window.ZHIFOU_ZHENGBIAN={"hook":"中国历史上，权力是怎样一夜易手、又怎样被百姓掀翻的？","answer":"这一页按事件讲：47个政变、权力斗争与起义，每个事件一张卡——起因、经过、结果，涉及的人物、都城，以及和战役的对应。","tags":["宫廷政变","兵变","权臣专权","外戚宦官","继位之争","党争","农民起义","宗教与会党","民变","改朝换代","关键转折"],"tagCount":{"宫廷政变":14,"兵变":3,"权臣专权":9,"外戚宦官":6,"继位之争":13,"党争":3,"农民起义":13,"宗教与会党":9,"民变":9,"改朝换代":9,"关键转折":16},"cityShow":{"临淄":"临淄","二里头":"偃师（二里头）","会宁":"阿城（金上京）","兴庆府":"银川","凤阳":"凤阳","北京（蓟、幽州、燕京、中都、大都、北平、京师）":"北京","南京（建业、建康、金陵、应天、天京）":"南京","咸阳":"咸阳","哈拉和林":"哈拉和林","大理":"大理","平城":"大同","开封（汴州、东京、大梁）":"开封","开平／元上都":"正蓝旗（元上都）","成都":"成都","新郑":"新郑","晋阳":"太原","曲阜":"曲阜","杭州（临安）":"杭州","殷墟":"安阳（殷墟）","沈阳":"沈阳","洛阳":"洛阳","渤海上京龙泉府":"宁安（渤海上京）","番禺":"广州","统万城":"靖边（统万城）","苏州（姑苏）":"苏州","荆州（郢、江陵）":"荆州","西安（丰镐、长安）":"西安","许昌":"许昌","赫图阿拉":"新宾（赫图阿拉）","辽上京":"巴林左旗（辽上京）","辽中京大定府":"宁城（辽中京）","辽阳":"辽阳","逻些（拉萨）":"拉萨","邯郸":"邯郸","邺城":"临漳（邺城）","郑州商城":"郑州","雍城":"凤翔（雍城）"},"intro":[{"t":"皇帝和朝廷的权力，有时在一夜之间易手，有时经过几代人的经营才转移到新家族。郑庄公与弟弟的封邑冲突、吕后死后的军权争夺、陈桥驿的军中拥立，都把个人安危、继承名分与统兵能力连在一起。另一类事件从乡里、戍所和宗教组织中发生，参与者聚众、立号、建政，再与官府和其他军队交战，逐步改变原有的政治局势。","s":["《左传·隐公元年》","《史记·卷9·吕太后本纪》","《宋史·卷1·太祖本纪一》","《史记·卷48·陈涉世家》","《后汉书·卷71·皇甫嵩朱儁列传》"]},{"t":"这四十七个事件，围绕政权存亡、权力格局和历史走向组织材料，分为政变与权力斗争、起义与民变两组。同组内按清单的时间线阅读，跨越数年的事件则追踪其发动、扩展、分裂和收束。宫门伏击、皇位废立、权臣专政与党争，呈现朝廷内部权力怎样移动；地方起事则呈现百姓、宗教组织和军人怎样在危机中聚集力量。","s":["《资治通鉴·卷191·唐纪七》","《后汉书·卷67·党锢列传》","《宋史·卷472·蔡京传》","《史记·卷48·陈涉世家》"]},{"t":"“政变”“兵变”“起义”“民变”是组织这页材料的分类。古书往往称相关行动为“反”“叛”“乱”，称对抗朝廷的队伍为“贼”“寇”，这些字带有王朝与编史者的立场。同一支队伍也可能先受招安、再被追剿，或在建政后取得另一套名号。阅读时既看史书如何称呼，也看人物实际做了什么、谁掌握兵粮与诏令。","s":["《史记·卷48·陈涉世家》","《后汉书·卷71·皇甫嵩朱儁列传》","《旧唐书·卷200下·黄巢传》"]},{"t":"《战役》页讲一场仗如何进行，这页讲一个事件为何发生、怎样发展及最后留下什么。黄巢攻入长安、李自成进入北京等具体攻城经过，由对应战役卡展开；这里把它们放回起事、流动、建政和失败的长线之中。人物与都城字段又把事件接回各朝代页面，便于顺着同一人或同一座城市继续阅读。","s":["《旧唐书·卷200下·黄巢传》","《明史·卷309·流贼传》"]},{"t":"每张卡取一至三个标签，同一事件可以同时涉及继位、宫廷行动或宗教组织。“改朝换代”用于直接取代旧政权或促成新政权建立的事件，卡中写明变化对象。年月以史书所用旧历为基础，出现公历换算时另行说明；坐标均为区域示意。分歧与数字口径集中放在史料说明，未解决的问题以红色待核标出。","s":["《史记·卷46·田敬仲完世家》","《汉书·卷99中·王莽传中》","《宋史·卷1·太祖本纪一》"]}],"table":[{"name":"郑伯克段于鄢","short":"郑伯克段","time":"前722","place":"河南新郑、荥阳、鄢陵","people":"郑庄公、共叔段、武姜","result":"共叔段败走，庄公保住君位","tags":["继位之争","关键转折"],"line":"郑庄公出兵击败扩张封邑的弟弟共叔段，郑国的继位矛盾由此发展为公开冲突。","s":["《左传·隐公元年》"]},{"name":"三家分晋","short":"三家分晋","time":"前453—前403","place":"山西太原；河南洛阳","people":"赵襄子、韩康子、魏桓子","result":"三家灭智氏，后获诸侯名分","tags":["权臣专权","关键转折"],"line":"韩赵魏联手消灭智氏，逐步掌握晋国土地，后来获得周王室承认，成为独立诸侯。","s":["《史记·卷43·赵世家》","《资治通鉴·卷1·周纪一》"]},{"name":"田氏代齐","short":"田氏代齐","time":"前481—前386","place":"山东淄博临淄","people":"田常、田和、齐简公、齐康公","result":"田氏获齐侯名分，姜齐退居一城","tags":["权臣专权","改朝换代"],"line":"田氏从齐国大夫逐步掌握国政，杀君、控制城邑，最终取代姜氏取得齐侯名分。","s":["《史记·卷46·田敬仲完世家》"]},{"name":"沙丘之变（赵）","short":"沙丘之变（赵）","time":"前295","place":"河北邢台广宗一带","people":"赵武灵王、公子章、赵惠文王、李兑","result":"公子章被杀，武灵王困死","tags":["继位之争","宫廷政变"],"line":"赵武灵王退位后仍牵动储位之争，公子章起事失败，武灵王也在沙丘宫被围困死。","s":["《史记·卷43·赵世家》"]},{"name":"沙丘之谋与二世即位","short":"沙丘之谋","time":"前210","place":"河北邢台广宗一带；陕西咸阳","people":"赵高、李斯、秦二世、扶苏","result":"扶苏死，秦二世继位","tags":["宫廷政变","继位之争"],"line":"秦始皇巡行途中去世，赵高与李斯改动继位安排，扶苏自杀，胡亥回到咸阳即位。","s":["《史记·卷87·李斯列传》"]},{"name":"诛灭诸吕与文帝入继","short":"诛灭诸吕","time":"前180","place":"陕西西安；河南郑州荥阳","people":"周勃、陈平、刘章、吕产、吕禄","result":"吕氏被清除，代王入继","tags":["外戚宦官","继位之争"],"line":"吕后死后，功臣与刘氏宗室夺取京城兵权、清除吕氏，迎立代王，汉文帝由此即位。","s":["《史记·卷9·吕太后本纪》"]},{"name":"巫蛊之祸","short":"巫蛊之祸","time":"前91","place":"陕西西安、咸阳；河南三门峡","people":"汉武帝、刘据、江充、刘屈氂","result":"太子兵败自杀，卫皇后死","tags":["继位之争","关键转折"],"line":"巫蛊调查进入太子宫，刘据杀江充并调兵自救，长安交战后兵败，皇位继承受到冲击。","s":["《汉书·卷63·武五子传》","《汉书·卷45·蒯伍江息夫传》"]},{"name":"王莽篡汉","short":"王莽篡汉","time":"8","place":"陕西西安","people":"王莽、王政君、孺子婴","result":"西汉被取代，新朝建立","tags":["权臣专权","外戚宦官","改朝换代"],"line":"王莽从外戚辅政走向居摄，借符命与群臣劝进称帝，废止汉朝帝号，建立新朝。","s":["《汉书·卷99上·王莽传上》","《汉书·卷99中·王莽传中》"]},{"name":"党锢之祸","short":"党锢之祸","time":"166、169","place":"河南洛阳及各郡国","people":"李膺、范滂、陈蕃、窦武、宦官集团","result":"士人被捕杀或禁仕","tags":["党争","外戚宦官"],"line":"东汉朝廷两次大捕党人，把士人的交游与议政视为结党，禁仕和株连扩大到郡县。","s":["《后汉书·卷67·党锢列传》","《后汉书·卷69·窦何列传》"]},{"name":"董卓入京与废立","short":"董卓废立","time":"189","place":"河南洛阳","people":"何进、袁绍、张让、董卓、汉献帝","result":"何进与宦官败亡，董卓掌政","tags":["外戚宦官","权臣专权","宫廷政变"],"line":"何进谋诛宦官却被杀，京城军队追杀宦官，董卓乘乱入京废立皇帝，控制东汉朝廷。","s":["《后汉书·卷69·窦何列传》","《后汉书·卷72·董卓列传》"]},{"name":"高平陵之变","short":"高平陵之变","time":"249","place":"河南洛阳","people":"司马懿、司马师、曹爽、魏齐王","result":"曹爽集团被诛，司马氏掌权","tags":["宫廷政变","权臣专权"],"line":"司马懿趁皇帝与曹爽出城祭陵控制洛阳，曹爽交出兵权后被杀，曹魏权力格局改变。","s":["《晋书·卷1·宣帝纪》","《三国志·卷9·诸夏侯曹传》"]},{"name":"八王之乱","short":"八王之乱","time":"291—306","place":"河南洛阳；河北邺城；陕西西安","people":"贾南风、司马伦、司马冏、司马越等","result":"宗室相继败亡，朝廷受重创","tags":["宫廷政变","继位之争","关键转折"],"line":"西晋诸王先后借皇帝诏令和地方军队争夺朝政，废立与杀戮反复，中央统治不断削弱。","s":["《晋书·卷59·八王列传》","《晋书·卷31·后妃传上》","《晋书·卷4·惠帝纪》"]},{"name":"玄武门之变","short":"玄武门之变","time":"626","place":"陕西西安","people":"唐太宗、李建成、李元吉、唐高祖","result":"太宗立为太子，随后即位","tags":["宫廷政变","继位之争"],"line":"唐太宗在玄武门伏击并杀死李建成、李元吉，继而掌握朝政，唐高祖随后传位于他。","s":["《资治通鉴·卷191·唐纪七》"]},{"name":"神龙政变","short":"神龙政变","time":"705","place":"河南洛阳","people":"张柬之、唐中宗、武则天、张易之","result":"中宗复位，恢复唐国号","tags":["宫廷政变","继位之争","改朝换代"],"line":"张柬之等联结禁军入宫诛杀张氏兄弟，拥唐中宗复位，武周结束，唐朝国号恢复。","s":["《资治通鉴·卷207·唐纪二十三》"]},{"name":"唐隆之变与先天之变","short":"唐隆与先天之变","time":"710、713","place":"陕西西安","people":"唐玄宗、韦后、太平公主、唐睿宗","result":"韦后、太平公主先后败亡","tags":["宫廷政变","继位之争"],"line":"唐玄宗先与太平公主合作清除韦后，后来又先行除去公主一党，最终集中皇帝权力。","s":["《资治通鉴·卷209·唐纪二十五》","《资治通鉴·卷210·唐纪二十六》"]},{"name":"甘露之变","short":"甘露之变","time":"835","place":"陕西西安；陕西宝鸡凤翔","people":"唐文宗、李训、郑注、仇士良","result":"诛宦官失败，朝臣遭杀戮","tags":["宫廷政变","外戚宦官"],"line":"唐文宗与李训等谋除宦官，伏兵计划在宫中败露，神策军反击，皇帝受到更严控制。","s":["《资治通鉴·卷245·唐纪六十一》"]},{"name":"陈桥兵变","short":"陈桥兵变","time":"960","place":"河南开封及东北陈桥驿","people":"北宋太祖、赵普、后周恭帝","result":"后周被取代，宋朝建立","tags":["兵变","改朝换代"],"line":"北宋太祖领兵出京，在陈桥驿被部将拥立，随后返城接受后周禅位，建立宋朝政权。","s":["《宋史·卷1·太祖本纪一》"]},{"name":"新旧党争","short":"新旧党争","time":"1069—1127","place":"河南开封；河南洛阳","people":"王安石、司马光、章惇、蔡京","result":"新法反复，党籍整肃扩大","tags":["党争","关键转折"],"line":"北宋新法引发朝议分歧，皇位更替带动用人和政策反复，后来发展为党籍与政治清算。","s":["《宋史·卷327·王安石传》","《宋史·卷336·司马光传》","《宋史·卷472·蔡京传》"]},{"name":"元代皇位之争：南坡之变与天历之变","short":"元代皇位之争","time":"1323—1329","place":"内蒙古正蓝旗；北京","people":"元英宗、铁失、元文宗、元明宗、燕铁木儿","result":"英宗、明宗相继死，文宗复位","tags":["宫廷政变","继位之争","权臣专权"],"line":"元英宗在南坡被杀后，皇位再经两都争立与兄弟相继即位，燕铁木儿的权势随之扩大。","s":["《元史·卷28·英宗本纪二》","《元史·卷31·明宗本纪》","《元史·卷32·文宗本纪一》","《元史·卷33·文宗本纪二》"]},{"name":"胡惟庸案","short":"胡惟庸案","time":"1380","place":"江苏南京","people":"明太祖、胡惟庸、李善长","result":"胡惟庸被诛，丞相制度废除","tags":["权臣专权","关键转折"],"line":"明太祖以谋反罪诛胡惟庸，并撤去中书省与丞相，六部直接对皇帝负责，株连延续多年。","s":["《明史·卷308·胡惟庸传》","《明史·卷72·职官志一》"]},{"name":"夺门之变","short":"夺门之变","time":"1457","place":"北京","people":"明英宗、徐有贞、石亨、曹吉祥、于谦","result":"英宗复位，景泰帝被废","tags":["宫廷政变","继位之争"],"line":"景泰帝病重时，石亨等迎出南宫中的明英宗复位，随后处死于谦，朝廷人事重新洗牌。","s":["《明史·卷170·于谦传》","《明史·卷171·徐有贞、石亨传》"]},{"name":"魏忠贤专权与东林党争","short":"魏忠贤专权","time":"1620—1627","place":"北京；江苏无锡等地","people":"魏忠贤、杨涟、左光斗、明熹宗、明思宗","result":"魏忠贤自杀，依附者遭清算","tags":["外戚宦官","党争","权臣专权"],"line":"魏忠贤借皇帝宠信与厂卫权力打击东林士人，诏狱与党籍扩大，崇祯即位后清除其势力。","s":["《明史·卷305·宦官传二》","《明史·卷244·杨涟、左光斗传》","《明史·卷23·庄烈帝本纪一》"]},{"name":"康熙擒鳌拜","short":"康熙擒鳌拜","time":"1669","place":"北京","people":"清圣祖、鳌拜、索额图","result":"鳌拜被拘，辅臣势力受清理","tags":["权臣专权","宫廷政变"],"line":"康熙亲政后处置仍把持朝务的鳌拜，削夺官爵并禁锢，皇帝进一步收回辅政时期的权力。","s":["《清史稿·卷249·索尼苏克萨哈遏必隆鳌拜列传》"]},{"name":"九子夺嫡与雍正继位","short":"九子夺嫡","time":"1708—1723","place":"北京；河北承德一带","people":"清圣祖、清世宗、胤礽、胤禩、胤禵","result":"太子两废，雍正继位并改元","tags":["继位之争","关键转折"],"line":"康熙两废太子后，皇子与大臣卷入储位竞争，胤禛最终继位，次年改元雍正并整顿政务。","s":["《清史稿·卷220·诸王列传》","《清史稿·卷9·世宗本纪》"]},{"name":"辛酉政变","short":"辛酉政变","time":"1861","place":"河北承德；北京","people":"慈禧太后、慈安太后、奕訢、肃顺","result":"八大臣失势，两宫垂帘","tags":["宫廷政变","继位之争"],"line":"咸丰死后，两宫太后联合恭亲王清除赞襄政务大臣，建立垂帘听政与议政王并行的安排。","s":["《清史稿·卷214·后妃列传》","《清史稿·卷221·诸王列传》"]},{"name":"戊戌变法与戊戌政变","short":"戊戌政变","time":"1898","place":"北京","people":"清德宗、慈禧太后、康有为、谭嗣同","result":"变法中止，慈禧重新训政","tags":["宫廷政变","关键转折"],"line":"光绪推行新政引发朝廷权力冲突，慈禧重新训政，改革者被捕或出逃，多项新政随即撤销。","s":["《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃列传》","《清史稿·卷437·荣禄传》"]},{"name":"国人暴动","short":"国人暴动","time":"前841","place":"陕西西安西南","people":"周厉王、召公、周公","result":"厉王出奔，共和行政","tags":["民变","关键转折"],"line":"周厉王以严厉措施压制议论，国人起而攻王，厉王出奔彘，王朝进入共和行政时期。","s":["《史记·卷4·周本纪》"]},{"name":"陈胜吴广起义","short":"陈胜吴广","time":"前209","place":"安徽宿州；河南周口淮阳","people":"陈胜、吴广","result":"建立张楚，后遭秦军击败","tags":["农民起义","关键转折"],"line":"陈胜吴广在赴戍途中发动起事，号召各地反秦并建立张楚，秦朝统治由此陷入广泛危机。","s":["《史记·卷48·陈涉世家》"]},{"name":"绿林赤眉起义","short":"绿林赤眉","time":"17—27","place":"湖北；山东；河南；陕西","people":"王匡、王凤、樊崇、刘玄、刘盆子","result":"新朝覆亡，更始、赤眉后败","tags":["农民起义","改朝换代"],"line":"绿林与赤眉从地方起事发展成大军，绿林系统推立更始帝并推翻新朝，两军后来相继败亡。","s":["《后汉书·卷11·刘玄刘盆子列传》","《后汉书·卷1上·光武帝纪上》"]},{"name":"黄巾起义","short":"黄巾起义","time":"184","place":"河北、河南、山东等地","people":"张角、张宝、张梁、皇甫嵩、朱儁","result":"主要队伍被击败，地方战争持续","tags":["宗教与会党","农民起义","关键转折"],"line":"张角借太平道组织起事，东汉调动中央和地方军队镇压，主要首领败亡后各地仍有余部。","s":["《后汉书·卷71·皇甫嵩朱儁列传》"]},{"name":"孙恩卢循起义","short":"孙恩卢循","time":"399—411","place":"浙江、江苏、广东、越南北部","people":"孙恩、卢循、刘裕","result":"首领败亡，东晋渡过危机","tags":["宗教与会党","民变"],"line":"孙恩在东南沿海聚众起事，卢循继领余部并一度逼近建康，最终被刘裕等击败，退往交州。","s":["《晋书·卷100·孙恩卢循传》"]},{"name":"隋末农民战争","short":"隋末农民战争","time":"611—618","place":"山东、河南、河北、安徽等地","people":"翟让、李密、窦建德、杜伏威","result":"隋朝覆亡，各路政权继续争夺","tags":["农民起义","改朝换代"],"line":"隋末各地起事在征役与饥荒中扩展，瓦岗等势力冲击隋朝统治，隋亡后群雄仍继续争夺。","s":["《隋书·卷70·李密传》"]},{"name":"庞勋起义","short":"庞勋起义","time":"868—869","place":"广西桂林；江苏徐州","people":"庞勋、崔彦曾、康承训","result":"徐州失守，庞勋败死","tags":["兵变","民变"],"line":"徐州戍卒因归期拖延发动兵变，北返后占据徐州并与朝廷交战，唐廷调军镇压，庞勋败死。","s":["《资治通鉴·卷251·唐纪六十七》"]},{"name":"黄巢起义","short":"黄巢起义","time":"875—884","place":"山东、河南、广东、陕西等地","people":"王仙芝、黄巢、唐僖宗","result":"大齐失去长安，黄巢败亡","tags":["农民起义","关键转折"],"line":"王仙芝黄巢相继聚众起事，黄巢军纵贯南北并在长安建大齐，唐廷反攻后其政权瓦解。","s":["《旧唐书·卷200下·黄巢传》"]},{"name":"王小波李顺起义","short":"王小波李顺","time":"993—995","place":"四川成都、眉山等地","people":"王小波、李顺、王继恩","result":"成都政权覆灭，余部续战","tags":["农民起义","民变"],"line":"王小波以均贫富号召聚众，李顺继领并占据成都建立政权，宋军反攻破城，各地余部续战。","s":["《宋史·卷5·太宗本纪二》"]},{"name":"方腊起义","short":"方腊起义","time":"1120—1122","place":"浙江、安徽、江苏、江西","people":"方腊、童贯","result":"方腊被俘，余部陆续平定","tags":["宗教与会党","农民起义"],"line":"方腊在睦州起事后迅速扩展到江南多州，宋廷调兵反攻，方腊被俘后各处余部仍继续抵抗。","s":["《宋史·卷468·童贯传》"]},{"name":"钟相杨幺起义","short":"钟相杨幺","time":"1130—1135","place":"湖南常德、洞庭湖一带","people":"钟相、杨幺、岳飞","result":"钟相先死，杨幺部后被击败","tags":["宗教与会党","农民起义"],"line":"钟相起事失败后，杨幺等依托洞庭湖继续抵抗，南宋调岳飞招降与进攻，最终瓦解湖区势力。","s":["《宋史·卷365·岳飞传》"]},{"name":"红巾军起义","short":"红巾军起义","time":"1351—1368","place":"安徽、河南、湖北、江苏等地","people":"韩山童、刘福通、徐寿辉、朱元璋","result":"元失中原，明朝建立","tags":["农民起义","宗教与会党","改朝换代"],"line":"元末红巾各军相继起事，形成多个政权，朱元璋在争夺中建立明朝，元廷最终退出大都。","s":["《明史·卷1·太祖本纪一》"]},{"name":"邓茂七起义","short":"邓茂七","time":"1448—1449","place":"福建沙县、延平等地","people":"邓茂七、邓伯孙、张楷","result":"首领败亡，起事被镇压","tags":["农民起义","民变"],"line":"邓茂七在福建发动起事，抗拒官府并吸引各地响应，明廷调军围攻，首领相继败亡后局势平定。","s":["《明史·卷165·丁瑄传》"]},{"name":"刘六刘七起义","short":"刘六刘七","time":"1510—1512","place":"河北、山东、河南、江苏等地","people":"刘六、刘七、赵鐩、陆完","result":"各路队伍相继败亡","tags":["民变","关键转折"],"line":"刘六刘七在北方聚众起事，各路队伍转战数省，明廷调边军追剿，起事首领相继败亡。","s":["《明史·卷187·马中锡陆完传》"]},{"name":"明末农民战争","short":"明末农民战争","time":"1628—1645","place":"陕西、河南、北京、四川等地","people":"李自成、张献忠、明清诸将","result":"明北京朝廷覆亡，顺西政权兴起","tags":["农民起义","改朝换代"],"line":"明末起事从西北扩展，李自成与张献忠分别建政，明朝北京朝廷覆亡后，各军又与清军交战。","s":["《明史·卷309·流贼传》"]},{"name":"林爽文起义","short":"林爽文起义","time":"1786—1788","place":"台湾彰化、嘉义、台南等地","people":"林爽文、庄大田、福康安","result":"首领被俘，清廷恢复控制","tags":["宗教与会党","民变"],"line":"林爽文在台湾借天地会组织起事，庄大田在南部响应，清廷渡海增兵后俘获首领，恢复控制。","s":["《清史稿·卷330·福康安传》"]},{"name":"川楚白莲教起义","short":"川楚白莲教起义","time":"1796—1804","place":"湖北、四川、陕西等地","people":"王聪儿、姚之富、清军诸将","result":"主要队伍陆续被镇压","tags":["宗教与会党","农民起义"],"line":"白莲教各部在川楚陕聚众起事，清军长期追剿并动员地方团练，战争延续多年，耗费大量财政。","s":["《清史稿·卷344·勒保等传》"]},{"name":"太平天国运动","short":"太平天国运动","time":"1851—1864","place":"广西、湖南、江苏、安徽等地","people":"洪秀全、杨秀清、曾国藩","result":"天京失守，中央政权瓦解","tags":["宗教与会党","农民起义","关键转折"],"line":"洪秀全等在广西起事后建立太平天国并定都天京，内争与长期战争削弱实力，天京最终失守。","s":["《清史稿·卷475·洪秀全传》"]},{"name":"捻军起义","short":"捻军起义","time":"1851—1868","place":"安徽、河南、山东、湖北等地","people":"张乐行、赖文光、张宗禹、李鸿章","result":"东西捻军先后败亡","tags":["民变","关键转折"],"line":"淮北各路捻军在地方动荡中联合，后来与太平军余部合流，清军以围堵与追剿逐渐将其瓦解。","s":["《清史稿·卷411·李鸿章传》"]},{"name":"义和团运动","short":"义和团运动","time":"1899—1901","place":"山东、河北、北京、天津","people":"义和团各部、慈禧太后、清廷大臣","result":"联军入京，签订辛丑条约","tags":["宗教与会党","民变","关键转折"],"line":"义和团由地方冲突扩展到京津，清廷一度支持其行动，联军入京后转为镇压并承担条约赔款。","s":["《清史稿·卷465·徐桐等传》","《清史稿·卷214·后妃列传》"]},{"name":"武昌起义","short":"武昌起义","time":"1911—1912","place":"湖北武汉；江苏南京；北京","people":"黎元洪、孙中山、袁世凯、清宣统帝","result":"民国建立，清帝退位","tags":["兵变","改朝换代"],"line":"武昌新军起事后各省相继脱离清廷，南京建立中华民国，南北议和推动清帝退位，帝制结束。","s":["《清史稿·卷25·宣统皇帝本纪》"]}],"groups":[{"title":"政变与权力斗争","events":["郑伯克段于鄢","三家分晋","田氏代齐","沙丘之变（赵）","沙丘之谋与二世即位","诛灭诸吕与文帝入继","巫蛊之祸","王莽篡汉","党锢之祸","董卓入京与废立","高平陵之变","八王之乱","玄武门之变","神龙政变","唐隆之变与先天之变","甘露之变","陈桥兵变","新旧党争","元代皇位之争：南坡之变与天历之变","胡惟庸案","夺门之变","魏忠贤专权与东林党争","康熙擒鳌拜","九子夺嫡与雍正继位","辛酉政变","戊戌变法与戊戌政变"]},{"title":"起义与民变","events":["国人暴动","陈胜吴广起义","绿林赤眉起义","黄巾起义","孙恩卢循起义","隋末农民战争","庞勋起义","黄巢起义","王小波李顺起义","方腊起义","钟相杨幺起义","红巾军起义","邓茂七起义","刘六刘七起义","明末农民战争","林爽文起义","川楚白莲教起义","太平天国运动","捻军起义","义和团运动","武昌起义"]}],"events":[{"name":"郑伯克段于鄢","tags":["继位之争","关键转折"],"g":"通说","lat":34.2,"lon":113.9,"f":[{"k":"时间","v":"前722年，旧历五月。","s":["《左传·隐公元年》"]},{"k":"地点","v":"河南省新郑市、荥阳市、鄢陵县一带；古名郑、京、鄢。","s":["《左传·隐公元年》"]},{"k":"起因","v":"郑武公的夫人武姜偏爱幼子共叔段，多次请求让他继位，武公没有答应。庄公即位后，武姜又替共叔段索取封邑，先求制邑，未获允许，改求京邑。京的城制超过大邑应有的限度，祭仲担心这会损害国君权威，劝庄公尽早处置，庄公却选择等待。","s":["《左传·隐公元年》"]},{"k":"结果与影响","v":"共叔段失去京邑，出奔他国，郑庄公保住君位，郑国原有的权力中心得到恢复。但冲突并未停留在兄弟之间：共叔段一方的公孙滑逃到卫国，卫人随后出兵取廪延，郑国又联合其他力量报复，内争牵动了邻国关系。《左传》解释“克”字时说双方如同两个国君交战，也批评庄公未尽教导弟弟的责任，保留了对兄弟双方的不同责问。","s":["《左传·隐公元年》"]},{"k":"史料说明","v":"《左传》把共叔段的行动写作“不弟”，也以“郑伯”之称批评庄公。颍考叔调解母子的细节属于该书的叙事，未见当时留下的独立记录。","s":["《左传·隐公元年》"]}],"steps":[{"t":"武姜替共叔段求取京邑，庄公应允，共叔段因而被称为京城太叔。祭仲指出，大邑城墙有等级限制，京邑超过制度，长久下去会形成与国君竞争的力量。","s":["《左传·隐公元年》"]},{"t":"共叔段命郑国西部、北部的边邑同时听命于自己，公子吕提醒庄公，国内已出现两个权力中心。庄公没有立即出兵，仍让共叔段继续行动，朝臣的劝阻未改变他的决定。","s":["《左传·隐公元年》"]},{"t":"共叔段进一步把两属的边邑收入自己的领地，势力扩展到廪延。公子吕再次要求处置，庄公认为这种扩张会使共叔段失去支持，继续等待公开动兵的机会。","s":["《左传·隐公元年》"]},{"t":"共叔段修筑城防、积聚物资、整备甲兵，准备袭击郑都，武姜计划从城内接应。庄公获知行动日期，随即命公子吕率军攻京，把封邑矛盾转为公开的武装冲突。","s":["《左传·隐公元年》"]},{"t":"京邑的人转而背离共叔段，他退到鄢，庄公继续追击。五月，共叔段逃往共地，争夺郑国统治权的计划失败，庄公重新控制先前受到威胁的城邑。","s":["《左传·隐公元年》"]},{"t":"庄公把武姜安置到城颍，并发誓不见母亲，后来又后悔。《左传》接着记颍考叔劝解母子和好的故事，显示这场冲突也破坏了国君与母亲之间的关系。","s":["《左传·隐公元年》"]}],"who":[{"side":"发动方","t":"共叔段、武姜。","s":["《左传·隐公元年》"]},{"side":"对立方","t":"郑庄公、公子吕、祭仲。","s":["《左传·隐公元年》"]}],"cities":["新郑"],"people":["郑庄公","共叔段","武姜","祭仲","颍考叔"],"battles":[],"src":["《左传·隐公元年》"],"line":"郑庄公出兵击败扩张封邑的弟弟共叔段，郑国的继位矛盾由此发展为公开冲突。","group":"政变与权力斗争","short":"郑伯克段","timeShort":"前722","placeShort":"河南新郑、荥阳、鄢陵","peopleShort":"郑庄公、共叔段、武姜","result":"共叔段败走，庄公保住君位"},{"name":"三家分晋","tags":["权臣专权","关键转折"],"g":"通说","lat":37.8,"lon":112.5,"f":[{"k":"时间","v":"前453—前403。","s":["《史记·卷43·赵世家》","《资治通鉴·卷1·周纪一》"]},{"k":"地点","v":"山西省太原市、河南省洛阳市；古名晋阳、洛邑。","s":["《史记·卷43·赵世家》","《资治通鉴·卷1·周纪一》"]},{"k":"起因","v":"晋国的军政权力长期落在卿族手中，范氏、中行氏败亡后，其土地又被智、赵、韩、魏分取。智伯在四家中势力强盛，接连向韩、魏索地，两家暂时退让。赵襄子拒绝交地，智伯便联合韩、魏攻赵，赵襄子退守晋阳，四家之间的矛盾走到决裂。","s":["《史记·卷43·赵世家》","《资治通鉴·卷1·周纪一》"]},{"k":"结果与影响","v":"韩、赵、魏从晋国权臣转为获周王室承认的诸侯，三晋由此成为战国格局中的重要力量。前453年的灭智氏消除了共同对手，前403年的册命则改变三家的政治身份，两者相隔半个世纪。晋国公室仍保留部分领地，直至后来继续被瓜分，因此这一事件的终点代表诸侯名分确立。三家同时继承晋国的土地、军队与人才，开始分别展开争夺。","s":["《史记·卷43·赵世家》","《资治通鉴·卷1·周纪一》"]},{"k":"史料说明","v":"前453年指三家灭智氏，前403年指周王承认三家为诸侯。晋君的残余封地后来才被瓜分，《赵世家》与《资治通鉴》的记述层次各有侧重。","s":["《史记·卷43·赵世家》","《资治通鉴·卷1·周纪一》"]}],"steps":[{"t":"智伯联合韩、魏向赵氏施压，赵襄子带领部众进入晋阳。此前晋君已难以节制各卿族，决定局势的实际力量来自卿族掌握的封邑、家臣与军队。","s":["《史记·卷43·赵世家》","《资治通鉴·卷1·周纪一》"]},{"t":"联军围困晋阳，并以水灌城，赵氏处境日益危急。智伯企图先消灭赵氏，再分其土地，韩、魏虽然出兵协助，也担心赵氏覆亡后自己成为下一个目标。","s":["《史记·卷43·赵世家》","《资治通鉴·卷1·周纪一》"]},{"t":"赵襄子派张孟谈联络韩、魏，指出三家利益相连。韩、魏接受倒戈安排，围城同盟内部出现裂缝，赵氏得以把孤立防守转为与两家共同对付智氏。","s":["《史记·卷43·赵世家》","《资治通鉴·卷1·周纪一》"]},{"t":"前453年，韩、魏与赵氏合力击败智伯，智氏覆灭，三家分取其地。晋国内部能够与三家抗衡的另一大卿族被清除，国君继续保留名号，实际领土和军力已更为有限。","s":["《史记·卷43·赵世家》","《资治通鉴·卷1·周纪一》"]},{"t":"三家此后各自任用官员、经营城邑，并以独立力量参与诸侯关系。前403年，周威烈王正式承认韩、赵、魏为诸侯，原来的晋国卿族取得与其他诸侯相列的政治名分。","s":["《史记·卷43·赵世家》","《资治通鉴·卷1·周纪一》"]},{"t":"晋君的残余封地并未在前403年一并消失，三家后来继续瓜分晋地。《资治通鉴》以周王承认三家为开篇，司马光的议论把名分变化视为周代政治秩序瓦解的重要一步。","s":["《史记·卷43·赵世家》","《资治通鉴·卷1·周纪一》"]}],"who":[{"side":"发动方","t":"赵襄子、韩康子、魏桓子及三家后继者。","s":["《史记·卷43·赵世家》","《资治通鉴·卷1·周纪一》"]},{"side":"对立方","t":"智伯、晋国公室。","s":["《史记·卷43·赵世家》","《资治通鉴·卷1·周纪一》"]}],"cities":["晋阳","洛阳"],"people":["赵襄子","智伯","韩康子","魏桓子","周威烈王"],"battles":[],"src":["《史记·卷43·赵世家》","《资治通鉴·卷1·周纪一》"],"line":"韩赵魏联手消灭智氏，逐步掌握晋国土地，后来获得周王室承认，成为独立诸侯。","group":"政变与权力斗争","short":"三家分晋","timeShort":"前453—前403","placeShort":"山西太原；河南洛阳","peopleShort":"赵襄子、韩康子、魏桓子","result":"三家灭智氏，后获诸侯名分"},{"name":"田氏代齐","tags":["权臣专权","改朝换代"],"g":"通说","lat":36.8,"lon":118.3,"f":[{"k":"时间","v":"前481—前386。","s":["《史记·卷46·田敬仲完世家》"]},{"k":"地点","v":"山东省淄博市临淄区；古名临淄。","s":["《史记·卷46·田敬仲完世家》"]},{"k":"起因","v":"田氏原是齐国卿族，长期积累封邑与人望。《史记》记田乞以有利于百姓的粮食出入办法争取支持，又参与废立齐君。田常继承家业后，与同掌国政的监止相互排斥，双方都有自己的亲属和部众。齐简公未能在两家之间作出有效处置，宫廷冲突逐渐扩大。","s":["《史记·卷46·田敬仲完世家》"]},{"k":"结果与影响","v":"田和获立为齐侯，田氏政权取得周王室的承认，田齐由此取代姜齐在诸侯体系中的位置。这个转变经历田常杀君、田氏控制各邑、齐康公退居海边以及田和获得册命等阶段。前386年以后，姜齐最后一城仍短暂存在，到前379年齐康公死后才完全消失。齐国的国名和主要都邑继续沿用，统治宗族却已更换，田氏随后以新的齐国君主身份参与列国竞争。","s":["《史记·卷46·田敬仲完世家》"]},{"k":"史料说明","v":"前386年是田和被列为诸侯之年，姜齐最后封地的消失在前379年。《史记》所说简公被执于“徐州”，是古代齐地地名，与今江苏徐州市的对应关系不同。","s":["《史记·卷46·田敬仲完世家》"]}],"steps":[{"t":"田乞死后，田常继续经营田氏势力，与监止同任齐相。齐大夫御鞅提醒简公，两家矛盾已无法并存，简公没有采纳，齐国的最高权力因而处在激烈争夺中。","s":["《史记·卷46·田敬仲完世家》"]},{"t":"监止一方的子我与田氏发生冲突，田常得知对方准备清除田氏，带兄弟进入宫中。双方随后动兵，子我战败逃走，田氏部众追杀子我和监止，先除去朝中主要对手。","s":["《史记·卷46·田敬仲完世家》"]},{"t":"前481年，齐简公出逃后被田氏追上并杀死。田常另立简公的弟弟为齐平公，自己继续担任相，国君的废立和朝廷的实际权力都落在田氏控制之下。","s":["《史记·卷46·田敬仲完世家》"]},{"t":"为稳定局势，田常归还侵占鲁、卫的土地，与周边诸侯修好，并继续施惠国内。随后清除强大的公族和其他卿族，扩大田氏封邑，使自己的经济与军事基础超过齐君。","s":["《史记·卷46·田敬仲完世家》"]},{"t":"田盘继任后，让田氏亲属分别掌管齐国城邑，公室对地方的控制继续削弱。到田和时，齐康公被迁到海边，仅保留一城祭祀先祖，朝政与大部分土地已由田氏掌握。","s":["《史记·卷46·田敬仲完世家》"]},{"t":"田和通过魏国向周王室请求诸侯名分，前386年获立为齐侯。姜齐公室此后仍有残余封地，前379年齐康公去世，姜氏祭祀断绝，其最后土地也归田氏。","s":["《史记·卷46·田敬仲完世家》"]}],"who":[{"side":"发动方","t":"田常、田盘、田和。","s":["《史记·卷46·田敬仲完世家》"]},{"side":"对立方","t":"齐简公、齐康公及姜齐公室。","s":["《史记·卷46·田敬仲完世家》"]}],"cities":["临淄"],"people":["田常","田和","齐简公","齐康公"],"battles":[],"src":["《史记·卷46·田敬仲完世家》"],"line":"田氏从齐国大夫逐步掌握国政，杀君、控制城邑，最终取代姜氏取得齐侯名分。","group":"政变与权力斗争","short":"田氏代齐","timeShort":"前481—前386","placeShort":"山东淄博临淄","peopleShort":"田常、田和、齐简公、齐康公","result":"田氏获齐侯名分，姜齐退居一城"},{"name":"沙丘之变（赵）","tags":["继位之争","宫廷政变"],"g":"通说","lat":37.1,"lon":115.1,"f":[{"k":"时间","v":"前295年。","s":["《史记·卷43·赵世家》"]},{"k":"地点","v":"河北省邢台市广宗县一带；古名沙丘宫。","s":["《史记·卷43·赵世家》"]},{"k":"起因","v":"赵武灵王在前299年传位给年幼的赵惠文王，自称主父，仍率军经营北方。长子公子章未能继位，被封为代安阳君，对弟弟成为国君心怀不服。武灵王又怜惜长子，一度考虑分赵而王章，朝中对谁掌握最终权力的疑虑加深，辅佐幼王的肥义也察觉到危险。","s":["《史记·卷43·赵世家》"]},{"k":"结果与影响","v":"公子章争位失败被杀，支持他的田不礼也死去，赵惠文王保住君位。肥义在冲突初起时遇害，武灵王则从仍有政治影响的主父变成被围困的对象，最终死于自己退位后的权力斗争。公子成、李兑取得辅政地位，赵国朝廷不再承受主父、幼王与长子三方并存的压力。《史记》把传位后的父子关系、武灵王对长子的怜惜和章的不服相连记述，呈现储位调整留下的后患。","s":["《史记·卷43·赵世家》"]},{"k":"史料说明","v":"《史记》记主父被围三月余后饿死，具体宫址与今广宗县境内遗址的对应仍有定位讨论。坐标取沙丘所在区域。","s":["《史记·卷43·赵世家》"]}],"steps":[{"t":"武灵王传位后，肥义同时担任相国和赵惠文王的师傅，负责辅佐新君。武灵王仍以主父身份参与军事与国事，父子分别保有威望，继位并未使权力归属完全安定。","s":["《史记·卷43·赵世家》"]},{"t":"赵国灭中山后，武灵王封公子章为代安阳君，又让田不礼辅佐他。《史记》记武灵王看到长子向弟弟称臣时产生怜悯，想另给公子章王位，这使章一方仍抱有希望。","s":["《史记·卷43·赵世家》"]},{"t":"李兑警告肥义，公子章与田不礼可能借主父之名生事，劝肥义离开危险位置。肥义认为自己受托辅王，不肯退避，并安排信期保护惠文王，以防出现假传召命的情况。","s":["《史记·卷43·赵世家》"]},{"t":"前295年，主父与惠文王到沙丘，分住宫室。公子章、田不礼假借主父命令召王，肥义先去察看，被他们杀死，随后公子章一方与保护惠文王的力量发生冲突。","s":["《史记·卷43·赵世家》"]},{"t":"公子成、李兑从国都赶来救援，击败公子章，杀田不礼。公子章逃进主父所在宫中，主父收容了他；公子成、李兑于是围住宫室，并在其中杀死公子章。","s":["《史记·卷43·赵世家》"]},{"t":"公子成、李兑担心解围后因围攻主父获罪，继续封锁宫室，只让宫人离开。武灵王失去供给，最终困死；两人在确认他死亡后才发丧，赵惠文王的统治由此稳定下来。","s":["《史记·卷43·赵世家》"]}],"who":[{"side":"发动方","t":"公子章、田不礼。","s":["《史记·卷43·赵世家》"]},{"side":"对立方","t":"赵惠文王、肥义、公子成、李兑；赵武灵王后遭围困。","s":["《史记·卷43·赵世家》"]}],"cities":["邯郸"],"people":["赵武灵王","赵惠文王","肥义","李兑","公子章"],"battles":[],"src":["《史记·卷43·赵世家》"],"line":"赵武灵王退位后仍牵动储位之争，公子章起事失败，武灵王也在沙丘宫被围困死。","group":"政变与权力斗争","short":"沙丘之变（赵）","timeShort":"前295","placeShort":"河北邢台广宗一带","peopleShort":"赵武灵王、公子章、赵惠文王、李兑","result":"公子章被杀，武灵王困死"},{"name":"沙丘之谋与二世即位","tags":["宫廷政变","继位之争"],"g":"通说","lat":37.1,"lon":115.1,"f":[{"k":"时间","v":"前210年，始皇三十七年七月以后。","s":["《史记·卷87·李斯列传》"]},{"k":"地点","v":"河北省邢台市广宗县一带、陕西省咸阳市；古名沙丘平台、咸阳。","s":["《史记·卷87·李斯列传》"]},{"k":"起因","v":"秦始皇最后一次巡行时，胡亥、李斯、赵高随行，长子扶苏在上郡监军，蒙恬掌握边军。皇帝在旅途中病重，继承问题尚未向朝廷公开解决。赵高与胡亥关系密切，又曾得罪蒙氏；李斯担心失去相位，三人在始皇去世后的消息封锁中取得决定继位安排的机会。","s":["《史记·卷87·李斯列传》"]},{"k":"结果与影响","v":"秦二世取得皇位，扶苏及蒙氏兄弟失去生命，秦朝的最高权力转入胡亥、赵高与李斯组成的新格局。消息封锁、掌握印玺、伪造诏书和使者催迫，使未在现场的继承人及掌兵大臣难以及时核实。二世即位后扩大对宗室与旧臣的处置，宫廷中的相互防备进一步加深。李斯参与拥立，却未能长期保住地位，后来又被赵高排挤并处死，沙丘合作最终破裂。","s":["《史记·卷87·李斯列传》"]},{"k":"史料说明","v":"改诏与三人密谈的详细经过主要见《史记·李斯列传》。该书成于事件百余年后，长篇对话是史家保存的叙述，未留存可供逐字核对的诏书原件。","s":["《史记·卷87·李斯列传》"]}],"steps":[{"t":"前210年，秦始皇巡行途中病重，《史记》记他曾写信给扶苏，令其回咸阳参加丧葬。书信交赵高掌管，尚未送出，始皇便在沙丘平台去世，远方的扶苏仍不知情。","s":["《史记·卷87·李斯列传》"]},{"t":"李斯认为皇帝死在外地，消息传开会引起诸公子与各地变化，决定秘不发丧。随行队伍仍按皇帝在世时安排饮食、上奏，少数近臣因而独占了遗诏、印玺和传递消息的渠道。","s":["《史记·卷87·李斯列传》"]},{"t":"赵高先说动胡亥，再劝李斯加入改立计划，强调扶苏与蒙恬关系密切，若扶苏继位，李斯可能失去相位。李斯起初拒绝，后来接受，三人共同改动皇帝留下的继承安排。","s":["《史记·卷87·李斯列传》"]},{"t":"他们伪造诏书，立胡亥为太子，又以皇帝印玺发书，指责扶苏、蒙恬在边境无功且心怀怨望，命二人自杀。使者赶往上郡，把宫廷内的决定直接送到掌兵者面前。","s":["《史记·卷87·李斯列传》"]},{"t":"扶苏见书后准备自杀，蒙恬劝他复核诏令，指出一名使者带来的命令可能有诈。扶苏没有等待再请，自杀身亡；蒙恬拒绝立即自尽，随后被拘押，边军失去原有统帅。","s":["《史记·卷87·李斯列传》"]},{"t":"巡行队伍回到咸阳才正式发丧，胡亥即位为秦二世，赵高任郎中令。此后蒙毅、蒙恬先后被杀，诸公子与旧臣也遭清除，新君以刑罚和任用亲信巩固自己的统治。","s":["《史记·卷87·李斯列传》"]}],"who":[{"side":"发动方","t":"赵高、李斯、秦二世。","s":["《史记·卷87·李斯列传》"]},{"side":"对立方","t":"扶苏、蒙恬、蒙毅。","s":["《史记·卷87·李斯列传》"]}],"cities":["咸阳"],"people":["秦始皇","秦二世","赵高","李斯","扶苏","蒙恬","蒙毅"],"battles":[],"src":["《史记·卷87·李斯列传》"],"line":"秦始皇巡行途中去世，赵高与李斯改动继位安排，扶苏自杀，胡亥回到咸阳即位。","group":"政变与权力斗争","short":"沙丘之谋","timeShort":"前210","placeShort":"河北邢台广宗一带；陕西咸阳","peopleShort":"赵高、李斯、秦二世、扶苏","result":"扶苏死，秦二世继位"},{"name":"诛灭诸吕与文帝入继","tags":["外戚宦官","继位之争"],"g":"通说","lat":34.3,"lon":108.9,"f":[{"k":"时间","v":"前180年，旧历七月至后九月。","s":["《史记·卷9·吕太后本纪》"]},{"k":"地点","v":"陕西省西安市、河南省郑州市荥阳市；古名长安、荥阳。","s":["《史记·卷9·吕太后本纪》"]},{"k":"起因","v":"汉惠帝死后，吕后继续临朝，封吕氏亲属为王，并把京城南北军交给吕氏掌握。前180年吕后病重，又嘱咐吕产、吕禄据兵卫宫。她去世后，刘氏宗室担心吕氏改变皇位归属，功臣也害怕自身遭到清除，京城兵权与幼帝的继承资格成为双方争夺的核心。","s":["《史记·卷9·吕太后本纪》"]},{"k":"结果与影响","v":"吕氏失去兵权并遭大规模杀戮，汉文帝从代国入继，吕后时期建立的政治安排结束。功臣通过控制北军、宫门和皇帝印玺决定继位，刘氏宗室的外部出兵也影响了长安局势。新君仍属于刘氏皇室，汉朝国号和政权延续，变化发生在继承支系、外戚与功臣之间的权力分配。文帝即位后重组近侍与军政人事，参与迎立的大臣获得封赏，朝廷进入新的统治阶段。","s":["《史记·卷9·吕太后本纪》"]},{"k":"史料说明","v":"《史记》称诸吕谋乱，并记功臣以少帝等非惠帝亲子为废立理由。这些指控来自胜出者主持的政治处置，少帝身世缺少独立材料核验。","s":["《史记·卷9·吕太后本纪》"]}],"steps":[{"t":"吕后去世，吕产、吕禄继续掌握京城军队。刘章从吕氏婚姻关系中听到消息，联络齐王刘襄发兵，刘氏宗室从外部施压，陈平、周勃则在长安谋求控制宫廷和军队。","s":["《史记·卷9·吕太后本纪》"]},{"t":"齐王起兵后，朝廷派灌婴迎击，灌婴率军到荥阳便停下，与齐王及诸侯联络。他不愿为吕氏消灭宗室军队，决定等待京城变化，吕氏因此失去了原先期待的外援。","s":["《史记·卷9·吕太后本纪》"]},{"t":"周勃名为太尉，却一度无法进入北军。陈平、周勃利用郦寄与吕禄的私人关系，劝吕禄交出将印、返回封国，又通过掌符节的官员打开进入军营的通道。","s":["《史记·卷9·吕太后本纪》"]},{"t":"周勃进入北军后，要求军士以袒露哪一侧肩臂表明支持刘氏还是吕氏，军中选择刘氏。吕禄交出兵权，吕氏在京城的重要军事基础被夺走，双方力量随即逆转。","s":["《史记·卷9·吕太后本纪》"]},{"t":"吕产准备进入未央宫，受到阻挡。周勃派刘章带兵入宫，刘章追杀吕产；随后吕禄等也被捕杀，清除范围扩大到吕氏宗族男女，原有辅政集团被彻底打散。","s":["《史记·卷9·吕太后本纪》"]},{"t":"功臣另议皇位人选，以少帝等非惠帝亲子为由废除原有安排，迎立代王。代王派人查探后入长安，接受皇帝玺印，成为汉文帝；少帝及几位幼王随后被杀。","s":["《史记·卷9·吕太后本纪》"]}],"who":[{"side":"发动方","t":"周勃、陈平、刘章、刘襄、灌婴。","s":["《史记·卷9·吕太后本纪》"]},{"side":"对立方","t":"吕产、吕禄及吕氏宗族。","s":["《史记·卷9·吕太后本纪》"]}],"cities":["西安（丰镐、长安）"],"people":["吕后","汉文帝","周勃","陈平","刘章","刘襄","灌婴","吕产","吕禄"],"battles":[],"src":["《史记·卷9·吕太后本纪》"],"line":"吕后死后，功臣与刘氏宗室夺取京城兵权、清除吕氏，迎立代王，汉文帝由此即位。","group":"政变与权力斗争","short":"诛灭诸吕","timeShort":"前180","placeShort":"陕西西安；河南郑州荥阳","peopleShort":"周勃、陈平、刘章、吕产、吕禄","result":"吕氏被清除，代王入继"},{"name":"巫蛊之祸","tags":["继位之争","关键转折"],"g":"通说","lat":34.3,"lon":108.9,"f":[{"k":"时间","v":"前91年，征和二年七月至八月。","s":["《汉书·卷63·武五子传》","《汉书·卷45·蒯伍江息夫传》"]},{"k":"地点","v":"陕西省西安市、咸阳市及河南省三门峡市灵宝市一带；古名长安、甘泉、湖县。","s":["《汉书·卷63·武五子传》","《汉书·卷45·蒯伍江息夫传》"]},{"k":"起因","v":"汉武帝晚年对巫蛊诅咒极为敏感，朝廷接连查办，牵连丞相公孙贺父子、公主和卫氏亲属。江充负责调查，与太子刘据及卫氏有旧怨，担心太子日后继位报复。武帝在甘泉养病，太子和卫皇后留在长安，宫内外消息不畅，调查进入太子宫后，双方已难以正常沟通。","s":["《汉书·卷63·武五子传》","《汉书·卷45·蒯伍江息夫传》"]},{"k":"结果与影响","v":"刘据兵败身亡，卫皇后与太子家属大批死去，汉武帝长期安排的皇位继承被打断。武帝后来追究江充及有关人员，并对太子表达悔恨，仍无法恢复原来的储位体系。太子的孙子刘病已在狱中幸存，后来成为汉宣帝，巫蛊案的后果因此一直影响到昭宣时期的宗室关系。事件也显示，当皇帝与储君之间缺乏可靠传讯渠道时，司法调查、宫卫调动和继承恐惧可能迅速相互推高。","s":["《汉书·卷63·武五子传》","《汉书·卷45·蒯伍江息夫传》"]},{"k":"史料说明","v":"《汉书》把江充利用巫蛊构陷太子作为叙事主线，并保存为太子申冤的奏疏。所谓木偶“证据”由江充一方查出，后续处置与最初指控发生了明显逆转。","s":["《汉书·卷63·武五子传》","《汉书·卷45·蒯伍江息夫传》"]}],"steps":[{"t":"江充利用武帝对巫蛊的怀疑扩大搜索，进入宫中掘地查验，最后声称在太子宫发现木偶。前面已有皇亲因此获罪，刘据担心自己也无法说明，向少傅石德寻求办法。","s":["《汉书·卷63·武五子传》","《汉书·卷45·蒯伍江息夫传》"]},{"t":"石德提醒太子，皇帝在甘泉养病，消息不通，扶苏因一封诏书而死的前例值得警惕，建议先拘捕江充查明真相。太子接受建议，开始以持节使者的形式收捕调查人员。","s":["《汉书·卷63·武五子传》","《汉书·卷45·蒯伍江息夫传》"]},{"t":"前91年七月，太子一方拘捕江充，韩说怀疑使者有诈，拒绝受命而被杀，章赣带伤逃走。刘据又派人告知卫皇后，调取宫卫、车辆与武库兵器，公开指称江充作乱。","s":["《汉书·卷63·武五子传》","《汉书·卷45·蒯伍江息夫传》"]},{"t":"刘据杀江充后，朝中却传出太子谋反的消息。武帝命丞相刘屈氂统兵，长安百官与居民因惧怕皇帝追责，未普遍响应太子，争端发展为京城内部的军事冲突。","s":["《汉书·卷63·武五子传》","《汉书·卷45·蒯伍江息夫传》"]},{"t":"太子军与丞相军交战后失败，刘据逃离长安，卫皇后也在追究中自杀。太子躲到湖县民家，后被地方官发现，围捕时自杀，他的儿子也在逃亡与搜捕中死去。","s":["《汉书·卷63·武五子传》","《汉书·卷45·蒯伍江息夫传》"]},{"t":"壶关三老、田千秋等先后为太子申冤，武帝逐渐了解其中冤情，处置江充家属与诬陷者。朝廷后来修筑思子宫等以寄托哀思，但原有皇后、太子及其家族已经遭到毁灭性打击。","s":["《汉书·卷63·武五子传》","《汉书·卷45·蒯伍江息夫传》"]}],"who":[{"side":"发动方","t":"刘据、石德、卫皇后。","s":["《汉书·卷63·武五子传》","《汉书·卷45·蒯伍江息夫传》"]},{"side":"对立方","t":"江充、刘屈氂；汉武帝主持追捕。","s":["《汉书·卷63·武五子传》","《汉书·卷45·蒯伍江息夫传》"]}],"cities":["西安（丰镐、长安）"],"people":["汉武帝","刘据","江充","卫子夫","田千秋","汉宣帝"],"battles":[],"src":["《汉书·卷63·武五子传》","《汉书·卷45·蒯伍江息夫传》"],"line":"巫蛊调查进入太子宫，刘据杀江充并调兵自救，长安交战后兵败，皇位继承受到冲击。","group":"政变与权力斗争","short":"巫蛊之祸","timeShort":"前91","placeShort":"陕西西安、咸阳；河南三门峡","peopleShort":"汉武帝、刘据、江充、刘屈氂","result":"太子兵败自杀，卫皇后死"},{"name":"王莽篡汉","tags":["权臣专权","外戚宦官","改朝换代"],"g":"通说","lat":34.3,"lon":108.9,"f":[{"k":"时间","v":"8。","s":["《汉书·卷99上·王莽传上》","《汉书·卷99中·王莽传中》","《汉书·卷99下·王莽传下》"]},{"k":"地点","v":"陕西省西安市；古名长安，王莽即位后改常安。","s":["《汉书·卷99上·王莽传上》","《汉书·卷99中·王莽传中》","《汉书·卷99下·王莽传下》"]},{"k":"起因","v":"西汉末年皇帝屡在年幼时继位，王氏外戚长期进入朝廷中枢。王莽以王太后亲属身份出任大司马，经营节俭礼贤的声望，获得部分士人与官员支持。汉哀帝死后，他再度掌权，辅佐年幼的平帝，并把女儿立为皇后。平帝去世后，幼小的孺子婴又给了他继续摄政的条件。","s":["《汉书·卷99上·王莽传上》","《汉书·卷99中·王莽传中》","《汉书·卷99下·王莽传下》"]},{"k":"结果与影响","v":"王莽称帝取代西汉，新朝建立，汉朝皇室由统治者变成受封的前朝后裔。新政权试图借古制、符命与制度更张证明自身合法性，官名、爵位、货币等随之发生变化。王政君虽保留尊号，已无法阻止权力转移，孺子婴也没有获得亲自统治的机会。这个新王朝后来面对改革失序、灾荒和地方起事，于23年覆亡，刘氏复国力量随之重新争夺天下。","s":["《汉书·卷99上·王莽传上》","《汉书·卷99中·王莽传中》","《汉书·卷99下·王莽传下》"]},{"k":"史料说明","v":"《汉书》以汉朝立场称此为篡位，并把符命写作王莽集团制造的受命凭据。称帝发生在公元8年旧历十二月，换算公历跨入9年初，表中沿用8年的历史纪年。","s":["《汉书·卷99上·王莽传上》","《汉书·卷99中·王莽传中》","《汉书·卷99下·王莽传下》"]}],"steps":[{"t":"王莽先以外戚和大司马身份控制朝廷，借封赏、礼制议论与官员荐举巩固声望。汉平帝年幼，王政君居太皇太后之位，重大政务逐渐集中到王莽及其支持者手中。","s":["《汉书·卷99上·王莽传上》","《汉书·卷99中·王莽传中》","《汉书·卷99下·王莽传下》"]},{"t":"平帝去世，王莽选立年幼的刘婴为继承人，称孺子，自己按周公摄政的说法处理国政。群臣不断给他加号、增礼，摄政者与皇帝之间的仪式界限逐步缩小。","s":["《汉书·卷99上·王莽传上》","《汉书·卷99中·王莽传中》","《汉书·卷99下·王莽传下》"]},{"t":"泉陵侯刘庆等与翟义相继起兵反对王莽。翟义立刘信为天子，号召恢复刘氏统治；王莽调军击败反对力量，同时发布文告，宣称自己只是暂摄，将来会归政孺子。","s":["《汉书·卷99上·王莽传上》","《汉书·卷99中·王莽传中》","《汉书·卷99下·王莽传下》"]},{"t":"反对军队被击败后，王莽大封有功者，调整爵位名号。各地又连续上报符命祥瑞，把取代汉室解释为天命所归，官员和受赏者的劝进为他进一步称帝提供舆论。","s":["《汉书·卷99上·王莽传上》","《汉书·卷99中·王莽传中》","《汉书·卷99下·王莽传下》"]},{"t":"初始元年十二月，哀章制作并呈进金匮图书，称汉朝应当把帝位交给王莽。王莽接受符命，即真天子位，改国号为新，宣布改元始建国，原来的居摄身份就此结束。","s":["《汉书·卷99上·王莽传上》","《汉书·卷99中·王莽传中》","《汉书·卷99下·王莽传下》"]},{"t":"王莽尊王政君为新室文母太皇太后，把孺子婴封为定安公，并改变汉朝宗室与官爵安排。新朝随后陆续更改官名、货币与土地制度，受禅成为全面重建政治秩序的起点。","s":["《汉书·卷99上·王莽传上》","《汉书·卷99中·王莽传中》","《汉书·卷99下·王莽传下》"]}],"who":[{"side":"发动方","t":"王莽及支持其受禅的官员。","s":["《汉书·卷99上·王莽传上》","《汉书·卷99中·王莽传中》","《汉书·卷99下·王莽传下》"]},{"side":"对立方","t":"王政君、孺子婴及反对王莽的宗室。","s":["《汉书·卷99上·王莽传上》","《汉书·卷99中·王莽传中》","《汉书·卷99下·王莽传下》"]}],"cities":["西安（丰镐、长安）"],"people":["王莽","王政君","汉平帝","孺子婴","翟义"],"battles":[],"src":["《汉书·卷99上·王莽传上》","《汉书·卷99中·王莽传中》","《汉书·卷99下·王莽传下》"],"line":"王莽从外戚辅政走向居摄，借符命与群臣劝进称帝，废止汉朝帝号，建立新朝。","group":"政变与权力斗争","short":"王莽篡汉","timeShort":"8","placeShort":"陕西西安","peopleShort":"王莽、王政君、孺子婴","result":"西汉被取代，新朝建立"},{"name":"党锢之祸","tags":["党争","外戚宦官"],"g":"通说","lat":34.7,"lon":112.5,"f":[{"k":"时间","v":"166、169。","s":["《后汉书·卷67·党锢列传》","《后汉书·卷69·窦何列传》"]},{"k":"地点","v":"河南省洛阳市及东汉各郡国；古名雒阳。","s":["《后汉书·卷67·党锢列传》","《后汉书·卷69·窦何列传》"]},{"k":"起因","v":"东汉士人通过太学、乡里品评和官场交游形成声望网络，一些官员严办宦官亲属，与宫中势力冲突。宦官依靠皇帝近侍身份控制传达和奏事，双方又都希望影响用人。李膺追究与宦官相通的张成之子杀人案后，张成弟子牢修指控李膺等结党，朝廷把士人交游视为政治威胁。","s":["《后汉书·卷67·党锢列传》","《后汉书·卷69·窦何列传》"]},{"k":"结果与影响","v":"党锢使大批士人被杀、被迫逃亡或长期失去仕途，东汉选官体系与地方声望网络受到冲击。168年窦武、陈蕃败亡，又使宦官对宫廷的控制加强，士人难以通过正常朝议改变局势。184年解除禁锢是应对黄巾危机的政治调整，朝廷试图重新争取地方力量；但禁锢期间形成的仇怨及相互援救关系仍然存在，后来东汉末年的官员交游与政治选择都承受其影响。","s":["《后汉书·卷67·党锢列传》","《后汉书·卷69·窦何列传》"]},{"k":"史料说明","v":"“党人”是当时朝廷以结党罪名标识的一类士人，名单来自交游、举荐和政治指控。其内部没有近代政党那样统一的组织和纲领，《后汉书》则明显同情遭禁锢者。","s":["《后汉书·卷67·党锢列传》","《后汉书·卷69·窦何列传》"]}],"steps":[{"t":"166年，牢修上书指控李膺等收养太学游士、联结郡国生徒，彼此声援并议论朝廷。汉桓帝震怒，下令各地捕人，李膺、陈寔等被列入调查，第一次党锢由此开始。","s":["《后汉书·卷67·党锢列传》","《后汉书·卷69·窦何列传》"]},{"t":"窦武、霍谞等上书请求查明，朝廷在次年赦免被捕者，却仍令其归田，终身不得做官。士人没有恢复政治资格，“党人”的身份继续登记在朝廷，成为后来追捕的依据。","s":["《后汉书·卷67·党锢列传》","《后汉书·卷69·窦何列传》"]},{"t":"汉桓帝死后，窦武与陈蕃辅佐新朝，希望利用太后与辅政地位清除宦官。168年计划泄露，宦官控制幼帝和诏令，调兵反击，窦武、陈蕃及其支持者遭到杀戮。","s":["《后汉书·卷67·党锢列传》","《后汉书·卷69·窦何列传》"]},{"t":"169年，宦官利用张俭等案件再度追究党人，把地方官员的执法与士人的交游相互牵连。李膺、杜密、范滂等被捕，许多人死于狱中，第二次党锢比前次更为严厉。","s":["《后汉书·卷67·党锢列传》","《后汉书·卷69·窦何列传》"]},{"t":"禁锢范围随后扩大到门生、故吏、父子兄弟与一定范围的亲属，地方官也借机追责。有人逃亡、有人窝藏党人并承担风险，朝廷与地方士人之间的互不信任继续加深。","s":["《后汉书·卷67·党锢列传》","《后汉书·卷69·窦何列传》"]},{"t":"184年黄巾起事，朝廷担心党人与起事者合流，接受赦党建议，解除禁锢，允许被排斥者重新任职。两次大捕形成的伤亡与长期禁仕，却已深刻改变东汉官场和士人群体。","s":["《后汉书·卷67·党锢列传》","《后汉书·卷69·窦何列传》"]}],"who":[{"side":"发动方","t":"宦官集团及奉诏捕人的官府。","s":["《后汉书·卷67·党锢列传》","《后汉书·卷69·窦何列传》"]},{"side":"对立方","t":"李膺、范滂、杜密、陈蕃、窦武等。","s":["《后汉书·卷67·党锢列传》","《后汉书·卷69·窦何列传》"]}],"cities":["洛阳"],"people":["汉桓帝","汉灵帝","李膺","范滂","陈蕃","窦武","杜密","陈寔"],"battles":[],"src":["《后汉书·卷67·党锢列传》","《后汉书·卷69·窦何列传》"],"line":"东汉朝廷两次大捕党人，把士人的交游与议政视为结党，禁仕和株连扩大到郡县。","group":"政变与权力斗争","short":"党锢之祸","timeShort":"166、169","placeShort":"河南洛阳及各郡国","peopleShort":"李膺、范滂、陈蕃、窦武、宦官集团","result":"士人被捕杀或禁仕"},{"name":"董卓入京与废立","tags":["外戚宦官","权臣专权","宫廷政变"],"g":"通说","lat":34.7,"lon":112.5,"f":[{"k":"时间","v":"189。","s":["《后汉书·卷69·窦何列传》","《后汉书·卷72·董卓列传》"]},{"k":"地点","v":"河南省洛阳市及北郊；古名雒阳、北芒。","s":["《后汉书·卷69·窦何列传》","《后汉书·卷72·董卓列传》"]},{"k":"起因","v":"汉灵帝死后，何太后临朝，兄长何进辅政，宫中宦官与外戚都希望控制新君和禁军。何进杀蹇硕后，与袁绍商议全面清除宦官，何太后却不愿同意。何进迟疑未决，采纳召外军入京施压的办法，董卓等地方将领因而得到接近京城政治中心的机会。","s":["《后汉书·卷69·窦何列传》","《后汉书·卷72·董卓列传》"]},{"k":"结果与影响","v":"何进与宫廷宦官先后败亡，原来围绕幼帝争权的两大集团都被摧毁，董卓凭军队接管中央政务。汉少帝被废，汉献帝在董卓控制下即位，皇帝与百官失去独立处置局势的能力。何进召外兵本为解决宫中矛盾，却使地方统兵者直接介入废立。各地随后以讨董卓为号召组织军队，东汉中央与地方之间的军事关系进一步破裂，朝廷又在胁迫中西迁长安。","s":["《后汉书·卷69·窦何列传》","《后汉书·卷72·董卓列传》"]},{"k":"史料说明","v":"《后汉书》分别从何进与董卓的传记交代同一轮政局变化。宫中宦官被杀、董卓吞并部队及废立是前后相接的多个阶段，参与各方的目标并不相同。","s":["《后汉书·卷69·窦何列传》","《后汉书·卷72·董卓列传》"]}],"steps":[{"t":"189年，汉灵帝去世，何进避开蹇硕设下的威胁，拥立刘辩为帝，何太后临朝。何进随后杀蹇硕并接收其部队，与袁绍联结朝中士人，准备进一步清除宫中宦官。","s":["《后汉书·卷69·窦何列传》","《后汉书·卷72·董卓列传》"]},{"t":"何太后认为宫廷仍需宦官服侍，不愿全面诛杀。何进与袁绍于是召董卓等率军进京，试图以外兵威胁太后；朝廷内部的分歧尚未解决，地方军队已开始向洛阳移动。","s":["《后汉书·卷69·窦何列传》","《后汉书·卷72·董卓列传》"]},{"t":"宦官得知自身危险，假传太后命召何进入宫，将他杀死。何进部众与袁绍、袁术等随即反击，焚烧宫门并追杀宦官，原先谋划的有控制的清除迅速变成京城混战。","s":["《后汉书·卷69·窦何列传》","《后汉书·卷72·董卓列传》"]},{"t":"张让、段珪等挟持少帝与陈留王离宫北走，后来在追兵压力下败亡。董卓接近洛阳时得知皇帝在北芒，带兵奉迎回宫，借护送天子进入了宫廷与朝廷的中心。","s":["《后汉书·卷69·窦何列传》","《后汉书·卷72·董卓列传》"]},{"t":"董卓原有兵力有限，却以军队反复出入制造援兵不断的声势，又吞并何进旧部。吕布杀丁原后归附，董卓进一步控制京师军力，朝臣已经难以在军事上与之对抗。","s":["《后汉书·卷69·窦何列传》","《后汉书·卷72·董卓列传》"]},{"t":"董卓召集大臣议废立，以陈留王较为聪慧为由，废少帝为弘农王，立陈留王为汉献帝。何太后被迁出宫并遭杀害，董卓自任高位，重要官员的去留也受他支配。","s":["《后汉书·卷69·窦何列传》","《后汉书·卷72·董卓列传》"]}],"who":[{"side":"发动方","t":"何进、袁绍先谋诛宦官；董卓随后夺权。","s":["《后汉书·卷69·窦何列传》","《后汉书·卷72·董卓列传》"]},{"side":"对立方","t":"张让等宦官；董卓入京后对立于汉少帝、何太后。","s":["《后汉书·卷69·窦何列传》","《后汉书·卷72·董卓列传》"]}],"cities":["洛阳"],"people":["汉灵帝","汉献帝","何进","何太后","袁绍","袁术","张让","董卓","吕布"],"battles":[],"src":["《后汉书·卷69·窦何列传》","《后汉书·卷72·董卓列传》"],"line":"何进谋诛宦官却被杀，京城军队追杀宦官，董卓乘乱入京废立皇帝，控制东汉朝廷。","group":"政变与权力斗争","short":"董卓废立","timeShort":"189","placeShort":"河南洛阳","peopleShort":"何进、袁绍、张让、董卓、汉献帝","result":"何进与宦官败亡，董卓掌政"},{"name":"高平陵之变","tags":["宫廷政变","权臣专权"],"g":"通说","lat":34.7,"lon":112.5,"f":[{"k":"时间","v":"249。","s":["《晋书·卷1·宣帝纪》","《三国志·卷9·诸夏侯曹传》"]},{"k":"地点","v":"河南省洛阳市及南郊；古名洛阳、高平陵、洛水浮桥。","s":["《晋书·卷1·宣帝纪》","《三国志·卷9·诸夏侯曹传》"]},{"k":"起因","v":"魏明帝临终托孤，曹爽与司马懿共同辅佐幼帝曹芳。曹爽逐渐任用何晏、丁谧等亲信，控制中枢与禁军，司马懿则以太傅身份退居，后来称病不问政事。两家同为受遗辅政大臣，却在兵权、官员任用和皇帝周围的影响上相互排斥，表面平静下的防备不断加深。","s":["《晋书·卷1·宣帝纪》","《三国志·卷9·诸夏侯曹传》"]},{"k":"结果与影响","v":"司马懿控制曹魏中枢，曹爽及其主要支持者被诛，原先两家共同辅政的格局结束。魏齐王仍在位，曹魏国号也继续使用，皇帝身边的军政决定却转入司马氏掌握。司马懿死后，司马师、司马昭先后延续这一权力基础，经过后来的废立与战争，司马炎最终代魏建晋。高平陵夺权因此是司马氏掌权的重要起点，后续改朝换代经历了更长的政治过程。","s":["《晋书·卷1·宣帝纪》","《三国志·卷9·诸夏侯曹传》"]},{"k":"史料说明","v":"《晋书》在尊司马懿为宣帝的框架下记事，同时保存其传言只免曹爽官职而后诛族的经过；《三国志》及裴注也记曹爽案，评价与细节可互相参看。","s":["《晋书·卷1·宣帝纪》","《三国志·卷9·诸夏侯曹传》"]}],"steps":[{"t":"曹爽担任大将军，兄弟分别掌握禁军，任用亲近者占据朝中要职。司马懿称病退处，曹爽一方派李胜探望，《晋书》记司马懿故意表现得衰弱昏乱，使对方降低戒备。","s":["《晋书·卷1·宣帝纪》","《三国志·卷9·诸夏侯曹传》"]},{"t":"249年正月，魏齐王出城拜谒魏明帝高平陵，曹爽兄弟随行。司马懿抓住他们同时离开洛阳的时机，奏请郭太后罢免曹爽兄弟，以太后命令作为行动依据。","s":["《晋书·卷1·宣帝纪》","《三国志·卷9·诸夏侯曹传》"]},{"t":"司马师率兵守司马门，司马懿控制宫门与京城要处，又派高柔、王观分别接收曹爽、曹羲的军营。曹爽在城中的部队和官署先后落入对手控制，无法立即从京城取得增援。","s":["《晋书·卷1·宣帝纪》","《三国志·卷9·诸夏侯曹传》"]},{"t":"司马懿率蒋济等到洛水浮桥，向皇帝上奏曹爽擅权之罪。曹爽暂扣奏章，在伊水南停留，砍树设置障碍并调兵自守，皇帝与随行官员因而停在城外，等待双方交涉。","s":["《晋书·卷1·宣帝纪》","《三国志·卷9·诸夏侯曹传》"]},{"t":"桓范逃出洛阳，劝曹爽带皇帝去许昌，号召各地兵马。曹爽不肯采用，转而派陈泰等探听条件；司马懿传达只免官的意思，曹爽希望保住侯爵与家产，最终交出兵权随帝返城。","s":["《晋书·卷1·宣帝纪》","《三国志·卷9·诸夏侯曹传》"]},{"t":"曹爽投降后，朝廷以张当供词牵出曹爽、何晏等谋反案，逮捕曹爽兄弟与其支持者并杀戮宗族。此前的免官承诺没有成为最终处置，曹爽集团从中枢彻底消失。","s":["《晋书·卷1·宣帝纪》","《三国志·卷9·诸夏侯曹传》"]}],"who":[{"side":"发动方","t":"司马懿、司马师、蒋济、高柔、王观。","s":["《晋书·卷1·宣帝纪》","《三国志·卷9·诸夏侯曹传》"]},{"side":"对立方","t":"曹爽、曹羲、曹训、何晏等；魏齐王在出城行列中。","s":["《晋书·卷1·宣帝纪》","《三国志·卷9·诸夏侯曹传》"]}],"cities":["洛阳"],"people":["魏齐王","司马懿","司马师","曹爽","何晏","桓范","蒋济"],"battles":[],"src":["《晋书·卷1·宣帝纪》","《三国志·卷9·诸夏侯曹传》"],"line":"司马懿趁皇帝与曹爽出城祭陵控制洛阳，曹爽交出兵权后被杀，曹魏权力格局改变。","group":"政变与权力斗争","short":"高平陵之变","timeShort":"249","placeShort":"河南洛阳","peopleShort":"司马懿、司马师、曹爽、魏齐王","result":"曹爽集团被诛，司马氏掌权"},{"name":"八王之乱","tags":["宫廷政变","继位之争","关键转折"],"g":"通说","lat":34.7,"lon":112.5,"f":[{"k":"时间","v":"291—306。","s":["《晋书·卷59·八王列传》","《晋书·卷31·后妃传上》","《晋书·卷4·惠帝纪》"]},{"k":"地点","v":"河南省洛阳市、河北省邯郸市临漳县、陕西省西安市；古名洛阳、邺、长安。","s":["《晋书·卷59·八王列传》","《晋书·卷31·后妃传上》","《晋书·卷4·惠帝纪》"]},{"k":"起因","v":"晋武帝死后，晋惠帝即位，外戚杨骏先控制朝政，皇后贾南风希望夺回宫中权力。西晋诸王拥有封国、军队或都督职位，能够以保护皇帝、惩办权臣为名调动兵力。皇帝诏令与宫廷名分因此成为各派争夺的工具，最初的外戚与皇后冲突逐渐引出宗室诸王接连介入。","s":["《晋书·卷59·八王列传》","《晋书·卷31·后妃传上》","《晋书·卷4·惠帝纪》"]},{"k":"结果与影响","v":"参与争夺的诸王多数败亡，司马越最后控制朝廷，但西晋中央已在反复废立、迁帝与调兵中遭到重创。宫廷安全依靠地方统兵者，地方将领又以拥护皇帝为名扩大自身权力，皇帝越来越难以独立作决定。各地军事集团、流民武装与边疆势力趁势发展，随后永嘉危机进一步扩大。八王之乱的结束只标志这轮宗室争权告一段落，朝廷所面对的军事与社会危机仍在延续。","s":["《晋书·卷59·八王列传》","《晋书·卷31·后妃传上》","《晋书·卷4·惠帝纪》"]},{"k":"史料说明","v":"“八王”来自《晋书》将相关诸王合为一卷的叙述，实际参与者还包括皇后、外戚及众多统兵者。291年的宫廷清除与300年以后扩大化的宗室战争之间，存在数年的间隔。","s":["《晋书·卷59·八王列传》","《晋书·卷31·后妃传上》","《晋书·卷4·惠帝纪》"]}],"steps":[{"t":"291年，贾南风联络楚王司马玮等清除杨骏，汝南王司马亮与卫瓘参与辅政。随后贾后借司马玮之兵杀司马亮、卫瓘，又以司马玮假诏为罪处死他，宫廷控制权回到贾后手中。","s":["《晋书·卷59·八王列传》","《晋书·卷31·后妃传上》","《晋书·卷4·惠帝纪》"]},{"t":"贾后掌权期间，太子司马遹成为继承问题的焦点。她先废太子，300年又使人将其杀死；赵王司马伦与孙秀借为太子复仇发动政变，废杀贾后，接收朝政。","s":["《晋书·卷59·八王列传》","《晋书·卷31·后妃传上》","《晋书·卷4·惠帝纪》"]},{"t":"301年，司马伦进一步废晋惠帝，自立为帝。齐王司马冏、成都王司马颖、河间王司马颙等以恢复惠帝为号召举兵，司马伦很快败亡，惠帝复位，司马冏进入中枢掌权。","s":["《晋书·卷59·八王列传》","《晋书·卷31·后妃传上》","《晋书·卷4·惠帝纪》"]},{"t":"司马冏执政后又与诸王失和，长沙王司马乂在洛阳起兵，除掉司马冏。随后司马颖与司马颙联手围逼洛阳，东海王司马越在城内倒向对方，司马乂被交出并遭杀害。","s":["《晋书·卷59·八王列传》","《晋书·卷31·后妃传上》","《晋书·卷4·惠帝纪》"]},{"t":"司马颖取得优势后，皇帝一度亲征邺城却失败，惠帝被带到邺。并州、幽州等力量随后介入，司马颖又失势，司马颙部将张方控制皇帝并把他迁往长安，朝廷实际驻地不断改变。","s":["《晋书·卷59·八王列传》","《晋书·卷31·后妃传上》","《晋书·卷4·惠帝纪》"]},{"t":"司马越再联合东方军队反对司马颙，最终取得上风，306年迎惠帝回洛阳。司马颖等相继遭清除，司马越成为主要掌权者，长达十余年的宗室争夺留下破败的都城和分散的军事力量。","s":["《晋书·卷59·八王列传》","《晋书·卷31·后妃传上》","《晋书·卷4·惠帝纪》"]}],"who":[{"side":"发动方","t":"贾南风及先后结盟的司马伦、司马冏、司马颖、司马颙、司马越等。","s":["《晋书·卷59·八王列传》","《晋书·卷31·后妃传上》","《晋书·卷4·惠帝纪》"]},{"side":"对立方","t":"杨骏、太子司马遹及各阶段的对立诸王。","s":["《晋书·卷59·八王列传》","《晋书·卷31·后妃传上》","《晋书·卷4·惠帝纪》"]}],"cities":["洛阳","邺城","西安（丰镐、长安）"],"people":["西晋惠帝","贾南风","杨骏","司马伦","司马亮","司马玮","司马冏","司马乂","司马颖","司马颙","司马越"],"battles":["永嘉之乱与洛阳陷落"],"src":["《晋书·卷59·八王列传》","《晋书·卷31·后妃传上》","《晋书·卷4·惠帝纪》"],"line":"西晋诸王先后借皇帝诏令和地方军队争夺朝政，废立与杀戮反复，中央统治不断削弱。","group":"政变与权力斗争","short":"八王之乱","timeShort":"291—306","placeShort":"河南洛阳；河北邺城；陕西西安","peopleShort":"贾南风、司马伦、司马冏、司马越等","result":"宗室相继败亡，朝廷受重创"},{"name":"玄武门之变","tags":["宫廷政变","继位之争"],"g":"通说","lat":34.3,"lon":108.9,"f":[{"k":"时间","v":"626年，旧历六月初四发动，八月传位。","s":["《资治通鉴·卷191·唐纪七》"]},{"k":"地点","v":"陕西省西安市；古名长安太极宫玄武门。","s":["《资治通鉴·卷191·唐纪七》"]},{"k":"起因","v":"唐朝建国战争中，秦王唐太宗统领军队立下重要战功，太子李建成则保有法定继承地位。双方各有僚属与兵力，又都试图争取唐高祖支持，齐王李元吉站在太子一边。洛阳行台去留、东宫与秦府用人以及北征统兵安排接连引发冲突，兄弟已把对方视为自身安全和继位的威胁。","s":["《资治通鉴·卷191·唐纪七》"]},{"k":"结果与影响","v":"李建成、李元吉及其诸子被杀，太子一系失去继承机会，唐太宗先成为太子，随后即皇帝位。宫门伏击的胜利通过控制禁军、取得皇帝诏令和调整官员迅速转化为统治权。唐朝国号延续，皇位从唐高祖传到原来的秦王一支。魏徵等曾在东宫任职者后来仍被任用，新的君臣关系逐渐建立；但这场政变造成的亲族杀戮及对皇帝的军事压力，也始终是理解继位过程的重要部分。","s":["《资治通鉴·卷191·唐纪七》"]},{"k":"史料说明","v":"太子一方毒酒、预谋杀秦王等细节见《资治通鉴》所汇唐代史料，传世叙事主要经过胜出一方主持的国史体系。双方的秘密动机与逐字对话缺少各自独立留下的完整记录。","s":["《资治通鉴·卷191·唐纪七》"]}],"steps":[{"t":"太子李建成与秦王之间的矛盾日益公开，双方争取武将和近臣。唐高祖曾考虑让秦王去洛阳，后来又改变安排，秦府仍留长安，两个政治中心继续近距离对峙。","s":["《资治通鉴·卷191·唐纪七》"]},{"t":"626年，朝廷准备以李元吉统兵抵御突厥，并调秦府将领同行。秦府人员担心兵力被抽走，《资治通鉴》又记他们获知太子、齐王将加害秦王，长孙无忌等遂推动先行动手。","s":["《资治通鉴·卷191·唐纪七》"]},{"t":"秦王向唐高祖告发建成、元吉与后宫关系，要求次日入朝对质。同时秘密召回房玄龄、杜如晦，与尉迟敬德等作好部署，准备在宫城北门控制对方进入宫中的通道。","s":["《资治通鉴·卷191·唐纪七》"]},{"t":"六月初四，秦王率亲信伏在玄武门，建成、元吉入宫后察觉异常，准备返回。秦王追呼，随后射杀建成；元吉逃走并与秦王搏斗，尉迟敬德赶来将元吉杀死。","s":["《资治通鉴·卷191·唐纪七》"]},{"t":"东宫与齐府军队得知变故后进攻宫门，玄武门守军抵抗，双方一时仍在交战。尉迟敬德等展示建成、元吉已死，东宫军队失去主心骨，局势逐渐被秦王一方控制。","s":["《资治通鉴·卷191·唐纪七》"]},{"t":"尉迟敬德披甲入见唐高祖，传达秦王胜出的局面，唐高祖命诸军听秦王处置。建成、元吉诸子被杀，秦王被立为太子，军国大事先由他裁决，宫变随即落实为继位安排。","s":["《资治通鉴·卷191·唐纪七》"]},{"t":"同年八月，唐高祖正式传位，唐太宗即皇帝位，次年改元贞观。原东宫的一些官员后来得到重新任用，宫变后的统治在清除对手与吸纳其人员之间逐步形成。","s":["《资治通鉴·卷191·唐纪七》"]}],"who":[{"side":"发动方","t":"唐太宗、尉迟敬德、长孙无忌、房玄龄、杜如晦。","s":["《资治通鉴·卷191·唐纪七》"]},{"side":"对立方","t":"李建成、李元吉；唐高祖随后交出政务。","s":["《资治通鉴·卷191·唐纪七》"]}],"cities":["西安（丰镐、长安）"],"people":["唐高祖","唐太宗","李建成","李元吉","尉迟敬德","长孙无忌","房玄龄","杜如晦","魏徵"],"battles":[],"src":["《资治通鉴·卷191·唐纪七》"],"line":"唐太宗在玄武门伏击并杀死李建成、李元吉，继而掌握朝政，唐高祖随后传位于他。","group":"政变与权力斗争","short":"玄武门之变","timeShort":"626","placeShort":"陕西西安","peopleShort":"唐太宗、李建成、李元吉、唐高祖","result":"太宗立为太子，随后即位"},{"name":"神龙政变","tags":["宫廷政变","继位之争","改朝换代"],"g":"通说","lat":34.7,"lon":112.5,"f":[{"k":"时间","v":"705年，旧历正月发动，二月恢复唐号。","s":["《资治通鉴·卷207·唐纪二十三》"]},{"k":"地点","v":"河南省洛阳市；古名神都、迎仙宫。","s":["《资治通鉴·卷207·唐纪二十三》"]},{"k":"起因","v":"武则天晚年患病，张易之、张昌宗兄弟在宫中受宠，能够影响传达与用人，朝臣对两人的权势和安全威胁深感不安。皇太子唐中宗虽已回到洛阳，能否顺利继位仍取决于宫内局势。张柬之入相后联络朝臣与禁军将领，准备借清除张氏兄弟推动皇位归还李氏。","s":["《资治通鉴·卷207·唐纪二十三》"]},{"k":"结果与影响","v":"张氏兄弟被杀，武则天退位，唐中宗复位，武周政权结束，唐朝国号和李氏皇位得到恢复。政变由宰相、台谏官与禁军将领合作完成，太子为行动提供继承名分，宫中武力则使传位迅速落实。功臣随后受封，却未长期保持原有影响，唐中宗朝的后族与武氏势力仍参与争权。恢复唐号解决了当时的皇位归属，宫廷内部的势力竞争仍继续发展。","s":["《资治通鉴·卷207·唐纪二十三》"]},{"k":"史料说明","v":"武则天在位时沿用“神龙”年号，退位后中宗继续使用，政变因此得名。武周结束与唐朝恢复发生在同一轮传位中，母子名分及武则天的尊号则被保留。","s":["《资治通鉴·卷207·唐纪二十三》"]}],"steps":[{"t":"武则天病居迎仙宫，张氏兄弟出入左右，朝臣难以直接接近。宋璟等先后要求查办张昌宗，武则天仍加保护，常规司法与朝议未能削弱两人在宫中的地位。","s":["《资治通鉴·卷207·唐纪二十三》"]},{"t":"张柬之、崔玄暐等秘密联络羽林将领李多祚，另让桓彦范、敬晖掌握禁军职务。行动者一面争取军队，一面确认迎立太子的名分，把诛张氏与恢复李唐相联结。","s":["《资治通鉴·卷207·唐纪二十三》"]},{"t":"705年正月，张柬之等率羽林兵迎太子，太子起初迟疑，最终随军入宫。起事者突破宫门，进入张氏兄弟所在区域，先将张易之、张昌宗杀死，再控制皇帝居处。","s":["《资治通鉴·卷207·唐纪二十三》"]},{"t":"武则天得知变故，询问带兵者的用意，张柬之等表示奉太子清除张氏。她要求太子回东宫，众人坚持由太子留在宫中，朝廷政务实际上已经转交到新的一方。","s":["《资治通鉴·卷207·唐纪二十三》"]},{"t":"随后诏令太子监国，并正式传位，唐中宗恢复皇位。武则天迁居上阳宫，保留尊号；中宗率百官问安，宫变后的礼仪安排仍维持母子名分和退位君主的尊崇。","s":["《资治通鉴·卷207·唐纪二十三》"]},{"t":"中宗恢复唐国号，改回武周时期变更的部分官名、旗帜与制度称号，并封赏功臣。武周作为独立国号的统治结束，张柬之等希望以复位和禁军功劳稳住新的政治格局。","s":["《资治通鉴·卷207·唐纪二十三》"]}],"who":[{"side":"发动方","t":"张柬之、崔玄暐、桓彦范、敬晖、袁恕己、李多祚。","s":["《资治通鉴·卷207·唐纪二十三》"]},{"side":"对立方","t":"张易之、张昌宗；武则天随后退位。","s":["《资治通鉴·卷207·唐纪二十三》"]}],"cities":["洛阳"],"people":["武则天","唐中宗","张柬之","崔玄暐","桓彦范","敬晖","袁恕己","李多祚","张易之","张昌宗"],"battles":[],"src":["《资治通鉴·卷207·唐纪二十三》"],"line":"张柬之等联结禁军入宫诛杀张氏兄弟，拥唐中宗复位，武周结束，唐朝国号恢复。","group":"政变与权力斗争","short":"神龙政变","timeShort":"705","placeShort":"河南洛阳","peopleShort":"张柬之、唐中宗、武则天、张易之","result":"中宗复位，恢复唐国号"},{"name":"唐隆之变与先天之变","tags":["宫廷政变","继位之争"],"g":"通说","lat":34.3,"lon":108.9,"f":[{"k":"时间","v":"710年旧历六月、713年旧历七月。","s":["《资治通鉴·卷209·唐纪二十五》","《资治通鉴·卷210·唐纪二十六》"]},{"k":"地点","v":"陕西省西安市；古名长安、太极宫。","s":["《资治通鉴·卷209·唐纪二十五》","《资治通鉴·卷210·唐纪二十六》"]},{"k":"起因","v":"唐中宗朝，韦后与安乐公主广结亲信，太平公主与相王一系也有自己的政治力量。中宗去世后，韦后以太后身份控制新朝，唐玄宗当时仍是临淄王，与太平公主合作清除韦氏。唐睿宗复位后，太平公主依功干预宰相与禁军任用，又与成为太子的唐玄宗争夺对朝政的影响。","s":["《资治通鉴·卷209·唐纪二十五》","《资治通鉴·卷210·唐纪二十六》"]},{"k":"结果与影响","v":"710年韦后集团被清除，唐睿宗复位，唐玄宗取得太子地位；713年太平公主集团再被清除，唐玄宗才集中掌握朝政。两次行动的合作对象、对立方和皇位阶段均有变化，贯穿其中的是禁军、宰相任用与太上皇权限的争夺。公主败亡后，新帝能够独立部署人事与国策，开元时期的政治安排由此展开。唐朝皇统延续，掌政中心从多个皇室成员之间转向在位皇帝。","s":["《资治通鉴·卷209·唐纪二十五》","《资治通鉴·卷210·唐纪二十六》"]},{"k":"史料说明","v":"唐隆之变发生于710年，先天之变发生于713年，中间经历睿宗复位及传位玄宗。传世史书多从玄宗胜出后的立场叙述双方阴谋，太平公主一方留下的自述很少。","s":["《资治通鉴·卷209·唐纪二十五》","《资治通鉴·卷210·唐纪二十六》"]}],"steps":[{"t":"710年六月，唐中宗去世，韦后掌握政务，立少帝并把亲属安置在禁军等要职。相王一系面临威胁，临淄王唐玄宗联络刘幽求、禁军人员与太平公主方面，共同准备入宫。","s":["《资治通鉴·卷209·唐纪二十五》","《资治通鉴·卷210·唐纪二十六》"]},{"t":"唐玄宗一方利用禁军将士对韦氏统兵者的不满发动夜袭，先除掉控制军队的韦氏亲属，再进入宫中。韦后与安乐公主被杀，韦氏集团失去宫廷与军队的控制权。","s":["《资治通鉴·卷209·唐纪二十五》","《资治通鉴·卷210·唐纪二十六》"]},{"t":"少帝随后退位，唐睿宗恢复帝位，唐玄宗被立为太子。太平公主在此次行动中有功，频繁干预朝政和大臣任命，原来的合作关系逐渐转成太子与公主之间的竞争。","s":["《资治通鉴·卷209·唐纪二十五》","《资治通鉴·卷210·唐纪二十六》"]},{"t":"712年，唐睿宗传位给太子，唐玄宗即皇帝位，但太上皇仍保留部分大政决定权。太平公主依靠与太上皇的兄妹关系及宰相支持，继续影响朝廷，新帝尚未掌握全部权力。","s":["《资治通鉴·卷209·唐纪二十五》","《资治通鉴·卷210·唐纪二十六》"]},{"t":"713年，唐玄宗获知太平公主一方可能动兵，先召集亲信控制北门军队，处置常元楷、李慈等将领，又杀萧至忠、岑羲等支持公主的大臣，打断对方的行动基础。","s":["《资治通鉴·卷209·唐纪二十五》","《资治通鉴·卷210·唐纪二十六》"]},{"t":"太平公主逃亡后被赐死，相关党人与家属受到处置。唐睿宗把剩余军政权力交给唐玄宗，太上皇退居，皇帝得以重新安排宰相与禁军人事，先天之变就此结束。","s":["《资治通鉴·卷209·唐纪二十五》","《资治通鉴·卷210·唐纪二十六》"]}],"who":[{"side":"发动方","t":"唐玄宗；710年与太平公主、刘幽求等合作，713年与郭元振、高力士等行动。","s":["《资治通鉴·卷209·唐纪二十五》","《资治通鉴·卷210·唐纪二十六》"]},{"side":"对立方","t":"710年为韦后、安乐公主等；713年为太平公主及其支持者。","s":["《资治通鉴·卷209·唐纪二十五》","《资治通鉴·卷210·唐纪二十六》"]}],"cities":["西安（丰镐、长安）"],"people":["唐中宗","唐睿宗","唐玄宗","韦后","安乐公主","太平公主","刘幽求","郭元振","高力士"],"battles":[],"src":["《资治通鉴·卷209·唐纪二十五》","《资治通鉴·卷210·唐纪二十六》"],"line":"唐玄宗先与太平公主合作清除韦后，后来又先行除去公主一党，最终集中皇帝权力。","group":"政变与权力斗争","short":"唐隆与先天之变","timeShort":"710、713","placeShort":"陕西西安","peopleShort":"唐玄宗、韦后、太平公主、唐睿宗","result":"韦后、太平公主先后败亡"},{"name":"甘露之变","tags":["宫廷政变","外戚宦官"],"g":"通说","lat":34.3,"lon":108.9,"f":[{"k":"时间","v":"835年，旧历十一月。","s":["《资治通鉴·卷245·唐纪六十一》"]},{"k":"地点","v":"陕西省西安市、宝鸡市凤翔区；古名长安、凤翔。","s":["《资治通鉴·卷245·唐纪六十一》"]},{"k":"起因","v":"唐代后期宦官掌握神策军和宫中传达，皇帝与宰相都受到牵制。唐文宗希望恢复自主，先前借宋申锡谋除宦官已经失败，后来转而信任由宦官引进的李训、郑注。两人借皇帝支持迅速升迁，计划先分化宫中势力、削弱王守澄，再通过宫外军队和宫内伏兵消灭主要宦官。","s":["《资治通鉴·卷245·唐纪六十一》"]},{"k":"结果与影响","v":"谋除宦官的计划失败，李训、郑注身死，数位宰相及大量无辜者遭杀戮，朝廷外朝受到严重打击。唐文宗虽然仍是皇帝，宫门、禁军与传达渠道却更牢固地落入宦官之手，恢复皇权的尝试反而加重了受制局面。事件中原有的内外配合被提前行动打乱，李训与郑注的相互猜忌也影响部署。甘露之变此后成为唐代皇帝难以摆脱禁军宦官控制的突出事例。","s":["《资治通鉴·卷245·唐纪六十一》"]},{"k":"史料说明","v":"《资治通鉴》分别记长安与凤翔的杀戮，数字涵盖官员、家属、部众等不同对象。此处未把它们合并为一个精确总伤亡数，“甘露”则是发动伏击的名目。","s":["《资治通鉴·卷245·唐纪六十一》"]}],"steps":[{"t":"李训、郑注利用王守澄与仇士良之间的矛盾，建议提拔仇士良以分王守澄之权，又把其他宦官调往外地。表面上两人依靠宦官升迁，暗中则与唐文宗安排清除计划。","s":["《资治通鉴·卷245·唐纪六十一》"]},{"t":"郑注出任凤翔节度使，开始经营亲兵，原拟借王守澄葬礼集中宦官后动手。唐文宗先下令毒死王守澄，宫中强势人物被除掉，但神策军仍掌握在其他宦官手中。","s":["《资治通鉴·卷245·唐纪六十一》"]},{"t":"李训担心功劳落到郑注，又想在成功后排除他，决定提前行动。835年十一月，韩约以金吾厅后石榴树上有甘露为名奏报，诱使皇帝和宦官前往观看，伏兵藏在附近。","s":["《资治通鉴·卷245·唐纪六十一》"]},{"t":"仇士良等察觉韩约神色异常，又见帷幕后有人持兵，立即退回唐文宗身边。李训试图把皇帝留在外朝，宦官却把他抬入宫内，关门阻断外臣，宫内外的控制权随即分开。","s":["《资治通鉴·卷245·唐纪六十一》"]},{"t":"宦官调神策军冲出，杀入中书、门下等官署，李训逃走，王涯、贾餗、舒元舆等宰相被捕。追捕与杀戮蔓延到家属、部属及京城居民，很多并未参与密谋的人也受到牵连。","s":["《资治通鉴·卷245·唐纪六十一》"]},{"t":"李训在逃亡中死去，郑注得知失败后返回凤翔，又被监军一方诱杀，亲兵与幕僚遭清除。宦官用所得供词处置朝臣，杀生任免多由神策军中尉决定，唐文宗难以事先知悉。","s":["《资治通鉴·卷245·唐纪六十一》"]}],"who":[{"side":"发动方","t":"唐文宗、李训、郑注、韩约。","s":["《资治通鉴·卷245·唐纪六十一》"]},{"side":"对立方","t":"仇士良等掌握神策军的宦官。","s":["《资治通鉴·卷245·唐纪六十一》"]}],"cities":["西安（丰镐、长安）"],"people":["唐文宗","李训","郑注","仇士良","王守澄","王涯","贾餗","舒元舆"],"battles":[],"src":["《资治通鉴·卷245·唐纪六十一》"],"line":"唐文宗与李训等谋除宦官，伏兵计划在宫中败露，神策军反击，皇帝受到更严控制。","group":"政变与权力斗争","short":"甘露之变","timeShort":"835","placeShort":"陕西西安；陕西宝鸡凤翔","peopleShort":"唐文宗、李训、郑注、仇士良","result":"诛宦官失败，朝臣遭杀戮"},{"name":"陈桥兵变","tags":["兵变","改朝换代"],"g":"通说","lat":34.9,"lon":114.4,"f":[{"k":"时间","v":"960年，旧历正月。","s":["《宋史·卷1·太祖本纪一》"]},{"k":"地点","v":"河南省开封市及东北陈桥镇一带；古名东京、陈桥驿。","s":["《宋史·卷1·太祖本纪一》"]},{"k":"起因","v":"后周世宗去世，年幼的恭帝即位，北宋太祖当时任殿前都点检，掌握禁军中的重要力量。五代时期，统兵将领的地位与皇位归属屡次相连，幼主朝廷很难独立约束强将。960年初，北汉与契丹将要入侵的军报传到开封，朝廷命北宋太祖出师，禁军因此离城并集中在其统领之下。","s":["《宋史·卷1·太祖本纪一》"]},{"k":"结果与影响","v":"后周中央政权被取代，宋朝建立，北宋太祖接收了后周积累的军队、官僚机构和大片领土。政变的关键来自掌兵将领与禁军将校合作，禅位仪式则把军中的拥立变成朝廷承认的新君。新朝一方面封赏功臣，一方面需要继续处置不服从的军事力量，随后又展开削平割据与调整军权的工作。陈桥的胜利奠定宋朝开端，统一进程和军政制度的重整则在此后逐步完成。","s":["《宋史·卷1·太祖本纪一》"]},{"k":"史料说明","v":"《宋史》保存宋初国史的拥立叙事，强调太祖受逼、约束军队与保护周室。军报真假、事前准备程度及黄袍由谁携带，现存材料难以完整复原。","s":["《宋史·卷1·太祖本纪一》"]}],"steps":[{"t":"960年正月，后周朝廷收到北方军情，命殿前都点检北宋太祖率军出征。军队离开东京，停驻陈桥驿，朝廷中的皇帝、太后与宰相没有随军，军中开始出现拥立将帅的议论。","s":["《宋史·卷1·太祖本纪一》"]},{"t":"次日天明，诸将持兵聚到北宋太祖住处，表示军队不能没有主上，要拥他做天子。《宋史》记有人把黄衣加在他身上，众人跪拜称万岁，拥立由军中议论转为公开行动。","s":["《宋史·卷1·太祖本纪一》"]},{"t":"北宋太祖对诸将提出约束，要求不得惊犯周帝与太后，不得侵凌大臣，不得劫掠府库与百姓。诸将答应后整队返京，拥立者试图把军事夺权包装为有秩序的政权转移。","s":["《宋史·卷1·太祖本纪一》"]},{"t":"军队进入开封，韩通试图组织抵抗，被王彦升追到家中杀死。其余主要官署未能形成有效反击，北宋太祖控制城门和军队后，宰相范质等被带到他面前商议皇位归属。","s":["《宋史·卷1·太祖本纪一》"]},{"t":"范质等在列校持剑逼迫下向北宋太祖行礼，翰林学士陶谷取出禅位制书，百官参加仪式。军事拥立随即通过禅位文书、朝会与登殿完成形式上的皇权交接，后周恭帝退位。","s":["《宋史·卷1·太祖本纪一》"]},{"t":"北宋太祖即皇帝位，改元建隆，国号宋，后周恭帝改封郑王，符太后保留周太后尊号。新朝向各地发布文告，封赏拥立将领，接收原后周的中枢机构与主要统治地区。","s":["《宋史·卷1·太祖本纪一》"]}],"who":[{"side":"发动方","t":"北宋太祖、赵普、赵光义及拥立将领。","s":["《宋史·卷1·太祖本纪一》"]},{"side":"对立方","t":"后周恭帝、符太后；韩通试图抵抗。","s":["《宋史·卷1·太祖本纪一》"]}],"cities":["开封（汴州、东京、大梁）"],"people":["北宋太祖","北宋太宗","赵普","后周恭帝","范质","韩通"],"battles":[],"src":["《宋史·卷1·太祖本纪一》"],"line":"北宋太祖领兵出京，在陈桥驿被部将拥立，随后返城接受后周禅位，建立宋朝政权。","group":"政变与权力斗争","short":"陈桥兵变","timeShort":"960","placeShort":"河南开封及东北陈桥驿","peopleShort":"北宋太祖、赵普、后周恭帝","result":"后周被取代，宋朝建立"},{"name":"新旧党争","tags":["党争","关键转折"],"g":"通说","lat":34.8,"lon":114.3,"f":[{"k":"时间","v":"1069—1127。","s":["《宋史·卷327·王安石传》","《宋史·卷336·司马光传》","《宋史·卷472·蔡京传》","《宋史·卷23·钦宗本纪》"]},{"k":"地点","v":"河南省开封市、洛阳市；古名东京、西京。","s":["《宋史·卷327·王安石传》","《宋史·卷336·司马光传》","《宋史·卷472·蔡京传》","《宋史·卷23·钦宗本纪》"]},{"k":"起因","v":"北宋神宗希望解决财政、军备与地方治理问题，1069年任用王安石参与政事，推动新法。青苗、免役等措施改变官府与民户之间的关系，引发执行效果、财利来源与祖宗制度的争论。支持与反对者在朝议中形成交游和任用网络，皇帝、太后对国策的选择又不断改变双方进退。","s":["《宋史·卷327·王安石传》","《宋史·卷336·司马光传》","《宋史·卷472·蔡京传》","《宋史·卷23·钦宗本纪》"]},{"k":"结果与影响","v":"新法与改罢新法的措施多次反复，官员任免逐渐与是否属于某一派相联，朝议中的政策争论因此越来越难以单独处理。元祐党籍把已死、在世官员及其后人共同纳入处分，形成跨越数朝的政治清算。《宋史》对王安石、司马光、蔡京的评价各有强烈取向，仍能看到党派内部的分歧和个人转向。1127年北宋中枢覆亡，结束了这段特定朝廷中的争权过程，相关人物与国策评价后来仍持续争论。","s":["《宋史·卷327·王安石传》","《宋史·卷336·司马光传》","《宋史·卷472·蔡京传》","《宋史·卷23·钦宗本纪》"]},{"k":"史料说明","v":"“新党”“旧党”概括围绕新法形成的政治群体，各阶段人员与立场有变化。《宋史》对新法及党争的叙述承接南宋史学评价，蔡京的党籍也同时包含私人倾轧与权力整肃。","s":["《宋史·卷327·王安石传》","《宋史·卷336·司马光传》","《宋史·卷472·蔡京传》","《宋史·卷23·钦宗本纪》"]}],"steps":[{"t":"1069年，王安石任参知政事，设置制置三司条例司，随后推行青苗、免役、保甲等新法。司马光等反对部分措施及实施办法，双方围绕财政、民力与国家干预的尺度展开争论。","s":["《宋史·卷327·王安石传》","《宋史·卷336·司马光传》","《宋史·卷472·蔡京传》","《宋史·卷23·钦宗本纪》"]},{"t":"新法推行过程中，一些反对官员离开中枢，司马光退居洛阳编书；王安石阵营内部也因执行和用人发生分歧。到神宗后期，王安石离职，部分新法仍由其他执政者继续推行。","s":["《宋史·卷327·王安石传》","《宋史·卷336·司马光传》","《宋史·卷472·蔡京传》","《宋史·卷23·钦宗本纪》"]},{"t":"1085年北宋神宗去世，北宋哲宗年幼，太皇太后高氏听政，起用司马光等。次年以后，多项新法被改罢，支持新法的官员陆续外迁，元祐时期的朝政方向随之转变。","s":["《宋史·卷327·王安石传》","《宋史·卷336·司马光传》","《宋史·卷472·蔡京传》","《宋史·卷23·钦宗本纪》"]},{"t":"1093年宣仁高太后去世，哲宗亲政，转而恢复神宗时期的政策，以章惇等主持政务。被称为元祐党人的官员受到贬逐，争论逐渐从政策得失发展成对前一阶段人事和政治行为的追究。","s":["《宋史·卷327·王安石传》","《宋史·卷336·司马光传》","《宋史·卷472·蔡京传》","《宋史·卷23·钦宗本纪》"]},{"t":"北宋徽宗即位后，最初曾调整两派关系，后来重用蔡京，以继承神宗事业为号召。蔡京编列元祐党籍，把司马光、苏轼等及相关官员列入，刻石禁锢，处分又牵连子弟与婚姻。","s":["《宋史·卷327·王安石传》","《宋史·卷336·司马光传》","《宋史·卷472·蔡京传》","《宋史·卷23·钦宗本纪》"]},{"t":"党籍禁令随政局和灾异议论时有松紧，蔡京也多次罢相复出。到靖康初年，朝廷再清算蔡京等人的权势与政策，北宋很快又在金军进攻中失去汴京，这段长期争论随旧朝中枢崩溃而转入新局。","s":["《宋史·卷327·王安石传》","《宋史·卷336·司马光传》","《宋史·卷472·蔡京传》","《宋史·卷23·钦宗本纪》"]}],"who":[{"side":"发动方","t":"各阶段支持新法或主张改罢新法的朝臣。","s":["《宋史·卷327·王安石传》","《宋史·卷336·司马光传》","《宋史·卷472·蔡京传》","《宋史·卷23·钦宗本纪》"]},{"side":"对立方","t":"各阶段被排斥的另一派官员；皇帝与太后决定用舍。","s":["《宋史·卷327·王安石传》","《宋史·卷336·司马光传》","《宋史·卷472·蔡京传》","《宋史·卷23·钦宗本纪》"]}],"cities":["开封（汴州、东京、大梁）","洛阳"],"people":["北宋神宗","北宋哲宗","北宋徽宗","王安石","司马光","章惇","蔡京","苏轼","宣仁高太后"],"battles":["靖康之战与汴京陷落"],"src":["《宋史·卷327·王安石传》","《宋史·卷336·司马光传》","《宋史·卷472·蔡京传》","《宋史·卷23·钦宗本纪》"],"line":"北宋新法引发朝议分歧，皇位更替带动用人和政策反复，后来发展为党籍与政治清算。","group":"政变与权力斗争","short":"新旧党争","timeShort":"1069—1127","placeShort":"河南开封；河南洛阳","peopleShort":"王安石、司马光、章惇、蔡京","result":"新法反复，党籍整肃扩大"},{"name":"元代皇位之争：南坡之变与天历之变","tags":["宫廷政变","继位之争","权臣专权"],"g":"通说","lat":42.3,"lon":116.2,"f":[{"k":"时间","v":"1323—1329。","s":["《元史·卷28·英宗本纪二》","《元史·卷31·明宗本纪》","《元史·卷32·文宗本纪一》","《元史·卷33·文宗本纪二》"]},{"k":"地点","v":"内蒙古自治区锡林郭勒盟正蓝旗及北京市；古名上都南坡、大都。","s":["《元史·卷28·英宗本纪二》","《元史·卷31·明宗本纪》","《元史·卷32·文宗本纪一》","《元史·卷33·文宗本纪二》"]},{"k":"起因","v":"元仁宗、英宗相继即位后，皇位在不同宗支之间转移，武宗后裔曾被排除在继承之外。英宗与拜住清理铁木迭儿旧势力，引起相关大臣恐惧；掌握宿卫的铁失等谋划先行动手。英宗被杀后虽另立泰定帝，宗支矛盾与军政集团之间的竞争却未解决，几年后又因皇帝去世重新爆发。","s":["《元史·卷28·英宗本纪二》","《元史·卷31·明宗本纪》","《元史·卷32·文宗本纪一》","《元史·卷33·文宗本纪二》"]},{"k":"结果与影响","v":"南坡之变使元英宗与宰相拜住遇害，泰定帝建立新的统治中心；天历之变又推翻上都朝廷的继承安排，武宗后裔重新取得皇位。文宗、明宗短期相继即位，明宗死后文宗复位，说明1328年的胜负尚未完全解决宗支之间的关系。宿卫、枢密机构、两都府库和地方军队在继位中具有决定作用，燕铁木儿等拥立者的权势因此上升，朝廷的宗室关系也受到长期影响。","s":["《元史·卷28·英宗本纪二》","《元史·卷31·明宗本纪》","《元史·卷32·文宗本纪一》","《元史·卷33·文宗本纪二》"]},{"k":"史料说明","v":"南坡之变发生于1323年，两都争立发生于1328年，明宗即位、去世及文宗复位在1329年。《元史》相关本纪记明宗暴卒，死因与责任的详细证据仍有不足。","s":["《元史·卷28·英宗本纪二》","《元史·卷31·明宗本纪》","《元史·卷32·文宗本纪一》","《元史·卷33·文宗本纪二》"]}],"steps":[{"t":"1323年，英宗与拜住追究铁木迭儿旧事，削夺其家财与荣典。铁失等担心清算扩大，联络掌兵大臣及宗王，利用皇帝往来两都、宿卫军随行的机会准备袭击。","s":["《元史·卷28·英宗本纪二》","《元史·卷31·明宗本纪》","《元史·卷32·文宗本纪一》","《元史·卷33·文宗本纪二》"]},{"t":"同年八月，英宗自上都南还，驻在南坡。铁失以所领阿速卫兵为外应，先杀拜住，再杀行帐中的英宗，随后迎晋王也孙铁木儿即位，即元泰定帝，南坡之变结束了英宗统治。","s":["《元史·卷28·英宗本纪二》","《元史·卷31·明宗本纪》","《元史·卷32·文宗本纪一》","《元史·卷33·文宗本纪二》"]},{"t":"1328年泰定帝死于上都，倒剌沙等在上都拥立其子。燕铁木儿则在大都控制枢密符印与宿卫，拘捕中枢官员，迎武宗之子图帖睦尔北上即位，是为元文宗，两都出现各自的皇帝。","s":["《元史·卷28·英宗本纪二》","《元史·卷31·明宗本纪》","《元史·卷32·文宗本纪一》","《元史·卷33·文宗本纪二》"]},{"t":"大都、上都两方征调军队，争夺关口、府库和地方支持。上都军攻向大都未能取胜，后来上都被围，倒剌沙奉皇帝玺印投降，大都一方赢得两都之争。","s":["《元史·卷28·英宗本纪二》","《元史·卷31·明宗本纪》","《元史·卷32·文宗本纪一》","《元史·卷33·文宗本纪二》"]},{"t":"文宗随后迎在北方的兄长，1329年兄长在和宁之北即位，是为元明宗。文宗把皇帝宝玺送去，明宗任命官员并南行，两方通过让位与迎驾仪式尝试重新安排宗支地位。","s":["《元史·卷28·英宗本纪二》","《元史·卷31·明宗本纪》","《元史·卷32·文宗本纪一》","《元史·卷33·文宗本纪二》"]},{"t":"明宗南行到旺忽察都与文宗相见，不久突然去世，文宗再次即位。燕铁木儿在拥立、调军和朝廷人事中取得极大影响，皇位虽重新落定，宗支间的疑惧与权臣势力仍然存在。","s":["《元史·卷28·英宗本纪二》","《元史·卷31·明宗本纪》","《元史·卷32·文宗本纪一》","《元史·卷33·文宗本纪二》"]}],"who":[{"side":"发动方","t":"铁失、也先铁木儿；后为燕铁木儿及拥立元文宗的力量。","s":["《元史·卷28·英宗本纪二》","《元史·卷31·明宗本纪》","《元史·卷32·文宗本纪一》","《元史·卷33·文宗本纪二》"]},{"side":"对立方","t":"元英宗、拜住；后为倒剌沙与上都朝廷。","s":["《元史·卷28·英宗本纪二》","《元史·卷31·明宗本纪》","《元史·卷32·文宗本纪一》","《元史·卷33·文宗本纪二》"]}],"cities":["开平／元上都","北京（蓟、幽州、燕京、中都、大都、北平、京师）"],"people":["元英宗","元泰定帝","元文宗","元明宗","拜住","铁失","燕铁木儿","倒剌沙"],"battles":[],"src":["《元史·卷28·英宗本纪二》","《元史·卷31·明宗本纪》","《元史·卷32·文宗本纪一》","《元史·卷33·文宗本纪二》"],"line":"元英宗在南坡被杀后，皇位再经两都争立与兄弟相继即位，燕铁木儿的权势随之扩大。","group":"政变与权力斗争","short":"元代皇位之争","timeShort":"1323—1329","placeShort":"内蒙古正蓝旗；北京","peopleShort":"元英宗、铁失、元文宗、元明宗、燕铁木儿","result":"英宗、明宗相继死，文宗复位"},{"name":"胡惟庸案","tags":["权臣专权","关键转折"],"g":"通说","lat":32.1,"lon":118.8,"f":[{"k":"时间","v":"1380年，洪武十三年正月；后续追究延至1390年以后。","s":["《明史·卷308·胡惟庸传》","《明史·卷72·职官志一》"]},{"k":"地点","v":"江苏省南京市；古名应天府。","s":["《明史·卷308·胡惟庸传》","《明史·卷72·职官志一》"]},{"k":"起因","v":"明朝建立后，中书省总领政务，丞相在皇帝之下协调六部。胡惟庸长期任相，参与官员升降与文书处理，依附者众多，皇帝对相权集中日益警惕。进贡消息被隐瞒、官员互相推责等事件又加深冲突，胡惟庸本人及同僚被指控谋反，案件最终引出中央制度的大幅调整。","s":["《明史·卷308·胡惟庸传》","《明史·卷72·职官志一》"]},{"k":"结果与影响","v":"胡惟庸被杀，中书省与丞相制度被撤除，六部直接向皇帝奏事，明朝中央决策结构发生长期变化。案件并未随主犯死亡结束，后来以胡党名义扩大追究，李善长等开国勋臣也遭清算。《明史》在叙述中区分最初诛杀和后来陆续公布的罪状，能够看到定罪材料不断扩展的过程。殿阁大学士最初主要备顾问，后来内阁地位上升，又形成不同于原中书省的新辅政方式。","s":["《明史·卷308·胡惟庸传》","《明史·卷72·职官志一》"]},{"k":"史料说明","v":"《明史》记部分通倭、通北元指控在胡惟庸死后多年才揭出，后案材料带有追究“胡党”的办案背景。废相与六部直达皇帝的制度变化，则见《职官志》的明确记载。","s":["《明史·卷308·胡惟庸传》","《明史·卷72·职官志一》"]}],"steps":[{"t":"胡惟庸由参知政事逐步升任丞相，明太祖起初信任其才能。《明史》记他截看各司奏章，把涉及自身不利的材料扣住，进退官员又常先自行处置，君相间的权力矛盾扩大。","s":["《明史·卷308·胡惟庸传》","《明史·卷72·职官志一》"]},{"t":"1379年，占城使者到来，中书省没有及时上报，皇帝追责，省臣与礼部互相推诿。汪广洋随后被赐死，相关案件继续牵连中书省及六部官员，胡惟庸的处境更加危险。","s":["《明史·卷308·胡惟庸传》","《明史·卷72·职官志一》"]},{"t":"1380年正月，涂节、商暠告发胡惟庸，明太祖命廷臣审讯。办案者把陈宁、涂节也列入谋反同谋，胡惟庸、陈宁、涂节一同被诛，丞相集团受到直接清除。","s":["《明史·卷308·胡惟庸传》","《明史·卷72·职官志一》"]},{"t":"胡惟庸死后，明太祖撤去中书省，废丞相，使六部直接对皇帝负责。大都督府也分为五军都督府，军事调度与统军机构分别安排，中央权力进一步集中到皇帝手中。","s":["《明史·卷308·胡惟庸传》","《明史·卷72·职官志一》"]},{"t":"此后数年，办案仍继续扩大，林贤、封绩等人的案件被纳入胡党通倭、通北元的指控。原来发生在中枢的案子因此延伸到沿海、边疆及开国功臣的关系网络。","s":["《明史·卷308·胡惟庸传》","《明史·卷72·职官志一》"]},{"t":"1390年，李善长及多名勋臣又被追究，朝廷编《昭示奸党录》公布罪状。牵连范围远超1380年最初被诛的人，皇帝通过持续追查重整开国官僚与勋贵，废相后的政治格局逐渐固定。","s":["《明史·卷308·胡惟庸传》","《明史·卷72·职官志一》"]}],"who":[{"side":"发动方","t":"明太祖与奉命办案的廷臣。","s":["《明史·卷308·胡惟庸传》","《明史·卷72·职官志一》"]},{"side":"对立方","t":"胡惟庸、陈宁、涂节；后来追究李善长等。","s":["《明史·卷308·胡惟庸传》","《明史·卷72·职官志一》"]}],"cities":["南京（建业、建康、金陵、应天、天京）"],"people":["明太祖","胡惟庸","李善长","刘基","徐达"],"battles":[],"src":["《明史·卷308·胡惟庸传》","《明史·卷72·职官志一》"],"line":"明太祖以谋反罪诛胡惟庸，并撤去中书省与丞相，六部直接对皇帝负责，株连延续多年。","group":"政变与权力斗争","short":"胡惟庸案","timeShort":"1380","placeShort":"江苏南京","peopleShort":"明太祖、胡惟庸、李善长","result":"胡惟庸被诛，丞相制度废除"},{"name":"夺门之变","tags":["宫廷政变","继位之争"],"g":"通说","lat":39.9,"lon":116.4,"f":[{"k":"时间","v":"1457年，旧历正月。","s":["《明史·卷170·于谦传》","《明史·卷171·徐有贞、石亨传》"]},{"k":"地点","v":"北京市；古名京师、南宫、奉天殿。","s":["《明史·卷170·于谦传》","《明史·卷171·徐有贞、石亨传》"]},{"k":"起因","v":"1449年土木堡战败，明英宗被俘，郕王即位为景泰帝，于谦组织守卫北京。英宗获释回朝后被安置在南宫，景泰帝又改立自己的儿子为太子，宫中形成复杂的继承关系。1457年景泰帝病重，其子早已去世，朝臣商议储位，石亨等担心失去机会，决定迎英宗复位。","s":["《明史·卷170·于谦传》","《明史·卷171·徐有贞、石亨传》"]},{"k":"结果与影响","v":"明英宗复位，景泰帝被废，于谦、王文遭到杀害，天顺朝廷重新安排皇位继承和中枢人事。参与者利用皇帝病重、储位未定和南宫仍有太上皇的条件，先造成复位事实，再通过诏令与刑案确立新局。于谦此前保卫北京有功，他的死亡与夺门集团巩固权力直接相关。石亨、徐有贞、曹吉祥后来又相继失势，受封并未让同盟长期维持，景泰与天顺间的是非也在后朝继续被重新评价。","s":["《明史·卷170·于谦传》","《明史·卷171·徐有贞、石亨传》"]},{"k":"史料说明","v":"“夺门”是迎出南宫、完成复位后的事件名称。《明史·于谦传》明言谋迎立他王的罪状出于诬陷，且保存英宗认为于谦有功、徐有贞坚持处死的对话。","s":["《明史·卷170·于谦传》","《明史·卷171·徐有贞、石亨传》"]}],"steps":[{"t":"土木堡危机后，景泰帝在位，英宗以太上皇身份回到北京，住在南宫。两帝并存并未形成共同执政，英宗受到限制，朝中人事和军政仍由景泰朝廷安排。","s":["《明史·卷170·于谦传》","《明史·卷171·徐有贞、石亨传》"]},{"t":"景泰帝改换太子后，原太子朱见深被降为沂王，新太子又早逝。到1457年正月皇帝病重，恢复旧太子还是另作安排成为朝廷焦点，石亨、张軏等开始联络宫内外力量。","s":["《明史·卷170·于谦传》","《明史·卷171·徐有贞、石亨传》"]},{"t":"石亨与徐有贞、曹吉祥等密议迎上皇，借将士进城控制南宫通道。夜间，他们打开并破坏阻碍通行的门墙，把英宗从南宫迎出，直向皇帝举行朝会的宫殿前进。","s":["《明史·卷170·于谦传》","《明史·卷171·徐有贞、石亨传》"]},{"t":"英宗登殿，钟鼓响起，百官到朝时才得知已经发生复位。起事者以皇帝已回位的事实要求朝廷承认，景泰帝在病中失去帝位，原朝廷未能组织有效反击。","s":["《明史·卷170·于谦传》","《明史·卷171·徐有贞、石亨传》"]},{"t":"石亨等随即逮捕于谦、大学士王文，指控他们准备迎立其他宗室。审案以谋逆定罪，徐有贞又向英宗强调须处死于谦来证明复位有理由，于谦、王文最终被杀。","s":["《明史·卷170·于谦传》","《明史·卷171·徐有贞、石亨传》"]},{"t":"英宗改元天顺，恢复朱见深的太子地位，景泰帝降为郕王，不久去世。夺门参与者得到封赏和要职，随后又相互排挤，复位后的政治清算继续影响朝廷用人。","s":["《明史·卷170·于谦传》","《明史·卷171·徐有贞、石亨传》"]}],"who":[{"side":"发动方","t":"石亨、徐有贞、张軏、曹吉祥、明英宗。","s":["《明史·卷170·于谦传》","《明史·卷171·徐有贞、石亨传》"]},{"side":"对立方","t":"景泰帝；于谦、王文随后被诬杀。","s":["《明史·卷170·于谦传》","《明史·卷171·徐有贞、石亨传》"]}],"cities":["北京（蓟、幽州、燕京、中都、大都、北平、京师）"],"people":["明英宗","明代宗","明宪宗","于谦","徐有贞","石亨","曹吉祥","王文"],"battles":["土木堡之战"],"src":["《明史·卷170·于谦传》","《明史·卷171·徐有贞、石亨传》"],"line":"景泰帝病重时，石亨等迎出南宫中的明英宗复位，随后处死于谦，朝廷人事重新洗牌。","group":"政变与权力斗争","short":"夺门之变","timeShort":"1457","placeShort":"北京","peopleShort":"明英宗、徐有贞、石亨、曹吉祥、于谦","result":"英宗复位，景泰帝被废"},{"name":"魏忠贤专权与东林党争","tags":["外戚宦官","党争","权臣专权"],"g":"通说","lat":39.9,"lon":116.4,"f":[{"k":"时间","v":"1620—1627。","s":["《明史·卷305·宦官传二》","《明史·卷244·杨涟、左光斗传》","《明史·卷23·庄烈帝本纪一》"]},{"k":"地点","v":"北京市、江苏省无锡市等地；古名京师、东林书院。","s":["《明史·卷305·宦官传二》","《明史·卷244·杨涟、左光斗传》","《明史·卷23·庄烈帝本纪一》"]},{"k":"起因","v":"万历末年围绕储位、宫廷案件和官员任用的争论，已使士人分成多种交游与政治阵营。明熹宗即位后，魏忠贤与乳母客氏获得宠信，逐步介入司礼监、东厂和朝廷任免。杨涟等曾参与护送新君、处理移宫，随后又反对近侍专权，原有宫廷冲突与外朝党争因而交织。","s":["《明史·卷305·宦官传二》","《明史·卷244·杨涟、左光斗传》","《明史·卷23·庄烈帝本纪一》"]},{"k":"结果与影响","v":"魏忠贤依靠近侍地位、皇帝宠信与厂卫力量压制外朝，东林士人遭禁锢和诏狱杀戮，朝廷用人受到严重影响。明思宗即位后清除魏忠贤及其依附者，并为部分冤案恢复名誉，司礼监与厂卫本身却仍继续存在。此次变化表明，近侍权势高度依赖皇帝支持，也能借内廷传达与司法侦缉扩展到地方。东林与反东林的政治关系并未随魏忠贤之死消失，明末朝议中仍承受这些旧怨。","s":["《明史·卷305·宦官传二》","《明史·卷244·杨涟、左光斗传》","《明史·卷23·庄烈帝本纪一》"]},{"k":"史料说明","v":"“东林”最初与书院讲学、官员交游有关，后在政治指控中不断扩大；被列为东林者的具体立场各有差别。《明史》对魏忠贤的评价，也承接崇祯初年的定罪与后来的史论。","s":["《明史·卷305·宦官传二》","《明史·卷244·杨涟、左光斗传》","《明史·卷23·庄烈帝本纪一》"]}],"steps":[{"t":"1620年明熹宗继位，杨涟等外朝官员与内侍王安协助处理李选侍移宫。魏忠贤、客氏因接近新帝迅速得势，魏忠贤进入司礼监，外朝越来越难以直接影响宫内传达。","s":["《明史·卷305·宦官传二》","《明史·卷244·杨涟、左光斗传》","《明史·卷23·庄烈帝本纪一》"]},{"t":"魏忠贤与客氏排挤王安，王安被降到南海子，随后遭杀。原先能够沟通外朝与皇帝的内侍力量被除去，魏忠贤又依靠王体乾等控制司礼监事务，取得更大的近侍权力。","s":["《明史·卷305·宦官传二》","《明史·卷244·杨涟、左光斗传》","《明史·卷23·庄烈帝本纪一》"]},{"t":"1624年，杨涟上疏列魏忠贤二十四罪，指责干预朝政、迫害宫人及专权。明熹宗没有采纳，魏忠贤反而利用皇帝信任巩固地位，支持或追随杨涟者逐渐被排挤出朝。","s":["《明史·卷305·宦官传二》","《明史·卷244·杨涟、左光斗传》","《明史·卷23·庄烈帝本纪一》"]},{"t":"魏忠贤一方借汪文言案扩大追究，把外朝反对者与所谓受贿联系起来。1625年，杨涟、左光斗等被捕入诏狱，在逼供与刑讯中死去，地方官与家属还面临追赃压力。","s":["《明史·卷305·宦官传二》","《明史·卷244·杨涟、左光斗传》","《明史·卷23·庄烈帝本纪一》"]},{"t":"清除行动继续扩大，东林书院受毁，党籍与诸种名单把不同政治关系的人归作一党。依附者则争建生祠、颂扬魏忠贤，各地督抚与京官的升降受到厂卫、司礼和内阁关系影响。","s":["《明史·卷305·宦官传二》","《明史·卷244·杨涟、左光斗传》","《明史·卷23·庄烈帝本纪一》"]},{"t":"1627年明熹宗死，明思宗即位，逐步接受弹劾，处置客氏并命魏忠贤去凤阳。魏忠贤途中自杀，朝廷转而追究其支持者，平反部分受害者，天启时期的权力格局迅速崩解。","s":["《明史·卷305·宦官传二》","《明史·卷244·杨涟、左光斗传》","《明史·卷23·庄烈帝本纪一》"]}],"who":[{"side":"发动方","t":"魏忠贤、客氏及依附的内外官员。","s":["《明史·卷305·宦官传二》","《明史·卷244·杨涟、左光斗传》","《明史·卷23·庄烈帝本纪一》"]},{"side":"对立方","t":"杨涟、左光斗等东林士人；明思宗即位后转而清除魏党。","s":["《明史·卷305·宦官传二》","《明史·卷244·杨涟、左光斗传》","《明史·卷23·庄烈帝本纪一》"]}],"cities":["北京（蓟、幽州、燕京、中都、大都、北平、京师）"],"people":["明熹宗","明思宗","魏忠贤","客氏","杨涟","左光斗","顾宪成","王安"],"battles":[],"src":["《明史·卷305·宦官传二》","《明史·卷244·杨涟、左光斗传》","《明史·卷23·庄烈帝本纪一》"],"line":"魏忠贤借皇帝宠信与厂卫权力打击东林士人，诏狱与党籍扩大，崇祯即位后清除其势力。","group":"政变与权力斗争","short":"魏忠贤专权","timeShort":"1620—1627","placeShort":"北京；江苏无锡等地","peopleShort":"魏忠贤、杨涟、左光斗、明熹宗、明思宗","result":"魏忠贤自杀，依附者遭清算"},{"name":"康熙擒鳌拜","tags":["权臣专权","宫廷政变"],"g":"通说","lat":39.9,"lon":116.4,"f":[{"k":"时间","v":"1669年，康熙八年五月。","s":["《清史稿·卷249·索尼苏克萨哈遏必隆鳌拜列传》","《清史稿·卷6·圣祖本纪一》"]},{"k":"地点","v":"北京市；古名京师、宫禁。","s":["《清史稿·卷249·索尼苏克萨哈遏必隆鳌拜列传》","《清史稿·卷6·圣祖本纪一》"]},{"k":"起因","v":"清世祖去世后，索尼、苏克萨哈、遏必隆、鳌拜四大臣辅佐幼年的清圣祖。鳌拜掌握宿卫与旗人关系，在辅政中越来越强势，又借圈换旗地等争端清除异己。索尼死后，其他辅臣难以牵制鳌拜；即使皇帝开始亲政，他仍干预人事和朝政，皇权与辅臣之间的矛盾不断累积。","s":["《清史稿·卷249·索尼苏克萨哈遏必隆鳌拜列传》","《清史稿·卷6·圣祖本纪一》"]},{"k":"结果与影响","v":"鳌拜被拘禁，原有辅政集团中掌握最大实权的一方失去地位，清圣祖得以扩大亲自裁决朝政和任免官员的权力。这次处置以结党、专擅、迫害官员等罪进行，鳌拜最终获免死，说明清廷同时考虑旧功与现罪。后来的康熙、雍正、乾隆诸朝又数次调整鳌拜及其后裔的爵位待遇，其早期军事功劳与辅政后期擅权在官方评价中并列保留。皇帝亲政的落实，由此跨过一个重要关口。","s":["《清史稿·卷249·索尼苏克萨哈遏必隆鳌拜列传》","《清史稿·卷6·圣祖本纪一》"]},{"k":"史料说明","v":"《清史稿·圣祖本纪》记选年轻侍卫、拜唐阿作扑击之戏并制伏鳌拜，《鳌拜传》则详列擅权与审判经过。两处详略不同，后世增添的器械、对话等场面缺少相同程度的文献支持。","s":["《清史稿·卷249·索尼苏克萨哈遏必隆鳌拜列传》","《清史稿·卷6·圣祖本纪一》"]}],"steps":[{"t":"1661年，四大臣受遗命辅政，清圣祖年幼，国家大事经辅臣议定。鳌拜原有战功与侍卫资历，又掌握旗人关系，能够借辅政职位深度介入宫廷和朝廷事务。","s":["《清史稿·卷249·索尼苏克萨哈遏必隆鳌拜列传》","《清史稿·卷6·圣祖本纪一》"]},{"t":"鳌拜推动镶黄旗与正白旗换地，要求按自己解释的旗序调整占地。苏纳海等反对，案件随即升级，相关官员被处死，辅政集团中的政策争论转为严厉的人事清除。","s":["《清史稿·卷249·索尼苏克萨哈遏必隆鳌拜列传》","《清史稿·卷6·圣祖本纪一》"]},{"t":"索尼去世，苏克萨哈又与鳌拜冲突并遭处置，四辅臣间的牵制逐渐消失。鳌拜与亲属、同党在家中先议朝事，再带入朝廷施行，其他官员难以公开表示不同意见。","s":["《清史稿·卷249·索尼苏克萨哈遏必隆鳌拜列传》","《清史稿·卷6·圣祖本纪一》"]},{"t":"清圣祖亲政后，鳌拜仍坚持推荐自己的人选，干预户部、工部任命，甚至反对言官议论时政。皇帝虽已具有亲政名分，重要部门与议政程序仍受到辅臣集团的实际影响。","s":["《清史稿·卷249·索尼苏克萨哈遏必隆鳌拜列传》","《清史稿·卷6·圣祖本纪一》"]},{"t":"1669年五月，《清史稿·圣祖本纪》记清圣祖先选年轻有力的侍卫、拜唐阿作扑击之戏，鳌拜入见时，命他们将其制伏拘禁。皇帝随后交议政王大臣审理，把宫中的擒拿转为正式的政治与司法处置。","s":["《清史稿·卷249·索尼苏克萨哈遏必隆鳌拜列传》","《清史稿·卷6·圣祖本纪一》"]},{"t":"清圣祖念鳌拜旧日效力，最终免其死罪，削夺官职、籍没家产并禁锢，鳌拜死于禁所。相关依附者也被处置，皇帝重新掌握任免与议政中的主动，四辅臣制度的影响进一步退去。","s":["《清史稿·卷249·索尼苏克萨哈遏必隆鳌拜列传》","《清史稿·卷6·圣祖本纪一》"]}],"who":[{"side":"发动方","t":"清圣祖及奉命侍卫、议政王大臣。","s":["《清史稿·卷249·索尼苏克萨哈遏必隆鳌拜列传》","《清史稿·卷6·圣祖本纪一》"]},{"side":"对立方","t":"鳌拜及其结党人员。","s":["《清史稿·卷249·索尼苏克萨哈遏必隆鳌拜列传》","《清史稿·卷6·圣祖本纪一》"]}],"cities":["北京（蓟、幽州、燕京、中都、大都、北平、京师）"],"people":["清圣祖","鳌拜","索尼","苏克萨哈","遏必隆"],"battles":[],"src":["《清史稿·卷249·索尼苏克萨哈遏必隆鳌拜列传》","《清史稿·卷6·圣祖本纪一》"],"line":"康熙亲政后处置仍把持朝务的鳌拜，削夺官爵并禁锢，皇帝进一步收回辅政时期的权力。","group":"政变与权力斗争","short":"康熙擒鳌拜","timeShort":"1669","placeShort":"北京","peopleShort":"清圣祖、鳌拜、索额图","result":"鳌拜被拘，辅臣势力受清理"},{"name":"九子夺嫡与雍正继位","tags":["继位之争","关键转折"],"g":"通说","lat":40.0,"lon":116.3,"f":[{"k":"时间","v":"1708—1723。","s":["《清史稿·卷220·诸王列传》","《清史稿·卷9·世宗本纪》"]},{"k":"地点","v":"北京市及河北省承德市一带；古名京师、畅春园、塞外行营。","s":["《清史稿·卷220·诸王列传》","《清史稿·卷9·世宗本纪》"]},{"k":"起因","v":"康熙早年立胤礽为皇太子，长期亲自教导，并让他留京处理部分政务。随着太子成年、近臣形成网络，父子之间在权威与信任上出现裂缝，其他皇子也参与朝政、领兵和争取大臣支持。1708年第一次废太子，打破了原先较明确的继承安排，储位空缺让朝廷中的关系更为紧张。","s":["《清史稿·卷220·诸王列传》","《清史稿·卷9·世宗本纪》"]},{"k":"结果与影响","v":"胤礽两次被废，康熙末年长期公开建储的安排终止，胤禛最终承位，1723年改元雍正。新君起初仍使用不同关系中的宗室与大臣，随后在执政中继续调整权力，其与部分兄弟的冲突也延续到后来的雍正年间。秘密建储把继承人选择藏于密旨，改变了公开太子长期聚集支持者的方式。“九子夺嫡”概括这一时期的继承竞争，真正的参与者还包括近侍、大臣与皇帝本人。","s":["《清史稿·卷220·诸王列传》","《清史稿·卷9·世宗本纪》"]},{"k":"史料说明","v":"“九子夺嫡”是后世概括，九位皇子的参与时间与程度不同。雍正即位在1722年，1723年是改元之年；《清史稿》记奉遗诏继位，流行的改字夺位情节缺少可靠原始证据。","s":["《清史稿·卷220·诸王列传》","《清史稿·卷9·世宗本纪》"]}],"steps":[{"t":"1708年，康熙在巡行期间公开列举太子失德、结党与窥伺等罪，宣布废黜胤礽。长子胤禔试图利用局势进一步打击废太子，却因自身行为激怒皇帝，随后被夺爵、幽禁。","s":["《清史稿·卷220·诸王列传》","《清史稿·卷9·世宗本纪》"]},{"t":"储位空缺后，大臣与皇子之间的支持关系更加显眼，胤禩一度得到较多推举。康熙对群臣结党推立深感警惕，反复训斥诸皇子，朝廷仍没有形成各方共同接受的继承人选。","s":["《清史稿·卷220·诸王列传》","《清史稿·卷9·世宗本纪》"]},{"t":"1709年，康熙恢复胤礽的太子地位，希望重新稳定储位。父子之间的信任未能持久，1712年胤礽再被废黜，此后康熙没有公开再立太子，皇子间的竞争继续存在。","s":["《清史稿·卷220·诸王列传》","《清史稿·卷9·世宗本纪》"]},{"t":"胤禛以雍亲王身份参与祭祀和政务，胤禵则出任抚远大将军，在西北军事中取得重要地位。各人的职责、声望和支持者不同，储位之争通过差使、交游及皇帝的评价不断变化。","s":["《清史稿·卷220·诸王列传》","《清史稿·卷9·世宗本纪》"]},{"t":"1722年十一月，康熙在畅春园病重去世。《清史稿·世宗本纪》记胤禛奉命代行祭祀，后被召至，承遗诏继位，成为清世宗，朝廷开始围绕新君重新分配职务。","s":["《清史稿·卷220·诸王列传》","《清史稿·卷9·世宗本纪》"]},{"t":"雍正即位后，先让胤禩、胤祥、马齐、隆科多总理事务，召胤禵回京，次年改元雍正。1723年又安排秘密建储，试图以密封继承人文书减少公开储位引发的结党与争夺。","s":["《清史稿·卷220·诸王列传》","《清史稿·卷9·世宗本纪》"]}],"who":[{"side":"发动方","t":"康熙诸皇子及各自支持者；最后由清世宗承位。","s":["《清史稿·卷220·诸王列传》","《清史稿·卷9·世宗本纪》"]},{"side":"对立方","t":"储位竞争中的其他皇子；清圣祖主持废立。","s":["《清史稿·卷220·诸王列传》","《清史稿·卷9·世宗本纪》"]}],"cities":["北京（蓟、幽州、燕京、中都、大都、北平、京师）"],"people":["清圣祖","清世宗","胤礽","胤禩","胤禵","允祥","隆科多","马齐"],"battles":[],"src":["《清史稿·卷220·诸王列传》","《清史稿·卷9·世宗本纪》"],"line":"康熙两废太子后，皇子与大臣卷入储位竞争，胤禛最终继位，次年改元雍正并整顿政务。","group":"政变与权力斗争","short":"九子夺嫡","timeShort":"1708—1723","placeShort":"北京；河北承德一带","peopleShort":"清圣祖、清世宗、胤礽、胤禩、胤禵","result":"太子两废，雍正继位并改元"},{"name":"辛酉政变","tags":["宫廷政变","继位之争"],"g":"通说","lat":39.9,"lon":116.4,"f":[{"k":"时间","v":"1861年，旧历七月至十一月。","s":["《清史稿·卷214·后妃列传》","《清史稿·卷221·诸王列传》"]},{"k":"地点","v":"河北省承德市、北京市；古名热河、京师。","s":["《清史稿·卷214·后妃列传》","《清史稿·卷221·诸王列传》"]},{"k":"起因","v":"1860年英法联军进逼北京，咸丰帝前往热河，恭亲王奕訢留京处理议和。次年咸丰死于热河，遗命载垣、端华、肃顺等八大臣赞襄政务，幼帝继位，两宫太后分别以嫡母与生母身份取得尊位。八大臣要维持顾命辅政，两宫则要求参与裁决政事，留京的奕訢成为另一支可合作的力量。","s":["《清史稿·卷214·后妃列传》","《清史稿·卷221·诸王列传》"]},{"k":"结果与影响","v":"八大臣失势，慈安、慈禧两宫垂帘，奕訢进入最高决策层，咸丰遗命建立的辅政安排被改组。幼帝仍在位，清朝皇统继续，两宫与近支亲王通过诏旨、拘捕和审判完成权力转移。此后朝廷在处理内战、议和与洋务时，都要经过新的中枢关系。两宫共同听政与奕訢议政也有各自边界，后来仍发生权力调整；慈禧在这轮政变中获得了持续参与最高政务的制度位置。","s":["《清史稿·卷214·后妃列传》","《清史稿·卷221·诸王列传》"]},{"k":"史料说明","v":"“辛酉”是1861年的干支纪年。清廷文书以幼帝名义发布，内容由两宫与合作大臣决定；八大臣的罪状与最终处置也出自政变胜出一方主持的审议。","s":["《清史稿·卷214·后妃列传》","《清史稿·卷221·诸王列传》"]}],"steps":[{"t":"1861年七月，咸丰去世，年幼的同治帝继位，载垣、端华、肃顺等奉遗命赞襄政务。慈安、慈禧两宫太后同时受尊，幼帝、太后与八大臣之间的办事权限尚待安排。","s":["《清史稿·卷214·后妃列传》","《清史稿·卷221·诸王列传》"]},{"t":"御史董元醇上疏，请两宫太后暂理朝政并选择亲王辅佐。两宫把建议交给八大臣，八大臣以清朝没有太后垂帘先例反对，围绕谁能参与最高政务的冲突由此公开。","s":["《清史稿·卷214·后妃列传》","《清史稿·卷221·诸王列传》"]},{"t":"奕訢从北京赴热河奔丧，得到与两宫接触的机会，两宫向他诉说八大臣擅政。留京亲王与宫中太后形成合作，原先分在京城和行在的政治资源开始汇合。","s":["《清史稿·卷214·后妃列传》","《清史稿·卷221·诸王列传》"]},{"t":"咸丰灵柩与皇帝、两宫返回北京，肃顺负责护送灵柩，行程安排使八大臣暂时分开。两宫与奕訢利用回京后的条件准备处置对手，京城军政力量不再只听从原有顾命集团。","s":["《清史稿·卷214·后妃列传》","《清史稿·卷221·诸王列传》"]},{"t":"两宫以幼帝名义下诏，指控载垣、端华、肃顺专擅阻挠，命拘捕查办。载垣、端华在京被拿，肃顺途中被捕，其他赞襄大臣也失去职位，八大臣的辅政体制迅速瓦解。","s":["《清史稿·卷214·后妃列传》","《清史稿·卷221·诸王列传》"]},{"t":"肃顺被处死，载垣、端华获赐自尽，其余人分别受罚。朝廷改拟用的祺祥年号为同治，定垂帘听政典礼，两宫在养心殿临朝，奕訢受命为议政王并主持重要政务。","s":["《清史稿·卷214·后妃列传》","《清史稿·卷221·诸王列传》"]}],"who":[{"side":"发动方","t":"慈禧太后、慈安太后、恭亲王奕訢等。","s":["《清史稿·卷214·后妃列传》","《清史稿·卷221·诸王列传》"]},{"side":"对立方","t":"肃顺、载垣、端华等赞襄政务王大臣。","s":["《清史稿·卷214·后妃列传》","《清史稿·卷221·诸王列传》"]}],"cities":["北京（蓟、幽州、燕京、中都、大都、北平、京师）"],"people":["清文宗","清穆宗","慈禧太后","慈安太后","奕訢","肃顺","载垣","端华"],"battles":[],"src":["《清史稿·卷214·后妃列传》","《清史稿·卷221·诸王列传》"],"line":"咸丰死后，两宫太后联合恭亲王清除赞襄政务大臣，建立垂帘听政与议政王并行的安排。","group":"政变与权力斗争","short":"辛酉政变","timeShort":"1861","placeShort":"河北承德；北京","peopleShort":"慈禧太后、慈安太后、奕訢、肃顺","result":"八大臣失势，两宫垂帘"},{"name":"戊戌变法与戊戌政变","tags":["宫廷政变","关键转折"],"g":"通说","lat":39.9,"lon":116.4,"f":[{"k":"时间","v":"1898年，旧历四月至八月。","s":["《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃列传》","《清史稿·卷437·荣禄传》"]},{"k":"地点","v":"北京市；古名京师、颐和园、瀛台。","s":["《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃列传》","《清史稿·卷437·荣禄传》"]},{"k":"起因","v":"甲午战败后，清廷面对赔款、割地与列强压力，朝中有人主张以改制求强。光绪帝希望通过学堂、科举、军政与机构调整改变困局，康有为等获得进言机会。慈禧虽已归政，仍影响高级人事和重大决定，新政推进又触动官署与既有人事，皇帝、太后及新旧官员之间的信任迅速下降。","s":["《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃列传》","《清史稿·卷437·荣禄传》"]},{"k":"结果与影响","v":"变法因政变中止，慈禧重新训政，光绪失去独立处理朝政的条件，维新参与者遭处死、罢官或流亡。短期改革所依赖的皇帝直接支持被切断，部院、军队与宫廷之间的权力关系重新调整。部分教育和实业措施仍有延续，京师大学堂也没有随大多数新政一同撤去。戊戌的失败推动出亡者继续宣传制度改革，清廷后来又在新的内外危机下推行新政，但其政治条件与1898年已有变化。","s":["《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃列传》","《清史稿·卷437·荣禄传》"]},{"k":"史料说明","v":"《清史稿》对维新人物及政变多持保守朝廷立场，并把围园、天津废立等记作讹传或议论。袁世凯告密的时点、密谋内容及其与政变的先后关系，仍需对读相关奏稿、日记与自述。","s":["《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃列传》","《清史稿·卷437·荣禄传》"]}],"steps":[{"t":"1898年，清廷在外部压力下讨论变法，光绪于旧历四月下诏定国是，要求讲求实政。朝廷随后连续发布改革命令，涉及教育、军队、工商与行政，百日维新的推行由此展开。","s":["《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃列传》","《清史稿·卷437·荣禄传》"]},{"t":"新政设京师大学堂，改革科举试文，提倡农工商和铁路矿务，并裁并部分冗署。政策颁行迅速，但执行仍需部院与各省配合，旧官员的去留和制度权限因而成为重要阻力。","s":["《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃列传》","《清史稿·卷437·荣禄传》"]},{"t":"光绪任用谭嗣同、杨锐、林旭、刘光第等参与新政，又因阻挠上书等事严厉处分大臣。改革支持者希望借皇帝直接用人突破阻力，太后与保守官员则对局势日益不安。","s":["《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃列传》","《清史稿·卷437·荣禄传》"]},{"t":"袁世凯受召，因练兵获得越级擢用，荣禄仍掌握北洋军务。宫廷中流传天津阅兵可能发生废立、有人计划围园等消息，《清史稿》分别记作传闻，军权与皇帝安全成为敏感焦点。","s":["《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃列传》","《清史稿·卷437·荣禄传》"]},{"t":"旧历八月初六，慈禧回宫重新训政，光绪居瀛台，朝廷以皇帝患病等名义发布安排。康有为等被查拿，原来围绕皇帝推进改革的人事体系失去支持，新政方向随之逆转。","s":["《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃列传》","《清史稿·卷437·荣禄传》"]},{"t":"谭嗣同、杨锐、林旭、刘光第、杨深秀、康广仁被杀，康有为、梁启超等出逃。多项新政被撤销，京师大学堂仍获保留，慈禧重新主持最高政务，光绪此后长期受限制。","s":["《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃列传》","《清史稿·卷437·荣禄传》"]}],"who":[{"side":"发动方","t":"清德宗、康有为等先推新政；慈禧太后随后重新训政。","s":["《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃列传》","《清史稿·卷437·荣禄传》"]},{"side":"对立方","t":"改革期间反对新政的官员；政变后为维新参与者。","s":["《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃列传》","《清史稿·卷437·荣禄传》"]}],"cities":["北京（蓟、幽州、燕京、中都、大都、北平、京师）"],"people":["清德宗","慈禧太后","康有为","梁启超","谭嗣同","荣禄","袁世凯","杨锐","林旭","刘光第"],"battles":[],"src":["《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃列传》","《清史稿·卷437·荣禄传》"],"line":"光绪推行新政引发朝廷权力冲突，慈禧重新训政，改革者被捕或出逃，多项新政随即撤销。","group":"政变与权力斗争","short":"戊戌政变","timeShort":"1898","placeShort":"北京","peopleShort":"清德宗、慈禧太后、康有为、谭嗣同","result":"变法中止，慈禧重新训政"},{"name":"国人暴动","tags":["民变","关键转折"],"g":"通说","lat":34.2,"lon":108.8,"f":[{"k":"时间","v":"前841。","s":["《史记·卷4·周本纪》"]},{"k":"地点","v":"陕西省西安市西南、山西省临汾市霍州市一带；古名镐京、彘。","s":["《史记·卷4·周本纪》"]},{"k":"起因","v":"周厉王任用荣夷公，试图把更多利益集中到王室，芮良夫担心这会激起广泛怨恨，劝谏未被接受。都城居民批评国王的统治，召公也指出百姓难以承受。厉王却把批评看成需要压制的声音，派人监视议论者，告发后加以杀戮，王室与国人的矛盾愈加尖锐。","s":["《史记·卷4·周本纪》"]},{"k":"结果与影响","v":"厉王出奔后，周朝王位没有转入新的家族，中央政务由大臣暂时主持。国人以集体行动迫使国王离都，说明王室统治受到都城政治力量的制约。太子后来继位为宣王，二相继续辅政，《史记》把这一阶段接在厉王失政之后叙述，既写王权中断，也写王室继承如何延续。《史记》又记宣王即位后修政，诸侯重新朝宗周室，把共和的结束与王朝整顿、恢复诸侯关系接续记述。","s":["《史记·卷4·周本纪》"]},{"k":"史料说明","v":"《史记》以“国人”描述参与者，未逐一交代其身份；共和部分记为召公、周公二相行政，太子静后来继位。","s":["《史记·卷4·周本纪》"]}],"steps":[{"t":"周厉王让荣夷公掌事，芮良夫劝他把利益分布于上下，国王仍坚持原来的用人。史书把这次争论放在暴动前面，交代王室逐利政策如何引起大臣和国人的不满。","s":["《史记·卷4·周本纪》"]},{"t":"国人议论朝政，厉王找来卫地巫者监视。有人被告发后遭杀害，公开批评随之减少，但恐惧也改变了都城日常交往，人们在路上只能以目光示意。","s":["《史记·卷4·周本纪》"]},{"t":"厉王以为自己制止了批评，向召公夸耀。召公以壅水为喻，劝他让不同身份的人陈述意见，使君主有机会知道政策的得失，厉王没有听从。","s":["《史记·卷4·周本纪》"]},{"t":"压制持续之后，国人联合攻击厉王，王都的政治秩序被打破。厉王无法继续留在都城，逃到彘，周王本人由此离开了王朝的权力中心。","s":["《史记·卷4·周本纪》"]},{"t":"太子静躲在召公家，国人得知后包围其宅。《史记》记召公设法保全太子，使王室继承人逃过追索，君位虽暂时空悬，王族的继承线索仍保留下来。","s":["《史记·卷4·周本纪》"]},{"t":"《史记》记召公、周公共同主持政务，称为共和。十四年后厉王死于彘，两位大臣迎立太子静，即周宣王，王朝才重新有了正式在位的周王。","s":["《史记·卷4·周本纪》"]}],"who":[{"side":"发动方","t":"周都国人。","s":["《史记·卷4·周本纪》"]},{"side":"对立方","t":"周厉王、荣夷公。","s":["《史记·卷4·周本纪》"]}],"cities":["西安（丰镐、长安）"],"people":["周厉王","周宣王","召公","周公","荣夷公"],"battles":[],"src":["《史记·卷4·周本纪》"],"line":"周厉王以严厉措施压制议论，国人起而攻王，厉王出奔彘，王朝进入共和行政时期。","group":"起义与民变","short":"国人暴动","timeShort":"前841","placeShort":"陕西西安西南","peopleShort":"周厉王、召公、周公","result":"厉王出奔，共和行政"},{"name":"陈胜吴广起义","tags":["农民起义","关键转折"],"g":"通说","lat":33.6,"lon":117.0,"f":[{"k":"时间","v":"前209年，旧历七月起。","s":["《史记·卷48·陈涉世家》"]},{"k":"地点","v":"安徽省宿州市、河南省周口市淮阳区一带；古名大泽乡、陈。","s":["《史记·卷48·陈涉世家》"]},{"k":"规模与伤亡","v":"《史记》史书所记大泽乡赴戍队伍为九百人，这是起事前同队戍卒的人数；到陈县时记步卒数万人，是沿途扩充后的队伍规模。","s":["《史记·卷48·陈涉世家》"]},{"k":"起因","v":"秦二世即位后继续征发戍卒。陈胜、吴广作为屯长，随队前往渔阳，途中因大雨受阻，停在大泽乡。《史记》记他们判断已经误期，将面临死刑，遂决定起兵；两人又借扶苏和楚将项燕的名义号召众人，把眼前的戍役危机同各地对秦朝统治的不满连接起来。","s":["《史记·卷48·陈涉世家》"]},{"k":"结果与影响","v":"陈胜称王前后仅数月，张楚的中心便告瓦解，吴广和主要西征将领也先后死亡。但《史记》记各地豪杰已因陈胜起事而纷纷举兵，秦朝必须同时面对多支队伍。此后项梁、项羽、刘邦等继续反秦，秦最终覆亡；陈胜发动的行动与后来完成灭秦的军事过程，在时间上前后相接。","s":["《史记·卷48·陈涉世家》"]},{"k":"史料说明","v":"《史记》以陈胜、吴广对误期处罚的判断解释起事，具体秦律适用另有讨论。鱼腹帛书、篝火狐鸣是该书所记发动手段，此处未展开。","s":["《史记·卷48·陈涉世家》"]}],"steps":[{"t":"前209年旧历七月，戍卒停驻大泽乡，陈胜与吴广商定行动。他们利用扶苏、项燕在民间的声望，准备以恢复楚国和反对秦廷为号召，争取同行者响应。","s":["《史记·卷48·陈涉世家》"]},{"t":"吴广激怒将尉，冲突中夺剑杀尉，陈胜协助杀死另一个将尉。两人召集戍卒，说明所处险境，众人盟誓起兵，推陈胜为将军、吴广为都尉。","s":["《史记·卷48·陈涉世家》"]},{"t":"队伍攻下大泽乡、蕲等地，沿路收兵，随后占领陈县。陈胜召集当地三老、豪杰商议，称王，号张楚，地方起事由此建立了自己的政治中心。","s":["《史记·卷48·陈涉世家》"]},{"t":"陈胜派吴广围攻荥阳，又派武臣、周市等向赵、魏故地发展。各地反秦队伍迅速增加，部分将领转而拥立本地国君，陈胜对各军的控制逐渐减弱。","s":["《史记·卷48·陈涉世家》"]},{"t":"周文率军西进，抵达关中戏地，秦廷命章邯征发骊山刑徒等迎战。周文接连退败，最终自杀，张楚向秦朝腹地进攻的力量受到重创。","s":["《史记·卷48·陈涉世家》"]},{"t":"围攻荥阳的将领发生内讧，田臧等杀死吴广，随后也败于秦军。章邯继续逼近陈县，陈胜退走途中被车夫庄贾杀害；吕臣后来收复陈地，诛杀庄贾。","s":["《史记·卷48·陈涉世家》"]}],"who":[{"side":"发动方","t":"陈胜、吴广、周文。","s":["《史记·卷48·陈涉世家》"]},{"side":"对立方","t":"秦二世、章邯、李由。","s":["《史记·卷48·陈涉世家》"]}],"cities":["荆州（郢、江陵）"],"people":["陈胜","吴广","秦二世","章邯","项羽","汉高祖"],"battles":[],"src":["《史记·卷48·陈涉世家》"],"line":"陈胜吴广在赴戍途中发动起事，号召各地反秦并建立张楚，秦朝统治由此陷入广泛危机。","group":"起义与民变","short":"陈胜吴广","timeShort":"前209","placeShort":"安徽宿州；河南周口淮阳","peopleShort":"陈胜、吴广","result":"建立张楚，后遭秦军击败"},{"name":"绿林赤眉起义","tags":["农民起义","改朝换代"],"g":"通说","lat":31.0,"lon":113.1,"f":[{"k":"时间","v":"17—27。","s":["《后汉书·卷11·刘玄刘盆子列传》","《后汉书·卷1上·光武帝纪上》"]},{"k":"地点","v":"湖北省中部、山东省东南部、陕西省西安市；古名绿林、莒、长安。","s":["《后汉书·卷11·刘玄刘盆子列传》","《后汉书·卷1上·光武帝纪上》"]},{"k":"起因","v":"王莽统治末年，南方饥荒严重，人们进入山泽采食，争夺食物，王匡、王凤因调解纠纷被推为首领，聚众藏入绿林。山东樊崇也在饥荒和地方动荡中起兵。两支力量各自扩展，新朝军队的进剿又推动他们整合部众，地方生计危机逐步演变为跨郡县的反抗。","s":["《后汉书·卷11·刘玄刘盆子列传》","《后汉书·卷1上·光武帝纪上》"]},{"k":"结果与影响","v":"绿林系统的更始政权直接取代新朝，使王莽于23年失去帝位和生命，故本事件带改朝换代标签。赤眉后来又推翻更始政权，但未能维持关中统治。汉光武帝在各军竞争中建立东汉，接受赤眉投降，继续统一各地；新朝的灭亡、刘玄的失败和东汉扩张，构成前后不同的阶段。","s":["《后汉书·卷11·刘玄刘盆子列传》","《后汉书·卷1上·光武帝纪上》"]},{"k":"史料说明","v":"绿林与赤眉各有首领和组织，并未始终由一个指挥中心统领。《后汉书》保存更始与赤眉的负面评价，也记载其饥荒背景和朝廷招降后的安置。","s":["《后汉书·卷11·刘玄刘盆子列传》","《后汉书·卷1上·光武帝纪上》"]}],"steps":[{"t":"王匡、王凤的队伍依托绿林活动，击退荆州方面的军队，人数增加。后来山中发生疫病，诸部分开行动，形成新市、下江等军，平林兵也加入起事。","s":["《后汉书·卷11·刘玄刘盆子列传》","《后汉书·卷1上·光武帝纪上》"]},{"t":"樊崇在山东聚众，逄安、徐宣等相继加入。与新朝军交战时，队伍涂眉为赤以相识别，史书因此称赤眉；他们与绿林诸部的组织和发展路线各有来源。","s":["《后汉书·卷11·刘玄刘盆子列传》","《后汉书·卷1上·光武帝纪上》"]},{"t":"23年，新市、平林等将领推刘玄为帝，建元更始，刘縯、汉光武帝参与的舂陵军也在这一联合体系中。更始军取得昆阳等胜利，随即分路向洛阳、长安进军。昆阳胜后，新朝在中原的主力受到重创。","s":["《后汉书·卷11·刘玄刘盆子列传》","《后汉书·卷1上·光武帝纪上》"]},{"t":"长安城内有人起兵攻王莽，更始军进入关中，王莽被杀，新朝灭亡。刘玄先都洛阳，再迁长安，却纵容将领争权，各地授官和军事号令逐渐混乱。","s":["《后汉书·卷11·刘玄刘盆子列传》","《后汉书·卷1上·光武帝纪上》"]},{"t":"赤眉西进，另立刘盆子为帝，25年攻入长安，刘玄出降后被杀。赤眉虽占据都城，却缺乏稳定供给，又与汉光武帝所部及关中各军反复交战。","s":["《后汉书·卷11·刘玄刘盆子列传》","《后汉书·卷1上·光武帝纪上》"]},{"t":"赤眉因缺粮向西转移，遇雪受困，又折返东行，沿途损失加重。27年在宜阳被汉光武帝军阻截，樊崇、刘盆子等投降，绿林、赤眉先后建立的政治中心均告终结。","s":["《后汉书·卷11·刘玄刘盆子列传》","《后汉书·卷1上·光武帝纪上》"]}],"who":[{"side":"发动方","t":"王匡、王凤、樊崇、刘玄、刘盆子。","s":["《后汉书·卷11·刘玄刘盆子列传》","《后汉书·卷1上·光武帝纪上》"]},{"side":"对立方","t":"王莽、新朝军队；后与汉光武帝争夺天下。","s":["《后汉书·卷11·刘玄刘盆子列传》","《后汉书·卷1上·光武帝纪上》"]}],"cities":["西安（丰镐、长安）","洛阳"],"people":["王莽","刘玄","刘盆子","汉光武帝","刘縯","樊崇"],"battles":["昆阳之战"],"src":["《后汉书·卷11·刘玄刘盆子列传》","《后汉书·卷1上·光武帝纪上》"],"line":"绿林与赤眉从地方起事发展成大军，绿林系统推立更始帝并推翻新朝，两军后来相继败亡。","group":"起义与民变","short":"绿林赤眉","timeShort":"17—27","placeShort":"湖北；山东；河南；陕西","peopleShort":"王匡、王凤、樊崇、刘玄、刘盆子","result":"新朝覆亡，更始、赤眉后败"},{"name":"黄巾起义","tags":["宗教与会党","农民起义","关键转折"],"g":"通说","lat":37.1,"lon":114.5,"f":[{"k":"时间","v":"184年，旧历二月事泄后起兵。","s":["《后汉书·卷71·皇甫嵩朱儁列传》"]},{"k":"地点","v":"河北省邢台市、河南省许昌市、南阳市等地；古名巨鹿、颍川、南阳。","s":["《后汉书·卷71·皇甫嵩朱儁列传》"]},{"k":"规模与伤亡","v":"《后汉书》史书所记太平道有三十六方，大方万余人、小方六七千人，这是起事前各方的组织人数口径；各方人数并非同一时点的军队点名册。","s":["《后汉书·卷71·皇甫嵩朱儁列传》"]},{"k":"起因","v":"张角长期以治病、传道的方式聚集信众，弟子分布于多地，逐渐组成太平道的地方组织。首领以改换天命的口号约定起兵，又同京师人员联络。184年计划被告发，朝廷逮捕相关人员，张角因而提前发动，原来隐蔽的宗教联系迅速转为公开的武装行动。","s":["《后汉书·卷71·皇甫嵩朱儁列传》"]},{"k":"结果与影响","v":"184年的主要黄巾队伍被镇压，张氏兄弟先后死亡，东汉朝廷保住了统治。战争调动中央将领、州郡官员和地方兵力，也使原有财政、生计困境更加严重。《后汉书》接着记皇甫嵩威望上升而朝政继续混乱，表明军事胜利没有消除政治危机；后来其他黄巾余部仍在不同地区活动。","s":["《后汉书·卷71·皇甫嵩朱儁列传》"]},{"k":"史料说明","v":"本传以“贼”称黄巾，是东汉朝廷及编史者的称呼。184年各主要战区的失败，与后来地方上继续以黄巾为号的活动，时间范围各有不同。","s":["《后汉书·卷71·皇甫嵩朱儁列传》"]}],"steps":[{"t":"张角把信众分为若干方，各设首领，通过弟子传教维系联系。原计划同京师内应配合，但唐周告发后，马元义被杀，朝廷又追查宫内外有关人员。","s":["《后汉书·卷71·皇甫嵩朱儁列传》"]},{"t":"张角得知事泄，立即通知各方起事，以黄巾作标识，自称天公将军，张宝、张梁分别称地公、人公将军。冀州、颍川、南阳等地相继出现攻打官府的队伍。","s":["《后汉书·卷71·皇甫嵩朱儁列传》"]},{"t":"东汉朝廷任皇甫嵩、朱儁、卢植分路出兵，京师加强守备，又解除党禁、征求地方兵力。朝廷试图同时缓和内部矛盾和组织军事反击，避免起事扩大。","s":["《后汉书·卷71·皇甫嵩朱儁列传》"]},{"t":"颍川方向，皇甫嵩、朱儁起初作战受挫，随后利用火攻等手段击败波才部，继续清理邻近郡县。南阳张曼成死后，继任首领据宛城坚持，朱儁围攻后破城。","s":["《后汉书·卷71·皇甫嵩朱儁列传》"]},{"t":"河北方向，卢植被征还，董卓接任后也未能取胜，皇甫嵩随后进军。张角已经病死，张梁仍据广宗抵抗，皇甫嵩趁其稍有懈怠发动进攻，张梁战死。","s":["《后汉书·卷71·皇甫嵩朱儁列传》"]},{"t":"皇甫嵩又与郭典攻下曲阳，张宝败亡，184年主要首领先后被消灭。朝廷改元中平，并对冀州饥民减免田租，战争留下的流离和其他地方武装仍未随之消失。","s":["《后汉书·卷71·皇甫嵩朱儁列传》"]}],"who":[{"side":"发动方","t":"张角、张宝、张梁、波才、张曼成。","s":["《后汉书·卷71·皇甫嵩朱儁列传》"]},{"side":"对立方","t":"汉灵帝、皇甫嵩、朱儁、卢植。","s":["《后汉书·卷71·皇甫嵩朱儁列传》"]}],"cities":["洛阳"],"people":["张角","汉灵帝","皇甫嵩","朱儁","卢植","董卓"],"battles":[],"src":["《后汉书·卷71·皇甫嵩朱儁列传》"],"line":"张角借太平道组织起事，东汉调动中央和地方军队镇压，主要首领败亡后各地仍有余部。","group":"起义与民变","short":"黄巾起义","timeShort":"184","placeShort":"河北、河南、山东等地","peopleShort":"张角、张宝、张梁、皇甫嵩、朱儁","result":"主要队伍被击败，地方战争持续"},{"name":"孙恩卢循起义","tags":["宗教与会党","民变"],"g":"通说","lat":30.0,"lon":120.6,"f":[{"k":"时间","v":"399—411。","s":["《晋书·卷100·孙恩卢循传》"]},{"k":"地点","v":"浙江省绍兴市、江苏省南京市、广东省广州市一带；古名会稽、建康、广州。","s":["《晋书·卷100·孙恩卢循传》"]},{"k":"起因","v":"孙恩家族奉五斗米道，其叔孙泰借宗教交往聚集信众，在东晋朝廷内外形成关系。孙泰因被指谋乱遭杀，孙恩逃到海上，继续招集部众。江南百姓又受到地方征发和权贵侵扰，社会不安，使海上力量有机会进入会稽，宗教组织、地方怨愤和朝廷内部动荡交织在一起。","s":["《晋书·卷100·孙恩卢循传》"]},{"k":"结果与影响","v":"起事使江南多个郡县遭受长期战争，又一度从广州扩展到建康城外。孙恩死后卢循仍保留水军，说明这一事件经历了首领更替、受官和再次举兵等阶段。卢循败亡后，东晋解除直接威胁，刘裕在平乱中进一步巩固军事地位，为后来掌握朝廷、取代晋室增加了力量和声望。","s":["《晋书·卷100·孙恩卢循传》"]},{"k":"史料说明","v":"《晋书》将孙恩、卢循列入对抗朝廷者的传记，兼载宗教活动和暴力行为；其中神异叙述反映信众及编史者的说法，未作为事实展开。","s":["《晋书·卷100·孙恩卢循传》"]}],"steps":[{"t":"399年孙恩从海上攻入上虞、会稽，杀死地方官。会稽及附近多个郡县相继响应，孙恩自号征东将军，以宗教身份和军事组织聚集人员，东晋朝廷大为震动。","s":["《晋书·卷100·孙恩卢循传》"]},{"t":"谢琰、刘牢之奉命进军，孙恩在陆地受压后撤回海上，却仍能反复登陆。400年又攻会稽，谢琰战死，沿海与内地之间的来回转移，使官军难以一次结束战事。","s":["《晋书·卷100·孙恩卢循传》"]},{"t":"401年孙恩再度沿海北上，进逼长江口和建康方向。刘裕在追击、截击中逐渐取得战功，孙恩未能夺取京师，后来在沿海行动中接连受挫。","s":["《晋书·卷100·孙恩卢循传》"]},{"t":"402年孙恩攻临海失败后投海，卢循接领余众。卢循此后南下广州，一度接受东晋官号，地方武装与中央之间出现暂时妥协，原有部众和水军却仍然保留。","s":["《晋书·卷100·孙恩卢循传》"]},{"t":"410年刘裕北伐南燕，卢循、徐道覆乘机北上，击败何无忌、刘毅等部，顺江逼近建康。刘裕及时返回组织守御，双方在京师附近相持，卢循最终未能破城。","s":["《晋书·卷100·孙恩卢循传》"]},{"t":"刘裕转入追击，徐道覆败亡，卢循沿江退回南方，广州也已失守。411年卢循再入交州，被杜慧度击败，投水而死，持续十余年的孙恩、卢循武装活动告终。","s":["《晋书·卷100·孙恩卢循传》"]}],"who":[{"side":"发动方","t":"孙恩、卢循、徐道覆。","s":["《晋书·卷100·孙恩卢循传》"]},{"side":"对立方","t":"谢琰、刘牢之、刘裕、杜慧度。","s":["《晋书·卷100·孙恩卢循传》"]}],"cities":["南京（建业、建康、金陵、应天、天京）","番禺"],"people":["孙恩","卢循","刘裕","刘牢之","谢琰","杜慧度"],"battles":[],"src":["《晋书·卷100·孙恩卢循传》"],"line":"孙恩在东南沿海聚众起事，卢循继领余部并一度逼近建康，最终被刘裕等击败，退往交州。","group":"起义与民变","short":"孙恩卢循","timeShort":"399—411","placeShort":"浙江、江苏、广东、越南北部","peopleShort":"孙恩、卢循、刘裕","result":"首领败亡，东晋渡过危机"},{"name":"隋末农民战争","tags":["农民起义","改朝换代"],"g":"通说","lat":34.9,"lon":114.0,"f":[{"k":"时间","v":"611—618。","s":["《隋书·卷70·李密传》","《旧唐书·卷54·窦建德传》","《旧唐书·卷56·杜伏威传》","《隋书·卷4·炀帝纪下》","《旧唐书·卷1·高祖本纪》"]},{"k":"地点","v":"山东省、河南省郑州市、河北省及江苏省扬州市一带；古名长白山、瓦岗、河北、江都。","s":["《隋书·卷70·李密传》","《旧唐书·卷54·窦建德传》","《旧唐书·卷56·杜伏威传》","《隋书·卷4·炀帝纪下》","《旧唐书·卷1·高祖本纪》"]},{"k":"起因","v":"隋炀帝连年动员兵员、粮食和劳力，辽东战争与地方水旱加重了百姓负担。失去生计的人聚集山泽，逃亡者和地方豪杰也加入队伍。官府进剿未能使各地恢复稳定，新的首领不断出现；瓦岗、河北和江淮各军在扩充过程中形成不同政治中心，隋廷的号令渐难贯彻。","s":["《隋书·卷70·李密传》","《旧唐书·卷54·窦建德传》","《旧唐书·卷56·杜伏威传》","《隋书·卷4·炀帝纪下》","《旧唐书·卷1·高祖本纪》"]},{"k":"结果与影响","v":"隋末各地起事破坏了隋廷的征收和军事动员，多个区域政权相继出现。618年隋炀帝被杀、长安唐朝建立，是这一轮中央政权崩解的重要节点，洛阳隋政权则继续至619年。瓦岗、河北、江淮各军的结局各不相同，唐朝的统一也在其后逐步完成，战争并未随隋炀帝之死同时结束。","s":["《隋书·卷70·李密传》","《旧唐书·卷54·窦建德传》","《旧唐书·卷56·杜伏威传》","《隋书·卷4·炀帝纪下》","《旧唐书·卷1·高祖本纪》"]},{"k":"史料说明","v":"本事件按清单以611—618年为主线，部分首领活动延至唐初。李密、窦建德、杜伏威各有独立队伍，后来归唐、败亡的经过分属不同阶段。","s":["《隋书·卷70·李密传》","《旧唐书·卷54·窦建德传》","《旧唐书·卷56·杜伏威传》","《隋书·卷4·炀帝纪下》","《旧唐书·卷1·高祖本纪》"]}],"steps":[{"t":"611年前后，山东等地已有聚众反抗征发的队伍，后来起事遍及多地。隋军往返征讨，地方官吏、逃亡者和失业百姓不断卷入，最初分散的行动逐渐形成大股武装。","s":["《隋书·卷70·李密传》","《旧唐书·卷54·窦建德传》","《旧唐书·卷56·杜伏威传》","《隋书·卷4·炀帝纪下》","《旧唐书·卷1·高祖本纪》"]},{"t":"翟让在瓦岗聚众，单雄信、徐世勣等加入；李密参与杨玄感行动失败后辗转投奔瓦岗。李密主张夺取粮仓、扩大号召，队伍由地方据点向洛阳周围发展。","s":["《隋书·卷70·李密传》","《旧唐书·卷54·窦建德传》","《旧唐书·卷56·杜伏威传》","《隋书·卷4·炀帝纪下》","《旧唐书·卷1·高祖本纪》"]},{"t":"瓦岗军击败张须陀，继而取得洛口仓等粮源，开仓吸引饥民。李密被推为魏公，设置官属，但与翟让的权力冲突加深，最终杀死翟让，内部关系受到破坏。","s":["《隋书·卷70·李密传》","《旧唐书·卷54·窦建德传》","《旧唐书·卷56·杜伏威传》","《隋书·卷4·炀帝纪下》","《旧唐书·卷1·高祖本纪》"]},{"t":"河北方面，窦建德在各部竞争中扩展，收纳人员、建立政权；江淮杜伏威也聚众出兵，逐步控制地方。各军分据区域，既反抗隋廷，也各自争夺地盘和人口。","s":["《隋书·卷70·李密传》","《旧唐书·卷54·窦建德传》","《旧唐书·卷56·杜伏威传》","《隋书·卷4·炀帝纪下》","《旧唐书·卷1·高祖本纪》"]},{"t":"617年唐高祖在太原起兵，进入长安，拥立隋恭帝。618年江都军队杀死隋炀帝，长安方面随后改建唐朝；洛阳仍拥立隋宗室，隋的中央统治分裂成不同残局。","s":["《隋书·卷70·李密传》","《旧唐书·卷54·窦建德传》","《旧唐书·卷56·杜伏威传》","《隋书·卷4·炀帝纪下》","《旧唐书·卷1·高祖本纪》"]},{"t":"618年李密与宇文化及交战后实力受损，又败于王世充，转而入唐。窦建德、杜伏威等继续据地活动，隋朝覆亡后的区域战争仍延续，后来由唐军逐步处理。","s":["《隋书·卷70·李密传》","《旧唐书·卷54·窦建德传》","《旧唐书·卷56·杜伏威传》","《隋书·卷4·炀帝纪下》","《旧唐书·卷1·高祖本纪》"]}],"who":[{"side":"发动方","t":"翟让、李密、窦建德、杜伏威等。","s":["《隋书·卷70·李密传》","《旧唐书·卷54·窦建德传》","《旧唐书·卷56·杜伏威传》","《隋书·卷4·炀帝纪下》","《旧唐书·卷1·高祖本纪》"]},{"side":"对立方","t":"隋炀帝、张须陀、王世充及隋军诸将。","s":["《隋书·卷70·李密传》","《旧唐书·卷54·窦建德传》","《旧唐书·卷56·杜伏威传》","《隋书·卷4·炀帝纪下》","《旧唐书·卷1·高祖本纪》"]}],"cities":["西安（丰镐、长安）","洛阳"],"people":["隋炀帝","李密","翟让","窦建德","杜伏威","唐高祖","王世充"],"battles":["虎牢之战"],"src":["《隋书·卷70·李密传》","《旧唐书·卷54·窦建德传》","《旧唐书·卷56·杜伏威传》","《隋书·卷4·炀帝纪下》","《旧唐书·卷1·高祖本纪》"],"line":"隋末各地起事在征役与饥荒中扩展，瓦岗等势力冲击隋朝统治，隋亡后群雄仍继续争夺。","group":"起义与民变","short":"隋末农民战争","timeShort":"611—618","placeShort":"山东、河南、河北、安徽等地","peopleShort":"翟让、李密、窦建德、杜伏威","result":"隋朝覆亡，各路政权继续争夺"},{"name":"庞勋起义","tags":["兵变","民变"],"g":"通说","lat":34.3,"lon":117.2,"f":[{"k":"时间","v":"868年旧历七月—869年旧历九月。","s":["《资治通鉴·卷251·唐纪六十七》"]},{"k":"地点","v":"广西壮族自治区桂林市、江苏省徐州市及淮河流域；古名桂州、徐州、泗州。","s":["《资治通鉴·卷251·唐纪六十七》"]},{"k":"规模与伤亡","v":"《资治通鉴》史书所记徐泗募兵二千，其中八百人分戍桂州；八百是分驻一地的戍卒人数，二千是最初招募总数。","s":["《资治通鉴·卷251·唐纪六十七》"]},{"k":"起因","v":"徐泗士兵远戍桂州，原约三年轮换，却被长期留驻。地方军费紧张，军府又决定延缓换防，戍卒因此愤怒。他们既思念家乡，也怨恨军将的管束，趁桂管长官更替时杀将北归。朝廷虽一度赦免，却没有消除他们对归镇后受罚的恐惧，擅自返乡遂转化为夺取徐州的行动。","s":["《资治通鉴·卷251·唐纪六十七》"]},{"k":"结果与影响","v":"庞勋未能获得节度使名位，徐州根据地失守后，起事迅速瓦解。事件起于换防失信，发展中又叠加军镇任命、地方参与和交通争夺，唐廷为镇压调动多道兵力。沙陀骑兵因作战受重用，朱邪赤心一系由此进一步进入中央军事体系，晚唐藩镇与军人集团的关系也随之变化。","s":["《资治通鉴·卷251·唐纪六十七》"]},{"k":"史料说明","v":"《资治通鉴》记桂州原分戍八百人，这是北归前一支戍军的口径；以后招集的军民远多于最初戍卒。“贼”等称呼来自官军叙事。","s":["《资治通鉴·卷251·唐纪六十七》"]}],"steps":[{"t":"868年旧历七月，许佶等杀死都将，推粮料判官庞勋为首，夺取兵器北归。朝廷派使赦免，安排沿途护送，队伍暂时收敛掠夺，继续向徐州方向移动。","s":["《资治通鉴·卷251·唐纪六十七》"]},{"t":"北归途中，首领担心回镇后遭清算，重新制造兵器、招集人员。到徐州附近，又要求罢免所怨军将、另设营伍，军府不肯接受，双方的最后协商破裂。","s":["《资治通鉴·卷251·唐纪六十七》"]},{"t":"庞勋等击破阻截，进入徐州，拘禁并杀死观察使崔彦曾及亲近军将。占领本镇后，吸收当地军民，提出取得节度使名位的要求，行动已超出单纯返乡。","s":["《资治通鉴·卷251·唐纪六十七》"]},{"t":"朝廷拒绝以节度使相授，任康承训等分路进剿，朱邪赤心率沙陀骑兵参战。庞勋军向泗州等地发展，争夺淮河运输线，围城与断粮使战事牵动更大区域。","s":["《资治通鉴·卷251·唐纪六十七》"]},{"t":"869年官军接连击败庞勋部，原来被驱使随军的百姓又不断离去。庞勋内部因败仗互相责备，军将对能否继续抵抗出现分歧，徐州周围的据点逐步失守。","s":["《资治通鉴·卷251·唐纪六十七》"]},{"t":"张玄稔转而归附朝廷，帮助官军夺取徐州。庞勋回救不及，转战途中败亡，其余队伍相继被消灭；朱邪赤心因功得到朝廷奖赏，沙陀军事力量在唐廷中的地位上升。","s":["《资治通鉴·卷251·唐纪六十七》"]}],"who":[{"side":"发动方","t":"庞勋、许佶、姚周等戍卒。","s":["《资治通鉴·卷251·唐纪六十七》"]},{"side":"对立方","t":"唐懿宗、康承训、朱邪赤心、张玄稔。","s":["《资治通鉴·卷251·唐纪六十七》"]}],"cities":[],"people":["庞勋","唐懿宗","康承训","朱邪赤心"],"battles":[],"src":["《资治通鉴·卷251·唐纪六十七》"],"line":"徐州戍卒因归期拖延发动兵变，北返后占据徐州并与朝廷交战，唐廷调军镇压，庞勋败死。","group":"起义与民变","short":"庞勋起义","timeShort":"868—869","placeShort":"广西桂林；江苏徐州","peopleShort":"庞勋、崔彦曾、康承训","result":"徐州失守，庞勋败死"},{"name":"黄巢起义","tags":["农民起义","关键转折"],"g":"通说","lat":34.3,"lon":108.9,"f":[{"k":"时间","v":"875—884。","s":["《旧唐书·卷200下·黄巢传》"]},{"k":"地点","v":"山东省菏泽市、广东省广州市、陕西省西安市等地；古名曹州、广州、长安。","s":["《旧唐书·卷200下·黄巢传》"]},{"k":"起因","v":"唐末河南等地连年灾荒，饥民聚集，王仙芝、尚君长等首先起兵，黄巢也组织队伍加入。官府镇压与招抚反复，首领之间对接受官职意见不同，原有联合逐渐分开。朝廷和藩镇各有打算，招讨号令时有牵制，使流动队伍能够在多个地区转移、补充人员和寻找立足之地。","s":["《旧唐书·卷200下·黄巢传》"]},{"k":"结果与影响","v":"黄巢的大齐政权控制长安数年，最后失去都城和主力，唐朝仍然存在。战争却使中央禁军、财政和地方控制受到重创，唐廷收复京师又依靠各地藩镇。朱温、李克用等因战争取得更大势力，黄巢败亡之后，中央与军镇的关系没有恢复到战前，晚唐的权力竞争继续加深。","s":["《旧唐书·卷200下·黄巢传》"]},{"k":"史料说明","v":"本传属于唐廷一方的记述，招抚、死亡细节在其他史籍中有差别。880年旧历十二月进入长安，公历已在881年初；大齐建立与唐朝灭亡分属不同事件。","s":["《旧唐书·卷200下·黄巢传》"]}],"steps":[{"t":"875年前后，王仙芝等在濮阳一带起事，黄巢部在山东响应。队伍攻取州县，并通过檄文指责朝政，最初的地方行动逐渐扩展到河南、湖北等区域。","s":["《旧唐书·卷200下·黄巢传》"]},{"t":"唐廷一面出兵，一面提出赦罪授官，起事首领对此出现分歧。招抚交涉又夹杂官军争功、杀死来使等事，王仙芝最终败亡，余部转归黄巢，尚让成为重要将领。","s":["《旧唐书·卷200下·黄巢传》"]},{"t":"黄巢率军南下，跨越江淮、岭南，占领广州，并向朝廷索取节度使等官职，未获所求。南方停留之后，队伍重新北进，战争的方向转向长江和中原。","s":["《旧唐书·卷200下·黄巢传》"]},{"t":"黄巢军渡江、渡淮后，唐军防线接连失利，洛阳失守。880年旧历十二月，队伍突破潼关、进入长安，唐僖宗出奔，黄巢随后称帝，国号大齐。","s":["《旧唐书·卷200下·黄巢传》"]},{"t":"占领都城后，黄巢面对关中粮食供应和唐军反攻的压力。朱温等将领转降唐廷，李克用率沙陀军参战，883年各路唐军进入长安，黄巢退出关中。","s":["《旧唐书·卷200下·黄巢传》"]},{"t":"黄巢转入河南，围攻陈州未下，又受唐军追击，部将不断离散。884年退至山东后败亡，《旧唐书》记林言杀黄巢、献其首，长期流动作战至此失去主要中心。","s":["《旧唐书·卷200下·黄巢传》"]}],"who":[{"side":"发动方","t":"王仙芝、黄巢、尚让。","s":["《旧唐书·卷200下·黄巢传》"]},{"side":"对立方","t":"唐僖宗、高骈、王铎、李克用等。","s":["《旧唐书·卷200下·黄巢传》"]}],"cities":["西安（丰镐、长安）","洛阳","番禺"],"people":["黄巢","王仙芝","尚让","唐僖宗","朱温","李克用"],"battles":["黄巢攻陷长安"],"src":["《旧唐书·卷200下·黄巢传》"],"line":"王仙芝黄巢相继聚众起事，黄巢军纵贯南北并在长安建大齐，唐廷反攻后其政权瓦解。","group":"起义与民变","short":"黄巢起义","timeShort":"875—884","placeShort":"山东、河南、广东、陕西等地","peopleShort":"王仙芝、黄巢、唐僖宗","result":"大齐失去长安，黄巢败亡"},{"name":"王小波李顺起义","tags":["农民起义","民变"],"g":"部分待核","lat":30.7,"lon":104.1,"f":[{"k":"时间","v":"993年春—995年。","s":["《宋史纪事本末·卷16·蜀盗之平》"]},{"k":"地点","v":"四川省眉山市、成都市、广元市一带；古名青神、成都、剑门。","s":["《宋史纪事本末·卷16·蜀盗之平》"]},{"k":"起因","v":"宋灭后蜀后，府库财富运往京师，地方又在常赋之外加重经营征取，设置博买务限制布帛交易。蜀地人口稠密，贫民生计紧张，兼并和贸易中的获利又加剧不满。王小波以均贫富号召聚众，穷人相继依附，对地方官府的反抗很快从青神、彭山扩展到成都平原。","s":["《宋史纪事本末·卷16·蜀盗之平》"]},{"k":"结果与影响","v":"李顺在成都建立的政权被宋军摧毁，张余等余部也相继失败，宋廷恢复对四川主要城市的控制。战争暴露了地方征取、官吏施政与贫民生活之间的矛盾。善后既有军事追剿，也有张咏招抚、筹粮等措施；朝廷对将领和宦官的授赏，则又牵动中央如何限制近侍参与政务的问题。","s":["《宋史纪事本末·卷16·蜀盗之平》"]},{"k":"史料说明","v":"“均贫富”据《宋史纪事本末》所记王小波号召。该书记成都破后李顺被获，后世对其结局另有讨论，具体逃脱说的史料对应〔待核〕。","s":["《宋史纪事本末·卷16·蜀盗之平》"]}],"steps":[{"t":"993年王小波在青神一带聚众，以改变贫富不均号召追随者，攻取青神、彭山等地。当地百姓和其他队伍响应，宋廷原有的州县治安措施逐渐失效。","s":["《宋史纪事本末·卷16·蜀盗之平》"]},{"t":"同年十二月，王小波在江原与宋军交战中受伤，随后死亡。部众推其妻弟李顺继续领导，队伍攻取邛州、永康军等地，行动并未随最初首领之死结束。","s":["《宋史纪事本末·卷16·蜀盗之平》"]},{"t":"994年正月，李顺攻下汉州、彭州，进而进入成都，自称大蜀王，建立官属。成都官员退走梓州，起事由地方聚众发展为占据大城市的政治力量。","s":["《宋史纪事本末·卷16·蜀盗之平》"]},{"t":"北宋太宗决定调兵镇压，任王继恩为两川招安使。李顺分兵争夺剑门，遭上官正等击退，宋军得以保住进川通路，随后向成都及周边推进。","s":["《宋史纪事本末·卷16·蜀盗之平》"]},{"t":"994年五月宋军收复成都，《宋史纪事本末》记李顺被获。张余等仍转战嘉、戎、泸、渝诸州，成都中心失守后，战事沿川江继续向外发展。","s":["《宋史纪事本末·卷16·蜀盗之平》"]},{"t":"张咏到任后推动官军继续进剿，又招抚被裹挟的百姓、安排粮食。995年张余被捕，主要队伍先后败亡，朝廷也以诏书承认地方官刻削、用人失当造成的责任。","s":["《宋史纪事本末·卷16·蜀盗之平》"]}],"who":[{"side":"发动方","t":"王小波、李顺、张余。","s":["《宋史纪事本末·卷16·蜀盗之平》"]},{"side":"对立方","t":"北宋太宗、王继恩、上官正、张咏。","s":["《宋史纪事本末·卷16·蜀盗之平》"]}],"cities":["成都"],"people":["王小波","李顺","张余","北宋太宗","王继恩","张咏"],"battles":[],"src":["《宋史纪事本末·卷16·蜀盗之平》"],"line":"王小波以均贫富号召聚众，李顺继领并占据成都建立政权，宋军反攻破城，各地余部续战。","group":"起义与民变","short":"王小波李顺","timeShort":"993—995","placeShort":"四川成都、眉山等地","peopleShort":"王小波、李顺、王继恩","result":"成都政权覆灭，余部续战"},{"name":"方腊起义","tags":["宗教与会党","农民起义"],"g":"通说","lat":29.6,"lon":119.0,"f":[{"k":"时间","v":"1120年旧历十月—1122年旧历三月。","s":["《宋史·卷468·童贯传》"]},{"k":"地点","v":"浙江省杭州市淳安县、杭州市及安徽省黄山市一带；古名青溪、杭州、歙州。","s":["《宋史·卷468·童贯传》"]},{"k":"规模与伤亡","v":"《宋史》史书所记童贯所率禁旅及秦晋蕃汉兵为十五万，是朝廷东下军队的合计数；又记方腊军攻陷六州五十二县，这是受影响的行政区数量。","s":["《宋史·卷468·童贯传》"]},{"k":"起因","v":"江南因采办花石和应奉差役受到侵扰，民间积怨。睦州山谷出产漆、楮、杉木，商人往来频繁，也为聚众提供了人员和交通条件。方腊利用宗教活动联络贫民，乘不满扩大而起兵。地方长期承平、缺乏作战准备，官军起初失利，使起事迅速越出一个县的范围。","s":["《宋史·卷468·童贯传》"]},{"k":"结果与影响","v":"方腊建立的地方政权未能维持，宋军收复江南城邑，余部也在次年陆续被镇压。战争破坏州县与民生，也迫使朝廷暂时处理花石应奉等积弊。童贯因平定获得更高爵位，随后又转入北方军事行动；江南战事与北宋后期中央的用人、财政及军事调度相互牵连。","s":["《宋史·卷468·童贯传》"]},{"k":"史料说明","v":"《宋史》称方腊所用宗教为“左道”，其具体教派归属另有讨论。本传所列大规模杀伤数字带有镇压一方的叙事口径，城市数与兵额分项列示。","s":["《宋史·卷468·童贯传》"]}],"steps":[{"t":"1120年旧历十月，方腊在青溪起兵，自号圣公，建元永乐，设置官吏和将帅。队伍以不同头巾区别等级，宗教联络转为组织军队、建立名号的行动。","s":["《宋史·卷468·童贯传》"]},{"t":"方腊军击败前来镇压的宋军，随后进入青溪、睦州、歙州，又向衢州发展。地方守备接连失利，首领和其他响应队伍借机取得更多城邑与物资。","s":["《宋史·卷468·童贯传》"]},{"t":"队伍沿桐庐、富阳逼近杭州，守臣弃城，杭州失守。朱言、吴邦、吕师囊等在各地响应，宋廷面对的已是多支分布在江南的武装，地方警报不断传入京师。","s":["《宋史·卷468·童贯传》"]},{"t":"朝廷调童贯、谭稹统兵东下，军事动员原与北方计划相连，随后转用于江南。皇帝又下令停罢相关应奉机构，试图在进剿同时减轻引发民怨的征取。","s":["《宋史·卷468·童贯传》"]},{"t":"1121年宋军击败攻秀州的方七佛部，继而水陆并进，收复杭州及其他失地。方腊退入青溪山区，凭借洞穴与山谷继续抵抗，活动空间日益缩小。","s":["《宋史·卷468·童贯传》"]},{"t":"1121年旧历四月，宋军在梓桐一带俘获方腊及家属、官属。方腊政权失去中心后，地方余部仍然活动，《宋史》记至1122年三月才全部平定。","s":["《宋史·卷468·童贯传》"]}],"who":[{"side":"发动方","t":"方腊、方七佛、吕师囊等。","s":["《宋史·卷468·童贯传》"]},{"side":"对立方","t":"北宋徽宗、童贯、谭稹、辛兴宗等。","s":["《宋史·卷468·童贯传》"]}],"cities":["杭州（临安）"],"people":["方腊","童贯","北宋徽宗"],"battles":[],"src":["《宋史·卷468·童贯传》"],"line":"方腊在睦州起事后迅速扩展到江南多州，宋廷调兵反攻，方腊被俘后各处余部仍继续抵抗。","group":"起义与民变","short":"方腊起义","timeShort":"1120—1122","placeShort":"浙江、安徽、江苏、江西","peopleShort":"方腊、童贯","result":"方腊被俘，余部陆续平定"},{"name":"钟相杨幺起义","tags":["宗教与会党","农民起义"],"g":"通说","lat":29.0,"lon":111.7,"f":[{"k":"时间","v":"1130年旧历二月—1135年。","s":["《宋史纪事本末·卷66·平群盗》","《宋史·卷365·岳飞传》"]},{"k":"地点","v":"湖南省常德市、汉寿县及洞庭湖一带；古名鼎州、龙阳、洞庭湖。","s":["《宋史纪事本末·卷66·平群盗》","《宋史·卷365·岳飞传》"]},{"k":"起因","v":"南宋初年金军南下，地方守备破碎，北来军队与地方武装争夺粮食、船只和人口。鼎州钟相原有宗教信众，又以组织忠义、保护乡里为名聚集人员，趁官府失去控制而称王。钟相失败后，湖区首领继续建立水寨，利用水网和耕作供给维持队伍，与官军长期相持。","s":["《宋史纪事本末·卷66·平群盗》","《宋史·卷365·岳飞传》"]},{"k":"结果与影响","v":"钟相建立的楚王政权短暂存在，杨幺等却依托洞庭湖继续坚持数年，前后组织与作战条件已有变化。岳飞采用招降、分化和进攻相结合的办法，解除南宋在长江中游的内部军事威胁，也吸收了部分湖区兵员。战争结束后，朝廷得以加强对湖区州县和交通的控制，转用兵力处理其他方向的局势。","s":["《宋史纪事本末·卷66·平群盗》","《宋史·卷365·岳飞传》"]},{"k":"史料说明","v":"杨幺在古籍中亦作杨么、杨太。钟相早期经过据《宋史纪事本末》，岳飞招降及湖区结局据《宋史·岳飞传》；两人的阶段与部众分别叙述。","s":["《宋史纪事本末·卷66·平群盗》","《宋史·卷365·岳飞传》"]}],"steps":[{"t":"1130年钟相在鼎州一带起事，自称楚王，改元天载，进攻澧州等地。宗教号召和地方保护组织结合，使活动迅速扩展到官军控制薄弱的州县。","s":["《宋史纪事本末·卷66·平群盗》","《宋史·卷365·岳飞传》"]},{"t":"孔彦舟率军进入鼎州，随后攻破钟相所部，捕获钟相及其子钟子昂，押送处置。钟相的称王行动很快失败，但各地已聚集起来的队伍并未全部解散。","s":["《宋史纪事本末·卷66·平群盗》","《宋史·卷365·岳飞传》"]},{"t":"杨幺等在龙阳和洞庭湖周围继续活动，建立水寨，利用湖泊、港汊和舟船相互接应。首领各领部众，官军在水战、地形和供给方面面临困难，战事拖延数年。","s":["《宋史纪事本末·卷66·平群盗》","《宋史·卷365·岳飞传》"]},{"t":"1135年朝廷命岳飞招捕杨幺，张浚督师。岳飞先派人招谕，黄佐率部投降，随后受命返回湖区，劝降其他首领或袭击仍坚持抵抗的据点。","s":["《宋史纪事本末·卷66·平群盗》","《宋史·卷365·岳飞传》"]},{"t":"岳飞继续争取杨钦等，利用归降人员熟悉湖区的条件，削弱杨幺的船只、部众与外部联系。湖区各寨原来的相互支援逐渐瓦解，官军得以集中力量推进。","s":["《宋史纪事本末·卷66·平群盗》","《宋史·卷365·岳飞传》"]},{"t":"官军趁水势和水道条件变化展开进攻，杨幺败亡，各寨相继投降或被攻下。岳飞接收其中壮丁入军，并让老弱归业，持续到1135年的湖区对抗结束。","s":["《宋史纪事本末·卷66·平群盗》","《宋史·卷365·岳飞传》"]}],"who":[{"side":"发动方","t":"钟相、杨幺、杨钦、黄佐等。","s":["《宋史纪事本末·卷66·平群盗》","《宋史·卷365·岳飞传》"]},{"side":"对立方","t":"孔彦舟、岳飞、张浚。","s":["《宋史纪事本末·卷66·平群盗》","《宋史·卷365·岳飞传》"]}],"cities":[],"people":["钟相","杨幺","岳飞","张浚","孔彦舟"],"battles":[],"src":["《宋史纪事本末·卷66·平群盗》","《宋史·卷365·岳飞传》"],"line":"钟相起事失败后，杨幺等依托洞庭湖继续抵抗，南宋调岳飞招降与进攻，最终瓦解湖区势力。","group":"起义与民变","short":"钟相杨幺","timeShort":"1130—1135","placeShort":"湖南常德、洞庭湖一带","peopleShort":"钟相、杨幺、岳飞","result":"钟相先死，杨幺部后被击败"},{"name":"红巾军起义","tags":["农民起义","宗教与会党","改朝换代"],"g":"通说","lat":32.9,"lon":115.8,"f":[{"k":"时间","v":"1351—1368。","s":["《元史·卷42·顺帝本纪五》","《明史·卷1·太祖本纪一》","《明史·卷2·太祖本纪二》"]},{"k":"地点","v":"安徽省阜阳市、凤阳县、江苏省南京市、北京市等地；古名颍州、濠州、应天、大都。","s":["《元史·卷42·顺帝本纪五》","《明史·卷1·太祖本纪一》","《明史·卷2·太祖本纪二》"]},{"k":"起因","v":"元末水灾、饥荒与地方动荡相继发生，黄河治理又动员大批军民。韩山童利用白莲会传统和弥勒下生等说法聚集信众，刘福通等以恢复宋室的名义策划起兵。官府搜捕使计划提前暴露，多地首领随后各自举兵，以红巾作为标识，形成彼此联系又各有组织的反元力量。","s":["《元史·卷42·顺帝本纪五》","《明史·卷1·太祖本纪一》","《明史·卷2·太祖本纪二》"]},{"k":"结果与影响","v":"红巾军先后建立宋、天完等政权，明太祖从其中一支发展，消灭主要竞争者并于1368年建立明朝，故本事件带改朝换代标签。元朝在中原的中央统治随后结束，北方蒙古政权仍然延续。各支红巾队伍既共同冲击元廷，也经历分裂和兼并，明朝统一是多年竞争后的结果。","s":["《元史·卷42·顺帝本纪五》","《明史·卷1·太祖本纪一》","《明史·卷2·太祖本纪二》"]},{"k":"史料说明","v":"《元史》以“妖”“寇”描述宗教宣传和反元者，《明史》则以明朝建立者为中心组织材料。红巾是多支队伍共有的标识，各部建政和指挥体系各自发展。","s":["《元史·卷42·顺帝本纪五》","《明史·卷1·太祖本纪一》","《明史·卷2·太祖本纪二》"]}],"steps":[{"t":"1351年刘福通等准备与韩山童起事，官府追捕时韩山童被擒，刘福通攻取颍州，以红巾为号。队伍很快向河南各地扩展，元廷调遣军队镇压。","s":["《元史·卷42·顺帝本纪五》","《明史·卷1·太祖本纪一》","《明史·卷2·太祖本纪二》"]},{"t":"同年徐寿辉等在湖北起兵，也以红巾为号，随后建天完政权。1352年郭子兴等攻取濠州，明太祖加入其军，南北各部逐步形成不同的政治与军事中心。","s":["《元史·卷42·顺帝本纪五》","《明史·卷1·太祖本纪一》","《明史·卷2·太祖本纪二》"]},{"t":"刘福通后来拥立韩林儿，国号宋、建元龙凤，分兵向北发展。南方各军也争取州县和粮源，元廷既需多路作战，内部又因罢免脱脱等事削弱原有军事部署。","s":["《元史·卷42·顺帝本纪五》","《明史·卷1·太祖本纪一》","《明史·卷2·太祖本纪二》"]},{"t":"明太祖从濠州系统中发展，渡江占领集庆，改为应天府，逐步设置官署、整顿赋税和军队。名义上仍接受韩林儿政权号令，实际经营长江下游根据地。","s":["《元史·卷42·顺帝本纪五》","《明史·卷1·太祖本纪一》","《明史·卷2·太祖本纪二》"]},{"t":"南方各政权互相兼并，陈友谅取代徐寿辉后与明太祖竞争，随后败亡；张士诚势力也被明太祖消灭。北方红巾各军受到元军打击，各部没有统一归于同一首领。","s":["《元史·卷42·顺帝本纪五》","《明史·卷1·太祖本纪一》","《明史·卷2·太祖本纪二》"]},{"t":"1368年明太祖在应天即皇帝位，建立明朝，徐达等率军北进，大都失守，元顺帝北走。红巾起事所打开的局面，最终由明朝整合成新的中央政权。","s":["《元史·卷42·顺帝本纪五》","《明史·卷1·太祖本纪一》","《明史·卷2·太祖本纪二》"]}],"who":[{"side":"发动方","t":"韩山童、刘福通、徐寿辉、郭子兴、明太祖。","s":["《元史·卷42·顺帝本纪五》","《明史·卷1·太祖本纪一》","《明史·卷2·太祖本纪二》"]},{"side":"对立方","t":"元顺帝、脱脱及元朝诸军。","s":["《元史·卷42·顺帝本纪五》","《明史·卷1·太祖本纪一》","《明史·卷2·太祖本纪二》"]}],"cities":["南京（建业、建康、金陵、应天、天京）","北京（蓟、幽州、燕京、中都、大都、北平、京师）"],"people":["韩山童","刘福通","韩林儿","徐寿辉","郭子兴","明太祖","陈友谅","元顺帝","徐达"],"battles":["鄱阳湖之战","明军攻占大都"],"src":["《元史·卷42·顺帝本纪五》","《明史·卷1·太祖本纪一》","《明史·卷2·太祖本纪二》"],"line":"元末红巾各军相继起事，形成多个政权，朱元璋在争夺中建立明朝，元廷最终退出大都。","group":"起义与民变","short":"红巾军起义","timeShort":"1351—1368","placeShort":"安徽、河南、湖北、江苏等地","peopleShort":"韩山童、刘福通、徐寿辉、朱元璋","result":"元失中原，明朝建立"},{"name":"邓茂七起义","tags":["农民起义","民变"],"g":"通说","lat":26.4,"lon":117.8,"f":[{"k":"时间","v":"1448—1449。","s":["《明史·卷165·丁瑄传》"]},{"k":"地点","v":"福建省三明市沙县区、南平市延平区、尤溪县等地；古名沙县、延平、尤溪。","s":["《明史·卷165·丁瑄传》"]},{"k":"规模与伤亡","v":"《明史》史书所记邓茂七部为“数万人”，所陷“二十余县”；前者是起事扩张阶段的概数，后者是该传列举的县级范围。","s":["《明史·卷165·丁瑄传》"]},{"k":"起因","v":"福建为防地方武装，曾把村民编甲，准许甲长置备兵器。邓茂七成为甲长后，反对佃户交租之外再向田主馈送，并要求田主自行收粮，田主因而向县里控诉。官府追捕引起冲突，弓兵和后续官军被杀伤；地方官员的贪索又加重不满，使原来的租佃争执扩展为大规模起事。","s":["《明史·卷165·丁瑄传》"]},{"k":"结果与影响","v":"邓茂七败亡后，继起部众仍继续抵抗，明军增兵才逐步压下局势。事件集中显示佃租之外的馈送负担、地方编甲武装和官府捕治如何相互激化。朝廷在镇压后恢复州县控制，参与进剿的文武官员则因战功、失职和冒功受到不同处置；起事者的具体诉求主要保存在镇压官员的传记中。","s":["《明史·卷165·丁瑄传》"]},{"k":"史料说明","v":"《明史·丁瑄传》将起事根由具体写到佃租、馈送与追捕。“铲平王”为书中所载自号；浙江同时存在其他起事，邓茂七本部以福建为中心。","s":["《明史·卷165·丁瑄传》"]}],"steps":[{"t":"邓茂七带头改变佃户交租、馈送的惯例，县里传捕而他拒不到案。巡检派弓兵追摄，冲突中数人被杀，官府继而增兵，地方纠纷转成公开的武装对抗。","s":["《明史·卷165·丁瑄传》"]},{"t":"起事队伍击败前来搜捕的官军，杀死巡检、知县等，吸引更多人员参加。邓茂七自称铲平王，设置官属，向周边州县发展，延平成为官民争夺的要地。","s":["《明史·卷165·丁瑄传》"]},{"t":"1448年队伍围延平，官员登城劝谕，起事者提出赦罪、免役后解散的条件。朝廷命丁瑄招讨，又派刘聚、张楷所统军队接应，招抚与进剿同时进行。","s":["《明史·卷165·丁瑄传》"]},{"t":"丁瑄转到沙县，安排地方官与军队占据要害，击败试图建立新寨的起事部众。官军逐渐熟悉各部活动路线，地方民兵也参与阻截，起事队伍的扩张受到限制。","s":["《明史·卷165·丁瑄传》"]},{"t":"1449年旧历二月，邓茂七再次攻延平，遭丁瑄所部击败，逃走时被刘福追斩。丁瑄继续招抚随从，追捕其他首领，主力失去最初领袖。","s":["《明史·卷165·丁瑄传》"]},{"t":"邓伯孙等仍率余部活动，朝廷又以陈懋等统军进剿，主要据点随后被攻破。官军内部还出现冒报战功争议，张楷等受到追究，镇压的功劳分配也进入朝廷审查。","s":["《明史·卷165·丁瑄传》"]}],"who":[{"side":"发动方","t":"邓茂七、邓伯孙等。","s":["《明史·卷165·丁瑄传》"]},{"side":"对立方","t":"丁瑄、刘福、陈懋、张楷。","s":["《明史·卷165·丁瑄传》"]}],"cities":[],"people":["邓茂七","邓伯孙","丁瑄","陈懋","明英宗"],"battles":[],"src":["《明史·卷165·丁瑄传》"],"line":"邓茂七在福建发动起事，抗拒官府并吸引各地响应，明廷调军围攻，首领相继败亡后局势平定。","group":"起义与民变","short":"邓茂七","timeShort":"1448—1449","placeShort":"福建沙县、延平等地","peopleShort":"邓茂七、邓伯孙、张楷","result":"首领败亡，起事被镇压"},{"name":"刘六刘七起义","tags":["民变","关键转折"],"g":"通说","lat":39.1,"lon":116.4,"f":[{"k":"时间","v":"1510—1512。","s":["《明史·卷187·马中锡陆完传》"]},{"k":"地点","v":"河北省廊坊市霸州市、山东省、河南省及江苏省南通市一带；古名霸州、山东、狼山。","s":["《明史·卷187·马中锡陆完传》"]},{"k":"起因","v":"明武宗时北方地方武装与流动人员聚集，霸州刘六、刘七等开始起事，队伍在畿辅和山东之间扩展。地方官军追讨失利，招抚又未能使首领解散，其他队伍陆续加入。朝廷最初沿用地方围捕，后来改调边军、安排河防和城寨，起事由局部治安冲突变成横跨数省的军事危机。","s":["《明史·卷187·马中锡陆完传》"]},{"k":"结果与影响","v":"起事各军未能建立稳定政权，在边军追击、河道封锁和水陆合围下相继失败。战争从河北扩展到长江下游，暴露州县守备和最初招抚办法的不足。朝廷依靠调边军、组织民间城寨和保护运道恢复秩序，陆完等因功晋升；军事胜利之后，北方地方社会遭受的损失仍需长期恢复。","s":["《明史·卷187·马中锡陆完传》"]},{"k":"史料说明","v":"《明史》本传以刘宠、刘宸记刘六、刘七，又把杨虎、刘惠、赵鐩等分路行动合叙；各部曾经联合，领导和行军方向并非一直相同。","s":["《明史·卷187·马中锡陆完传》"]}],"steps":[{"t":"1510年刘六、刘七等在霸州一带聚众，此后与齐彦名、杨虎、刘惠等队伍合流或配合作战。部众流动迅速，突破州县守备，北方各地不断告急。","s":["《明史·卷187·马中锡陆完传》"]},{"t":"朝廷派马中锡等主持招抚、进剿，起事首领一度与官员交涉，却仍继续行动。官军久未取得决定结果，地方城邑和交通受到反复冲击，朝廷遂追究主帅责任。","s":["《明史·卷187·马中锡陆完传》"]},{"t":"1511年陆完接替统兵，朝廷调入边将、骑兵，又命地方筑寨、守城、护运。起事者围绕官军的部署转移，有的逼近京畿，使朝廷加强皇帝出行和都城周围的警备。","s":["《明史·卷187·马中锡陆完传》"]},{"t":"刘六等向山东、河南活动，赵鐩等另领部众，队伍分路突进。官军利用边军追击，又扼守黄河、太行等要道，迫使起事各部不断变换方向，难以固定立足。","s":["《明史·卷187·马中锡陆完传》"]},{"t":"1512年陆完等逐步击破主要队伍，刘六败亡，赵鐩被捕。刘七、齐彦名所部转入舟船，从黄州顺流东下，抵达镇江附近，南京和江南沿线随之告急。","s":["《明史·卷187·马中锡陆完传》"]},{"t":"官军集中水陆力量追击，刘七等在风暴中弃舟退保狼山。陆完遣军登山进攻，齐彦名战死，刘七中箭后投水，主要首领先后败亡，跨省流动作战结束。","s":["《明史·卷187·马中锡陆完传》"]}],"who":[{"side":"发动方","t":"刘六、刘七、齐彦名、杨虎、刘惠、赵鐩。","s":["《明史·卷187·马中锡陆完传》"]},{"side":"对立方","t":"明武宗、马中锡、陆完、仇钺、许泰。","s":["《明史·卷187·马中锡陆完传》"]}],"cities":[],"people":["刘六","刘七","赵鐩","马中锡","陆完","明武宗"],"battles":[],"src":["《明史·卷187·马中锡陆完传》"],"line":"刘六刘七在北方聚众起事，各路队伍转战数省，明廷调边军追剿，起事首领相继败亡。","group":"起义与民变","short":"刘六刘七","timeShort":"1510—1512","placeShort":"河北、山东、河南、江苏等地","peopleShort":"刘六、刘七、赵鐩、陆完","result":"各路队伍相继败亡"},{"name":"明末农民战争","tags":["农民起义","改朝换代"],"g":"部分待核","lat":34.8,"lon":113.6,"f":[{"k":"时间","v":"1628—1645。","s":["《明史·卷309·流贼传》"]},{"k":"地点","v":"陕西省、河南省、北京市及四川省成都市一带；古名陕北、中州、北京、成都。","s":["《明史·卷309·流贼传》"]},{"k":"起因","v":"明末陕西等地发生饥荒，边军缺饷，部分士兵哗变，饥民与地方武装相继举事。明廷同时面对边疆战争和内部财政困境，调兵、加派又使州县更加困难。招抚与进剿交替，各部有时受降、有时再起，队伍在西北、中原、湖广之间流动，地方危机逐渐汇成影响王朝存亡的战争。","s":["《明史·卷309·流贼传》"]},{"k":"结果与影响","v":"李自成直接推翻明朝北京朝廷，并建立大顺，张献忠另立大西，故带改朝换代标签。北京失守后，明宗室在南方继续建政，清朝又在与大顺的战争中入主北京。明末各军的活动因而跨越明、清权力转换，1645年李自成败亡只是一个收束节点，大西及其他余部的结局还在其后。","s":["《明史·卷309·流贼传》"]},{"k":"史料说明","v":"李自成死于通城九宫山的具体经过及异说仍须分别核对，〔待核〕。事件按清单收至1645年，张献忠1646年败亡及南明、余部活动另作后续交代。","s":["《明史·卷309·流贼传》"]}],"steps":[{"t":"1628年前后，陕西饥荒与军队欠饷交织，王嘉胤、高迎祥等聚众，其他队伍不断加入。明廷派总督、巡抚进剿，起事者受到压力后转入山西、河南等地。","s":["《明史·卷309·流贼传》"]},{"t":"各部在流动作战中分合，李自成随高迎祥发展，张献忠另率队伍活动。高迎祥被捕杀后，李自成继续以闯王为号；明军先后取得局部胜利，却未能消灭全部武装。","s":["《明史·卷309·流贼传》"]},{"t":"杨嗣昌推行围剿，洪承畴、孙传庭等出兵，各军一度陷入低谷。李自成受挫后重新进入河南，利用饥荒中扩大的民众支持发展兵力；张献忠受抚后又起，继续转战。","s":["《明史·卷309·流贼传》"]},{"t":"李自成取得襄阳、西安等地，建立官属，1644年以大顺名义建政；张献忠则向四川发展，在成都建立大西政权。原来流动的队伍开始争取稳定的统治中心。","s":["《明史·卷309·流贼传》"]},{"t":"1644年李自成军进入北京，明思宗自尽，明朝北京朝廷覆亡。大顺随即与吴三桂、清军交战，山海关失利后退出北京，清军占领京师，战争的主要对手发生变化。","s":["《明史·卷309·流贼传》"]},{"t":"1645年李自成退出西安，转入湖北后败亡，死亡经过各书有别。张献忠在四川的活动仍延续到1646年，顺、西余部也继续抵抗，清军入关后的统一战争尚未结束。","s":["《明史·卷309·流贼传》"]}],"who":[{"side":"发动方","t":"高迎祥、李自成、张献忠等。","s":["《明史·卷309·流贼传》"]},{"side":"对立方","t":"明思宗、杨嗣昌、洪承畴、孙传庭；后与清军交战。","s":["《明史·卷309·流贼传》"]}],"cities":["西安（丰镐、长安）","成都","北京（蓟、幽州、燕京、中都、大都、北平、京师）"],"people":["李自成","张献忠","高迎祥","明思宗","洪承畴","孙传庭","吴三桂"],"battles":["李自成攻陷北京","山海关之战"],"src":["《明史·卷309·流贼传》"],"line":"明末起事从西北扩展，李自成与张献忠分别建政，明朝北京朝廷覆亡后，各军又与清军交战。","group":"起义与民变","short":"明末农民战争","timeShort":"1628—1645","placeShort":"陕西、河南、北京、四川等地","peopleShort":"李自成、张献忠、明清诸将","result":"明北京朝廷覆亡，顺西政权兴起"},{"name":"林爽文起义","tags":["宗教与会党","民变"],"g":"通说","lat":24.0,"lon":120.7,"f":[{"k":"时间","v":"1786—1788。","s":["《钦定平定台湾纪略》","《清史稿·卷330·福康安传》"]},{"k":"地点","v":"台湾彰化县、台中市大里区、嘉义市及台南市一带；古名彰化、大里杙、诸罗、台湾府城。","s":["《钦定平定台湾纪略》","《清史稿·卷330·福康安传》"]},{"k":"起因","v":"台湾地方会党借结盟、互助和乡里关系组织人员，林爽文等在彰化一带发展天地会。官府查拿会众，双方发生冲突，逮捕行动引出武装抗拒。会党网络使人员迅速聚集，部分地方官和驻军又未能及时控制局势；起事扩大后，南部庄大田响应，台湾南北的州县和交通均受冲击。","s":["《钦定平定台湾纪略》","《清史稿·卷330·福康安传》"]},{"k":"结果与影响","v":"林爽文、庄大田先后被俘，清朝恢复台湾主要城邑的秩序，天地会在本次起事中建立的军事中心被摧毁。战争揭露驻军调度、地方行政和会党动员之间的紧张关系。清廷随后整顿官吏、驻防与屯丁，嘉义之名也由此次守城而来；不同地方人群在战争中的立场并不一致。","s":["《钦定平定台湾纪略》","《清史稿·卷330·福康安传》"]},{"k":"史料说明","v":"《钦定平定台湾纪略》汇录清廷谕旨、奏报、供词，以“逆匪”“义民”等分别命名交战者，反映朝廷立场。《清史稿》另记将领争功和官军内部失误。","s":["《钦定平定台湾纪略》","《清史稿·卷330·福康安传》"]}],"steps":[{"t":"1786年冬，官府查拿林爽文及会众，搜捕与抗拒不断升级。林爽文等聚集部众，攻击官军，进入彰化，地方官员被杀，行动从会党抗捕发展为公开占城。","s":["《钦定平定台湾纪略》","《清史稿·卷330·福康安传》"]},{"t":"起事队伍利用既有结盟和乡里联系继续扩大，分兵攻取附近地方，庄大田在南部响应。官军退保据点，北部、南部各有主战区，参与者与地方关系也各不相同。","s":["《钦定平定台湾纪略》","《清史稿·卷330·福康安传》"]},{"t":"清廷从福建等地调兵渡海，最初将领分守府城、鹿港，互相观望，未能迅速解决战事。皇帝更换统帅，追究失职，增调官军，战争转为持续的大规模动员。","s":["《钦定平定台湾纪略》","《清史稿·卷330·福康安传》"]},{"t":"林爽文部长期围攻诸罗，柴大纪组织守城，援兵一时难以解围。清高宗为表彰守御，将诸罗改名嘉义，围城与救援遂成为清廷调度兵力的重点。","s":["《钦定平定台湾纪略》","《清史稿·卷330·福康安传》"]},{"t":"1787年福康安与海兰察率军到达，突破阻截，解嘉义之围。官军继续北进，进攻林爽文据点，利用地方协助与各路堵截，压缩起事队伍活动范围。","s":["《钦定平定台湾纪略》","《清史稿·卷330·福康安传》"]},{"t":"1788年林爽文被捕，随后庄大田也被俘，主要起事告终。清廷在处置首领之外整顿地方军政，募原住民屯丁、清理吏治和邮政，试图加强对乡村及交通的控制。","s":["《钦定平定台湾纪略》","《清史稿·卷330·福康安传》"]}],"who":[{"side":"发动方","t":"林爽文、庄大田、天地会部众。","s":["《钦定平定台湾纪略》","《清史稿·卷330·福康安传》"]},{"side":"对立方","t":"清高宗、常青、柴大纪、福康安、海兰察。","s":["《钦定平定台湾纪略》","《清史稿·卷330·福康安传》"]}],"cities":[],"people":["林爽文","庄大田","福康安","海兰察","清高宗"],"battles":[],"src":["《钦定平定台湾纪略》","《清史稿·卷330·福康安传》"],"line":"林爽文在台湾借天地会组织起事，庄大田在南部响应，清廷渡海增兵后俘获首领，恢复控制。","group":"起义与民变","short":"林爽文起义","timeShort":"1786—1788","placeShort":"台湾彰化、嘉义、台南等地","peopleShort":"林爽文、庄大田、福康安","result":"首领被俘，清廷恢复控制"},{"name":"川楚白莲教起义","tags":["宗教与会党","农民起义"],"g":"部分待核","lat":31.2,"lon":109.5,"f":[{"k":"时间","v":"1796—1804。","s":["《清史稿·卷344·勒保等传》"]},{"k":"地点","v":"湖北省宜昌市、襄阳市、四川省达州市、陕西省南部等地；古名宜昌、襄阳、川东、汉中。","s":["《清史稿·卷344·勒保等传》"]},{"k":"起因","v":"白莲教等秘密宗教在多个省份传播，清廷大索教徒，官吏办案株连、借机扰民。《清史稿》记川楚百姓又受军需征调困扰，禁私盐、私铸等行动也冲击部分人的生计。宗教网络与地方不满相结合，各地相继聚众，官军追捕把原本分散的教案推向跨省武装对抗。","s":["《清史稿·卷344·勒保等传》"]},{"k":"结果与影响","v":"主要起事队伍被镇压，清廷保住对川楚陕的统治，却付出多年军事动员和财政支出。战争过程中，八旗、绿营将领的协同与纪律受到质疑，地方寨堡、团练承担更大作用。官府搜捕造成民扰、战时征取又加重困难的记述，也被保存进镇压者的传记，显示教案与地方治理危机相互激化。","s":["《清史稿·卷344·勒保等传》"]},{"k":"史料说明","v":"白莲教是当时官府对多个秘密宗教支系的归类，各部名号、首领和行动相互交错。《清史稿》既使用“教匪”称呼，也明确记载搜捕株连、军需民扰等背景。王聪儿在本传作齐王氏，其姓名与称谓对应仍待专题核对，〔待核〕。","s":["《清史稿·卷344·勒保等传》"]}],"steps":[{"t":"1796年湖北多地起事，队伍在宜昌、襄阳等地扩展，四川、陕西也有响应。各首领各领部众，利用山地与省界转移，清军需要在多路之间分配兵力。","s":["《清史稿·卷344·勒保等传》"]},{"t":"王聪儿、姚之富等率队离开原有据点，在川楚陕之间流动作战，其他队伍也不断分合。官军虽取得局部战果，却常因追击、供给和统属问题难以协同。","s":["《清史稿·卷344·勒保等传》"]},{"t":"1798年前后，王聪儿、姚之富所部受围剿而败亡，四川徐天德、冉天元等仍继续作战。一个首领的失败没有使全局结束，分散队伍仍能转移和重新聚集。","s":["《清史稿·卷344·勒保等传》"]},{"t":"清廷调整统帅与节制关系，先后令勒保、额勒登保等统筹军务。将领既遭遇战场困难，也受到粮饷、虚报、迁延等问题的审查，军政失序成为朝廷整顿的对象。","s":["《清史稿·卷344·勒保等传》"]},{"t":"官军与地方官推行筑寨、团练和清野，收拢人口、粮食与牲畜，试图切断流动队伍的补给。勒保建议将四川做法推广到邻省，又请求蠲免受战事地区的钱粮。","s":["《清史稿·卷344·勒保等传》"]},{"t":"各军随后集中追剿，冉天元等相继败亡，余部在山地继续活动。至1804年，清廷宣布主要战事结束，长期跨省战争逐渐收束，地方驻防和善后仍需继续办理。","s":["《清史稿·卷344·勒保等传》"]}],"who":[{"side":"发动方","t":"王聪儿、姚之富、徐天德、冉天元等。","s":["《清史稿·卷344·勒保等传》"]},{"side":"对立方","t":"清仁宗、勒保、额勒登保、德楞泰。","s":["《清史稿·卷344·勒保等传》"]}],"cities":[],"people":["王聪儿","姚之富","冉天元","勒保","额勒登保","德楞泰","清仁宗"],"battles":[],"src":["《清史稿·卷344·勒保等传》"],"line":"白莲教各部在川楚陕聚众起事，清军长期追剿并动员地方团练，战争延续多年，耗费大量财政。","group":"起义与民变","short":"川楚白莲教起义","timeShort":"1796—1804","placeShort":"湖北、四川、陕西等地","peopleShort":"王聪儿、姚之富、清军诸将","result":"主要队伍陆续被镇压"},{"name":"太平天国运动","tags":["宗教与会党","农民起义","关键转折"],"g":"部分待核","lat":23.6,"lon":110.1,"f":[{"k":"时间","v":"1851—1864。","s":["《清史稿·卷475·洪秀全传》","《清史稿·卷411·李鸿章传》","《天朝田亩制度》"]},{"k":"地点","v":"广西壮族自治区桂平市、湖南省、江苏省南京市、安徽省安庆市等地；古名金田、天京、安庆。","s":["《清史稿·卷475·洪秀全传》","《清史稿·卷411·李鸿章传》","《天朝田亩制度》"]},{"k":"起因","v":"广西地方饥荒、人口流动与社会冲突加深，洪秀全、冯云山等以拜上帝的宗教活动聚集人员，与杨秀清、韦昌辉、石达开等形成军事核心。官府搜捕和地方对抗使聚众迅速武装化，队伍在金田集中后公开起事。宗教信仰、共同生活和严格组织，成为早期团结部众的重要方式。","s":["《清史稿·卷475·洪秀全传》","《清史稿·卷411·李鸿章传》","《天朝田亩制度》"]},{"k":"结果与影响","v":"太平天国在长江中下游建立了持续多年的政权，提出独立的宗教、土地与军政安排，最终因长期内外战争、领导分裂及根据地丧失而失败。清廷虽保住统治，湘淮军将领与地方筹饷体系却因战争扩大权力。1864年天京失守是中央政权终结，其他地区余部的抵抗还延续到其后。","s":["《清史稿·卷475·洪秀全传》","《清史稿·卷411·李鸿章传》","《天朝田亩制度》"]},{"k":"史料说明","v":"《清史稿》以清廷立场记太平天国，早期宗教源流和部分死亡细节存在争议；洪秀全的具体死因〔待核〕。《天朝田亩制度》是政权公布的纲领，条文与各地实际施行情况分属不同层面。","s":["《清史稿·卷475·洪秀全传》","《清史稿·卷411·李鸿章传》","《天朝田亩制度》"]}],"steps":[{"t":"1851年洪秀全所部在广西起事，建立太平天国名号，洪秀全称天王。队伍经过永安整顿，分封诸王，军队指挥、宗教权威与官职体系逐渐联在一起。","s":["《清史稿·卷475·洪秀全传》","《清史稿·卷411·李鸿章传》","《天朝田亩制度》"]},{"t":"1852年突破广西包围，经过湖南进入长江流域，冯云山、萧朝贵先后战死。队伍仍继续北上，攻取武昌，继而沿江东下，把地方起事扩展为跨省战争。","s":["《清史稿·卷475·洪秀全传》","《清史稿·卷411·李鸿章传》","《天朝田亩制度》"]},{"t":"1853年攻取南京，改称天京，建立中央政治中心，又向北、西两路出兵。《天朝田亩制度》提出分田、国库及基层军政组织的安排，显示其试图重建社会秩序的纲领。","s":["《清史稿·卷475·洪秀全传》","《清史稿·卷411·李鸿章传》","《天朝田亩制度》"]},{"t":"1856年天京内部发生权力冲突，杨秀清、韦昌辉先后被杀，大批人员卷入；石达开后来率部离开，原有领导体系遭受重创，洪秀全重新安排官员和军队。","s":["《清史稿·卷475·洪秀全传》","《清史稿·卷411·李鸿章传》","《天朝田亩制度》"]},{"t":"陈玉成、李秀成等继续作战，西线安庆与东线苏浙成为争夺重点。清廷倚重湘军、淮军，并利用外籍武装协助，1861年安庆失守，天京与上游的联系受到严重削弱。","s":["《清史稿·卷475·洪秀全传》","《清史稿·卷411·李鸿章传》","《天朝田亩制度》"]},{"t":"1864年洪秀全在天京去世，幼主继位；清军攻破天京，中央政权瓦解。李秀成被捕，各地余部继续流动作战，运动的政治中心和主要根据地已相继丧失。","s":["《清史稿·卷475·洪秀全传》","《清史稿·卷411·李鸿章传》","《天朝田亩制度》"]}],"who":[{"side":"发动方","t":"洪秀全、杨秀清、冯云山、石达开、李秀成、陈玉成。","s":["《清史稿·卷475·洪秀全传》","《清史稿·卷411·李鸿章传》","《天朝田亩制度》"]},{"side":"对立方","t":"清文宗、清穆宗、曾国藩、曾国荃、李鸿章等。","s":["《清史稿·卷475·洪秀全传》","《清史稿·卷411·李鸿章传》","《天朝田亩制度》"]}],"cities":["南京（建业、建康、金陵、应天、天京）"],"people":["洪秀全","杨秀清","冯云山","石达开","李秀成","陈玉成","曾国藩","曾国荃","李鸿章","清文宗","清穆宗"],"battles":["天京陷落"],"src":["《清史稿·卷475·洪秀全传》","《清史稿·卷411·李鸿章传》","《天朝田亩制度》"],"line":"洪秀全等在广西起事后建立太平天国并定都天京，内争与长期战争削弱实力，天京最终失守。","group":"起义与民变","short":"太平天国运动","timeShort":"1851—1864","placeShort":"广西、湖南、江苏、安徽等地","peopleShort":"洪秀全、杨秀清、曾国藩","result":"天京失守，中央政权瓦解"},{"name":"捻军起义","tags":["民变","关键转折"],"g":"部分待核","lat":33.5,"lon":116.2,"f":[{"k":"时间","v":"1851—1868。","s":["《清史稿·卷418·袁甲三传》","《清史稿·卷404·僧格林沁传》","《清史稿·卷411·李鸿章传》"]},{"k":"地点","v":"安徽省亳州市、河南省、山东省及湖北省等地；古名蒙亳、豫东、鲁西、鄂北。","s":["《清史稿·卷418·袁甲三传》","《清史稿·卷404·僧格林沁传》","《清史稿·卷411·李鸿章传》"]},{"k":"起因","v":"淮北原有分散结伙的地方武装，饥荒、水患和地方秩序动摇使其活动扩大。太平军进入长江、淮河流域后，清廷兵力被多个方向牵制，捻军各部有机会联合和发展。张乐行等在蒙亳一带形成较强队伍，官军与地方团练反复进剿，战争逐步超出原有乡里活动的范围。","s":["《清史稿·卷418·袁甲三传》","《清史稿·卷404·僧格林沁传》","《清史稿·卷411·李鸿章传》"]},{"k":"结果与影响","v":"捻军在清军河防、围堵与机动作战配合下失去继续流动的空间，1868年主要队伍败亡。战争从地方结伙发展为跨省骑兵战争，吸收太平军余部后又改变了指挥和作战方式。清廷取胜进一步依赖湘淮军及地方团练，捻军的终结与太平天国的失败前后相连，也推动地方军事力量在中央政治中上升。","s":["《清史稿·卷418·袁甲三传》","《清史稿·卷404·僧格林沁传》","《清史稿·卷411·李鸿章传》"]},{"k":"史料说明","v":"张乐行在《清史稿》中常作张洛行，张宗禹作张总愚。各支早期捻党并无始终统一的建军日期；1851按清单作叙事起点，张宗禹的具体死亡经过〔待核〕。","s":["《清史稿·卷418·袁甲三传》","《清史稿·卷404·僧格林沁传》","《清史稿·卷411·李鸿章传》"]}],"steps":[{"t":"1851年前后淮北各路捻党活动加剧，后来张乐行等联合多部，在蒙亳一带发展。队伍以地方关系和各自首领维系，既有据寨防守，也有外出流动作战。","s":["《清史稿·卷418·袁甲三传》","《清史稿·卷404·僧格林沁传》","《清史稿·卷411·李鸿章传》"]},{"t":"太平军经过安徽后，捻军与其时有联合，各部仍保留自己的组织。袁甲三等统军、整团练，围绕雉河集、蒙城、临淮等地反复争夺，清廷一时难以统一控制局面。","s":["《清史稿·卷418·袁甲三传》","《清史稿·卷404·僧格林沁传》","《清史稿·卷411·李鸿章传》"]},{"t":"僧格林沁转入淮北进剿，1863年攻破重要据点，张乐行被捕杀。原有寨堡体系受到重创，其他首领继续率部活动，战争开始更依赖骑兵和长距离转移。","s":["《清史稿·卷418·袁甲三传》","《清史稿·卷404·僧格林沁传》","《清史稿·卷411·李鸿章传》"]},{"t":"1864年以后，赖文光等太平军余部与捻军合流，张宗禹、任柱等共同作战。1865年击败追击的清军，僧格林沁战死，清廷改命曾国藩主持军事，后来由李鸿章接替。","s":["《清史稿·卷418·袁甲三传》","《清史稿·卷404·僧格林沁传》","《清史稿·卷411·李鸿章传》"]},{"t":"各部逐渐分成东、西两路，东路以赖文光、任柱等为主，西路由张宗禹率领。清军凭运河、黄河等修筑防线，结合骑兵追击，试图限制行动并切断沿途粮源。","s":["《清史稿·卷418·袁甲三传》","《清史稿·卷404·僧格林沁传》","《清史稿·卷411·李鸿章传》"]},{"t":"1867年任柱死，1868年初赖文光被捕，东路瓦解；西路北进后又被多道河防阻截，活动空间逐步缩小。1868年张宗禹部在山东失败，东西两支主要队伍相继终结。","s":["《清史稿·卷418·袁甲三传》","《清史稿·卷404·僧格林沁传》","《清史稿·卷411·李鸿章传》"]}],"who":[{"side":"发动方","t":"张乐行、张宗禹、任柱、赖文光等。","s":["《清史稿·卷418·袁甲三传》","《清史稿·卷404·僧格林沁传》","《清史稿·卷411·李鸿章传》"]},{"side":"对立方","t":"僧格林沁、曾国藩、李鸿章、刘铭传等。","s":["《清史稿·卷418·袁甲三传》","《清史稿·卷404·僧格林沁传》","《清史稿·卷411·李鸿章传》"]}],"cities":[],"people":["张乐行","张宗禹","赖文光","僧格林沁","曾国藩","李鸿章","刘铭传"],"battles":[],"src":["《清史稿·卷418·袁甲三传》","《清史稿·卷404·僧格林沁传》","《清史稿·卷411·李鸿章传》"],"line":"淮北各路捻军在地方动荡中联合，后来与太平军余部合流，清军以围堵与追剿逐渐将其瓦解。","group":"起义与民变","short":"捻军起义","timeShort":"1851—1868","placeShort":"安徽、河南、山东、湖北等地","peopleShort":"张乐行、赖文光、张宗禹、李鸿章","result":"东西捻军先后败亡"},{"name":"义和团运动","tags":["宗教与会党","民变","关键转折"],"g":"通说","lat":39.9,"lon":116.4,"f":[{"k":"时间","v":"1899—1901。","s":["《清史稿·卷465·徐桐等传》","《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃传》"]},{"k":"地点","v":"山东省、河北省及北京市、天津市一带；古名山东、直隶、京师、天津。","s":["《清史稿·卷465·徐桐等传》","《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃传》"]},{"k":"起因","v":"山东地方反教冲突与拳会活动相互交织，部分地方官对拳众采取庇护态度，另一些官员则主张捕治。拳会以神术护身和排斥外国教会相号召，逐渐向直隶、京津扩展。清廷对外关系日趋紧张，朝中又有人相信可以借拳民抵抗外国，民间运动由地方纠纷进入中央外交与军事决策。","s":["《清史稿·卷465·徐桐等传》","《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃传》"]},{"k":"结果与影响","v":"义和团未能阻止外国军队占领京津，清廷在战争失败后转向镇压，并接受辛丑条约。地方反教运动、朝廷决策与列强军事干预逐步汇合，使冲突扩大成全国性政治危机。民众和教民遭到杀伤，联军占领也带来严重破坏；赔款、驻兵和惩办安排进一步削弱清廷的财政与政治处境。","s":["《清史稿·卷465·徐桐等传》","《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃传》"]},{"k":"史料说明","v":"《清史稿》对拳术神效及支持者多有批评，也使用“拳匪”等称呼。朝廷不同官员的主张、拳民各部行动和外国军队进攻各有线索，宗教神术是当时的信念与宣传。","s":["《清史稿·卷465·徐桐等传》","《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃传》"]}],"steps":[{"t":"1899年前后，山东拳会与教会、官军发生冲突，朱红灯等聚众。毓贤主政时对部分拳会加以保护，后来被调离，官府对拳民的态度在捕治和容纳之间变化。","s":["《清史稿·卷465·徐桐等传》","《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃传》"]},{"t":"拳民进入直隶、京津，地方组织不断增加，以扶清、反洋为号召，攻击教堂、教民及铁路电线等设施。各地活动没有一个统一指挥，暴力同时波及外国人和中国居民。","s":["《清史稿·卷465·徐桐等传》","《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃传》"]},{"t":"1900年清廷内部围绕招抚、镇压和对外关系争论，刚毅、载漪等支持拳民。部分官员供给兵器，团众进入京师，民间拳会与朝廷不同派系的行动进一步交织。","s":["《清史稿·卷465·徐桐等传》","《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃传》"]},{"t":"外国军队增援京津，大沽炮台失守，清廷随后对列强发布宣战诏书。使馆区遭围攻，天津发生激烈战斗，清军、拳民与外国联军之间形成多方军事冲突。","s":["《清史稿·卷465·徐桐等传》","《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃传》"]},{"t":"联军攻占天津后继续进军，八月进入北京，两宫西行。清廷转而命令捕治拳民，并在议和中处分支持拳团的大臣，原先借拳御外的政策迅速逆转。","s":["《清史稿·卷465·徐桐等传》","《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃传》"]},{"t":"1901年清廷同各国签订辛丑条约，承担赔款、驻兵与惩办等条件。义和团主要活动被镇压，外交和京畿军事安排受到重新限制，庚子危机转入条约善后。","s":["《清史稿·卷465·徐桐等传》","《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃传》"]}],"who":[{"side":"发动方","t":"义和团各部、朱红灯、曹福田、张德成等。","s":["《清史稿·卷465·徐桐等传》","《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃传》"]},{"side":"对立方","t":"外国传教与驻军势力；清廷先支持，后转镇压。","s":["《清史稿·卷465·徐桐等传》","《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃传》"]}],"cities":["北京（蓟、幽州、燕京、中都、大都、北平、京师）"],"people":["慈禧太后","清德宗","毓贤","刚毅","载漪","袁世凯","李鸿章"],"battles":[],"src":["《清史稿·卷465·徐桐等传》","《清史稿·卷24·德宗本纪二》","《清史稿·卷214·后妃传》"],"line":"义和团由地方冲突扩展到京津，清廷一度支持其行动，联军入京后转为镇压并承担条约赔款。","group":"起义与民变","short":"义和团运动","timeShort":"1899—1901","placeShort":"山东、河北、北京、天津","peopleShort":"义和团各部、慈禧太后、清廷大臣","result":"联军入京，签订辛丑条约"},{"name":"武昌起义","tags":["兵变","改朝换代"],"g":"通说","lat":30.5,"lon":114.3,"f":[{"k":"时间","v":"1911年10月—1912年2月（公历）。","s":["《清史稿·卷25·宣统皇帝本纪》","《临时政府公报·第一号·临时大总统宣言书》"]},{"k":"地点","v":"湖北省武汉市、江苏省南京市、北京市；古名武昌、南京、京师。","s":["《清史稿·卷25·宣统皇帝本纪》","《临时政府公报·第一号·临时大总统宣言书》"]},{"k":"起因","v":"清末立宪与军制改革未能平息政治矛盾，铁路国有及借款引发保路风潮，四川局势紧张，朝廷调兵入川。湖北新军中革命组织已在联络人员，秘密活动被侦破后，官府逮捕、处死相关人员，并准备继续追查。面临搜捕的军人决定先行动手，地方军队的控制因而突然崩解。","s":["《清史稿·卷25·宣统皇帝本纪》","《临时政府公报·第一号·临时大总统宣言书》"]},{"k":"结果与影响","v":"武昌起义促成各省脱离清廷，推动中华民国建立，清宣统帝于1912年退位，清朝帝制结束，故带改朝换代标签。皇帝退位由朝廷、南方代表和北洋集团多方谈判形成，皇室优待条件同时公布。地方军政力量在革命中取得更大自主权，共和建立后的统一和权力安排仍需继续解决。","s":["《清史稿·卷25·宣统皇帝本纪》","《临时政府公报·第一号·临时大总统宣言书》"]},{"k":"史料说明","v":"1911年10月10日及1912年2月12日采用公历；《清史稿》原按旧历记事。该书保存清廷谕旨，也以清廷立场称“革命党”“民军”，南京建政与清帝退位前后相接。","s":["《清史稿·卷25·宣统皇帝本纪》","《临时政府公报·第一号·临时大总统宣言书》"]}],"steps":[{"t":"1911年秋，四川保路风潮扩大，清廷命端方带兵入川，湖北也办理铁路国有。地方政治不满与军事调动同时发生，武昌革命党人在新军中的活动继续进行。","s":["《清史稿·卷25·宣统皇帝本纪》","《临时政府公报·第一号·临时大总统宣言书》"]},{"t":"起事前夕，革命组织计划暴露，湖广总督瑞澂报告捕获人员、处死三人，朝廷仍令继续追查。新军中相关军人面临被捕危险，行动由秘密准备转为紧急发动。","s":["《清史稿·卷25·宣统皇帝本纪》","《临时政府公报·第一号·临时大总统宣言书》"]},{"t":"10月10日晚武昌新军起事，官兵攻占重要军政据点，瑞澂逃离，提督张彪退走。起事者取得武昌，随后进入汉阳、汉口，武汉三镇成为新的政治和军事中心。","s":["《清史稿·卷25·宣统皇帝本纪》","《临时政府公报·第一号·临时大总统宣言书》"]},{"t":"起事军民推黎元洪为都督，设置湖北军政府，各省陆续宣布独立。清廷调军反攻，并起用袁世凯统筹湖北及援军，地方起事迅速引出全国范围的政权危机。","s":["《清史稿·卷25·宣统皇帝本纪》","《临时政府公报·第一号·临时大总统宣言书》"]},{"t":"北洋军取得汉口、汉阳，武昌仍由革命方面控制，双方开始停战交涉。清廷改组内阁、调整摄政安排，南方各省同时讨论组织全国政府，军事与议和两条线并行。","s":["《清史稿·卷25·宣统皇帝本纪》","《临时政府公报·第一号·临时大总统宣言书》"]},{"t":"1912年南京建立中华民国临时政府，孙中山任临时大总统。南北议和与北方将领压力持续，2月12日清帝退位，清廷交出统治权，革命进入共和政权整合的新阶段。","s":["《清史稿·卷25·宣统皇帝本纪》","《临时政府公报·第一号·临时大总统宣言书》"]}],"who":[{"side":"发动方","t":"湖北新军革命党人、黎元洪及响应各省。","s":["《清史稿·卷25·宣统皇帝本纪》","《临时政府公报·第一号·临时大总统宣言书》"]},{"side":"对立方","t":"清宣统帝、摄政王载沣、清廷；袁世凯兼掌军政与议和。","s":["《清史稿·卷25·宣统皇帝本纪》","《临时政府公报·第一号·临时大总统宣言书》"]}],"cities":["南京（建业、建康、金陵、应天、天京）","北京（蓟、幽州、燕京、中都、大都、北平、京师）"],"people":["黎元洪","孙中山","袁世凯","清宣统帝","载沣","黄兴"],"battles":[],"src":["《清史稿·卷25·宣统皇帝本纪》","《临时政府公报·第一号·临时大总统宣言书》"],"line":"武昌新军起事后各省相继脱离清廷，南京建立中华民国，南北议和推动清帝退位，帝制结束。","group":"起义与民变","short":"武昌起义","timeShort":"1911—1912","placeShort":"湖北武汉；江苏南京；北京","peopleShort":"黎元洪、孙中山、袁世凯、清宣统帝","result":"民国建立，清帝退位"}],"systems":[{"title":"宫廷政变的几种类型","paras":[{"t":"宫廷政变常围绕宫门、诏令、军队和继承名分展开。玄武门之变由伏兵杀死竞争者开始，高平陵之变则趁皇帝出城时夺取京师控制权，两者都先改变武力配置，再处理朝廷名位。","s":["《资治通鉴·卷191·唐纪七》","《晋书·卷1·宣帝纪》"]},{"t":"废立也可以通过官员集体行动推进，神龙政变拥唐中宗复位，陈桥兵变由军中拥立转入后周禅位。诸吕被诛牵涉外戚、宗室与功臣，魏忠贤专权涉及近侍及其官僚依附者，八王之乱则不断借宗室身份争夺中央。不同类型可以出现在同一事件中，胜负往往同时取决于谁能发号令、谁有兵力执行。","s":["《资治通鉴·卷207·唐纪二十三》","《宋史·卷1·太祖本纪一》","《史记·卷9·吕太后本纪》","《明史·卷305·宦官传二》","《晋书·卷59·八王列传》"]}],"note":"","table":null},{"title":"外戚与宦官为什么能专权","paras":[{"t":"外戚的地位首先来自皇室婚姻，又可通过太后临朝、出任大将军和主持辅政进入政务中心。东汉窦武、何进都凭外戚身份掌握重要军政职务，诛宦官的计划又受到宫内消息和禁军行动的牵制。","s":["《后汉书·卷69·窦何列传》"]},{"t":"宦官长期在宫中侍奉，掌握皇帝与外廷之间的传达通道，幼帝、太后依赖近侍时，他们更易参与机密。《后汉书》记郑众帮助和帝清除窦宪后受重用；唐代甘露之变中，宦官又能控制神策军反击。亲近君主、参与诏命和掌握武力相结合，才使近侍权力能够越出宫廷日常事务。","s":["《后汉书·卷78·宦者列传》","《资治通鉴·卷245·唐纪六十一》"]}],"note":"","table":null},{"title":"党争与朝议","paras":[{"t":"朝议围绕政策、官员任用和政治责任展开，争论也会发展为对人物交往的追查。东汉党锢中，士人批评宦官与地方官，又被朝廷指为结党，禁仕和株连扩大到亲属、门生及交游。","s":["《后汉书·卷67·党锢列传》"]},{"t":"北宋新旧党争以新法的利弊为起点，皇位和辅政安排更替后，用人、法令随之反复，后来又形成元祐党籍。明代东林与魏忠贤集团的冲突，则涉及奏疏、铨选和厂卫审讯，杨涟、左光斗等在诏狱中死亡。争论进入党籍、逮捕和禁仕程序后，原来的政策问题又叠加了人身与仕途风险。","s":["《宋史·卷327·王安石传》","《宋史·卷336·司马光传》","《宋史·卷472·蔡京传》","《明史·卷244·杨涟、左光斗传》","《明史·卷305·宦官传二》"]}],"note":"","table":null},{"title":"起义的类型","paras":[{"t":"起义队伍的成员和组织往往有多种来源。绿林诸部从饥荒中争食、调解纠纷发展起来，明末军队欠饷、饥民聚集与地方武装相互汇合，显示生计危机可以逐步转化为军事行动。","s":["《后汉书·卷11·刘玄刘盆子列传》","《明史·卷309·流贼传》"]},{"t":"黄巾依靠太平道的跨地区传教网络，林爽文借天地会联系会众，宗教与会党为聚众提供了关系和号召。庞勋起事由戍卒换防问题引发，武昌则由新军行动扩大到各省独立；国人暴动又发生在王都政治秩序内部。农民、军人、会众与地方居民可能共同参加，标签标示主要线索，各部仍有自己的成员和首领。","s":["《后汉书·卷71·皇甫嵩朱儁列传》","《钦定平定台湾纪略》","《资治通鉴·卷251·唐纪六十七》","《清史稿·卷25·宣统皇帝本纪》","《史记·卷4·周本纪》"]}],"note":"","table":null},{"title":"史书怎样称呼起义者与镇压者","paras":[{"t":"古书常把挑战本朝统治的队伍称为贼、寇，把镇压者称为官军、王师。《后汉书》将黄巾置于皇甫嵩、朱儁等人的军事功绩中，《清史稿》又以粵寇等称太平军，叙述重心随编史立场而变化。","s":["《后汉书·卷71·皇甫嵩朱儁列传》","《清史稿·卷475·洪秀全传》"]},{"t":"“义”也由各方用来说明自身行动的正当性：起事者可以用复国、救民号召部众，清廷又把协助官军的地方人群称为义民。读这些称呼时，还要同时看谁组织、谁供粮、谁被杀伤，以及记载来自奏报、供词还是当事方文书；《天朝田亩制度》所用的官号、国库与礼拜组织，呈现的便是太平天国自身的制度语言。","s":["《史记·卷48·陈涉世家》","《钦定平定台湾纪略》","《天朝田亩制度》"]}],"note":"","table":null},{"title":"起义与王朝更替的关系","paras":[{"t":"起义可以直接摧毁中央政权，也可以先削弱王朝，再由其他力量完成替代。更始军进入长安、王莽被杀，新朝随之灭亡；李自成军进入北京，明思宗自尽，北京明廷覆亡，而南方明宗室仍继续建政。","s":["《后汉书·卷11·刘玄刘盆子列传》","《明史·卷309·流贼传》"]},{"t":"红巾诸部中发展起来的明太祖最后建立明朝，元廷退出大都；武昌起义引发各省响应，南北议和又促成清帝退位。黄巾主要首领败亡后东汉仍在，黄巢大齐失败后唐廷也恢复长安。事件与改朝换代之间有不同距离：建立新政权、推翻旧朝中央、削弱其控制，是可以分别追踪的结果。","s":["《明史·卷1·太祖本纪一》","《明史·卷2·太祖本纪二》","《清史稿·卷25·宣统皇帝本纪》","《后汉书·卷71·皇甫嵩朱儁列传》","《旧唐书·卷200下·黄巢传》"]}],"note":"","table":null},{"title":"本页与《战役》页的对应","paras":[{"t":"下表按事件卡的“关联战役”字段列出；同一事件可以对应多张战役卡。八王之乱与永嘉洛阳陷落、隋末战争与虎牢的对应包含后续局势，夺门与土木堡的对应则属于前因。","s":[]}],"note":"","table":{"head":["事件","相关战役"],"rows":[[{"t":"八王之乱","s":[]},{"t":"永嘉之乱与洛阳陷落","s":[]}],[{"t":"新旧党争","s":[]},{"t":"靖康之战与汴京陷落","s":[]}],[{"t":"夺门之变","s":[]},{"t":"土木堡之战","s":[]}],[{"t":"绿林赤眉起义","s":[]},{"t":"昆阳之战","s":[]}],[{"t":"隋末农民战争","s":[]},{"t":"虎牢之战","s":[]}],[{"t":"黄巢起义","s":[]},{"t":"黄巢攻陷长安","s":[]}],[{"t":"红巾军起义","s":[]},{"t":"鄱阳湖之战、明军攻占大都","s":[]}],[{"t":"明末农民战争","s":[]},{"t":"李自成攻陷北京、山海关之战","s":[]}],[{"t":"太平天国运动","s":[]},{"t":"天京陷落","s":[]}]]}},{"title":"改朝换代事件一览","paras":[],"note":"","table":{"head":["事件名","被取代或灭亡的政权","兴起的政权","年份","一句话"],"rows":[[{"t":"田氏代齐","s":[]},{"t":"姜齐的齐侯统治","s":[]},{"t":"田齐","s":[]},{"t":"前386；姜齐末君仍留一城","s":[]},{"t":"田氏从齐国大夫逐步掌握国政，杀君、控制城邑，最终取代姜氏取得齐侯名分。","s":["《史记·卷46·田敬仲完世家》"]}],[{"t":"王莽篡汉","s":[]},{"t":"西汉","s":[]},{"t":"新","s":[]},{"t":"8","s":[]},{"t":"王莽从外戚辅政走向居摄，借符命与群臣劝进称帝，废止汉朝帝号，建立新朝。","s":["《汉书·卷99上·王莽传上》","《汉书·卷99中·王莽传中》"]}],[{"t":"神龙政变","s":[]},{"t":"武周","s":[]},{"t":"唐（恢复国号）","s":[]},{"t":"705","s":[]},{"t":"张柬之等联结禁军入宫诛杀张氏兄弟，拥唐中宗复位，武周结束，唐朝国号恢复。","s":["《资治通鉴·卷207·唐纪二十三》"]}],[{"t":"陈桥兵变","s":[]},{"t":"后周","s":[]},{"t":"宋","s":[]},{"t":"960","s":[]},{"t":"北宋太祖领兵出京，在陈桥驿被部将拥立，随后返城接受后周禅位，建立宋朝政权。","s":["《宋史·卷1·太祖本纪一》"]}],[{"t":"绿林赤眉起义","s":[]},{"t":"新","s":[]},{"t":"更始汉政权；其后东汉兴起","s":[]},{"t":"23；更始25年亡，赤眉27年降","s":[]},{"t":"绿林与赤眉从地方起事发展成大军，绿林系统推立更始帝并推翻新朝，两军后来相继败亡。","s":["《后汉书·卷11·刘玄刘盆子列传》","《后汉书·卷1上·光武帝纪上》"]}],[{"t":"隋末农民战争","s":[]},{"t":"隋中央统治；洛阳隋廷延至619","s":[]},{"t":"唐及多个地方政权","s":[]},{"t":"618；地方战争继续","s":[]},{"t":"隋末各地起事在征役与饥荒中扩展，瓦岗等势力冲击隋朝统治，隋亡后群雄仍继续争夺。","s":["《隋书·卷70·李密传》","《旧唐书·卷54·窦建德传》","《旧唐书·卷56·杜伏威传》","《隋书·卷4·炀帝纪下》","《旧唐书·卷1·高祖本纪》"]}],[{"t":"红巾军起义","s":[]},{"t":"元在中原的中央统治","s":[]},{"t":"明","s":[]},{"t":"1368","s":[]},{"t":"元末红巾各军相继起事，形成多个政权，朱元璋在争夺中建立明朝，元廷最终退出大都。","s":["《元史·卷42·顺帝本纪五》","《明史·卷1·太祖本纪一》","《明史·卷2·太祖本纪二》"]}],[{"t":"明末农民战争","s":[]},{"t":"明北京朝廷；南明仍延续","s":[]},{"t":"大顺、大西；清随后入主北京","s":[]},{"t":"1644","s":[]},{"t":"明末起事从西北扩展，李自成与张献忠分别建政，明朝北京朝廷覆亡后，各军又与清军交战。","s":["《明史·卷309·流贼传》"]}],[{"t":"武昌起义","s":[]},{"t":"清朝帝制","s":[]},{"t":"中华民国","s":[]},{"t":"1912；起义始于1911","s":[]},{"t":"武昌新军起事后各省相继脱离清廷，南京建立中华民国，南北议和推动清帝退位，帝制结束。","s":["《清史稿·卷25·宣统皇帝本纪》","《临时政府公报·第一号·临时大总统宣言书》"]}]]}}],"checks":[{"name":"王小波李顺起义","q":"史料说明","why":"“均贫富”据《宋史纪事本末》所记王小波号召。该书记成都破后李顺被获，后世对其结局另有讨论，具体逃脱说的史料对应待核。原因：逃脱说的具体古籍依据与《宋史纪事本末》所记被获结局，尚未逐项比对。"},{"name":"明末农民战争","q":"史料说明","why":"李自成死于通城九宫山的具体经过及异说仍须分别核对，待核。事件按清单收至1645年，张献忠1646年败亡及南明、余部活动另作后续交代。原因：李自成最后行踪、死亡方式及不同地点记载尚未完成逐书比对。"},{"name":"川楚白莲教起义","q":"史料说明","why":"白莲教是当时官府对多个秘密宗教支系的归类，各部名号、首领和行动相互交错。《清史稿》既使用“教匪”称呼，也明确记载搜捕株连、军需民扰等背景。王聪儿在本传作齐王氏，其姓名与称谓对应仍待专题核对，待核。原因：《清史稿》以齐王氏记其人，王聪儿这一姓名与该称谓的原始文献对应尚待核对。"},{"name":"太平天国运动","q":"史料说明","why":"《清史稿》以清廷立场记太平天国，早期宗教源流和部分死亡细节存在争议；洪秀全的具体死因待核。《天朝田亩制度》是政权公布的纲领，条文与各地实际施行情况分属不同层面。原因：《清史稿》记服毒死，具体死因及不同当事记录仍须比对；早期宗教源流也有叙事差异。"},{"name":"捻军起义","q":"史料说明","why":"张乐行在《清史稿》中常作张洛行，张宗禹作张总愚。各支早期捻党并无始终统一的建军日期；1851按清单作叙事起点，张宗禹的具体死亡经过待核。原因：《清史稿》记张总愚投水，张宗禹结局的异说及原始证据尚未逐项核对。"}]};
